(window.GIM_TS=window.GIM_TS||{})["Makkot.0"]={"from":0,"a":[["\u0003כיצד העדים נעשים זוממים?\u0004 הרי שבאו שני עדים לפני בית דין ואמרו: \u0003\"מעידין אנו באיש פלוני שהוא בן גרושה או בן חלוצה\",\u0004 שאם אביו של זה הוא כהן הרי הבן חלל ופסול לכהונה. ולאחר מכן הוזמו העדים הללו — \u0003אין אומרים: יעשה זה\u0004 כל אחד מן העדים \u0003בן גרושה או בן חלוצה תחתיו, אלא\u0004 \u0003לוקה ארבעים\u0004 מלקות כעונש על עדות שקר.","וכן אם אמרו העדים: \u0003\"מעידין אנו באיש פלוני שהוא חייב לגלות\u0004 לעיר מקלט\" משום שהרג נפש בשגגה, ולאחר מכן הוזמו העדים הללו — \u0003אין אומרים: יגלה זה\u0004 העד \u0003תחתיו, אלא לוקה\u0004 \u0003ארבעים.\u0004","ותחילה מבררים את המשפט הראשון במשנה: \u0003הא\u0004 \u0005[הרי]\u0006 בנוסח \u0003\"כיצד אין העדים נעשים זוממין\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לתנא לשנות\u0005],\u0006 שהרי כרגיל עדים זוממים נענשים כפי שזממו לעשות, ואילו כאן מובאים מקרים שבהם העדים אינם נענשים כמזימתם! \u0003ועוד\u0004 יש לשאול: \u0003מדקתני לקמן\u0004 \u0005[מ\u0006מה \u0005ששנה לפנינו,\u0006 במשנה להלן\u0005]:\u0006 \u0003אבל אמרו\u0004 המזימים \u0003להם\u0004 לעדים: \u0003\"היאך אתם מעידין\u0004 בעדות זו, ש\u0003הרי באותו יום אתם הייתם עמנו במקום פלוני\"\u0004 — \u0003הרי אלו זוממין, מכלל\u0004 הדברים נשמע שדווקא אלו הם זוממים, אבל \u0003אלו\u0004 שנמנו קודם (במשנתנו) בעדותם \u0003אין זוממין!\u0004","ומתרצים את שני הקשיים בתירוץ אחד: ה\u0003תנא התם קאי\u0004 \u0005[שם\u0006 הוא \u0005עומד]\u0006 כלומר, התנא מתייחס לדברים שבסוף מסכת סנהדרין, שמסכת מכות סמוכה ונספחת לה, ששנינו שם: \u0003כל הזוממין מקדימין לאותה מיתה\u0004 שרצו להביא על מי שהעידו עליו, \u0003חוץ מזוממי בת כהן ובועלה\u0004 כלומר, חוץ מעדים שהעידו על בת כהן אשת איש שנבעלה לאדם זר, שאם אמת הדבר דינה בשריפה, ודינו של הבועל בחנק. \u0003ש\u0004אם עדים אלו נמצאים זוממים — \u0003אין מקדימים לאותה מיתה\u0004 שזממו להמית בה את האשה, בשריפה, \u0003אלא למיתה אחרת\u0004 מיתת חנק, שממיתים בה את האיש.","ובהמשך למשנה זו בסנהדרין הוסיף התנא במשנה שלנו: \u0003ויש עדים זוממין אחרים, שאין עושין בהן דין הזמה כל עיקר,\u0004 שאינם נענשים כלל כפי שזממו לעשות, \u0003אלא\u0004 לוקים \u0003מלקות ארבעים, כיצד? \"מעידים אנו באיש פלוני שהוא בן גרושה או בן חלוצה\"\u0004 — \u0003אין אומרים יעשה זה\u0004 העד \u0003בן גרושה או בן חלוצה תחתיו, אלא לוקה את הארבעים.\u0004","עד כאן לבירור לשון המשנה, ולתוכן דברי המשנה שואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו],\u0006 שאין מקיימים דין \"כאשר זמם\" לפסול אדם מכהונה? \u0003אמר ר' יהושע בן לוי אמר ר' שמעון בן לקיש:\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ועשיתם לו כאשר זמם\"\u0004 (דברים יט, יט), ויש לדייק מן הלשון: \u0003\"לו\"\u0004 — \u0003ולא לזרעו,\u0004 ואם היינו עושים את העד חלל, נמצא שפוסלים אנו בכך גם את זרעו. ושואלים: \u0003ליפסלוהו לדידיה ולא ליפסלו לזרעיה\u0004 \u0005[שיפסלו אותו\u0006 עצמו \u0005ולא יפסלו את זרעו].\u0006 שאם העד הזומם היה כהן ידונו אותו כחלל, ויורידו אותו מכל זכויות הכהונה, אבל לא יפסלו את בניו אחריו! ומשיבים: גם אם נעשה כן לא יתקיים האמור בענין זה, כי \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 לקיים \u0003\"כאשר זמם לעשות\"\u0004 (דברים יט, יט) \u0003ו\u0004באופן זה \u0003ליכא\u0004 \u0005[אין]\u0006 מתקיים הדבר, שהרי העד זמם לפסול את האיש וגם את זרעו אחריו.","\u0003בר פדא אומר\u0004 טעם אחר: \u0003קל וחומר\u0004 הוא, \u0003ומה המחלל,\u0004 כהן הבא על גרושה, שמחלל את האשה ואת זרעו הנולד ממנה, הוא עצמו \u0003אינו מתחלל\u0004 על ידי כך, אלא נשאר בכשרותו, העד הזומם \u0003הבא לחלל ולא חילל\u0004 בפועל, שהרי הוזם — \u0003אינו דין שלא יתחלל\u0004 הוא עצמו? \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא\u0004 על סברה זו: \u0003אם כן,\u0004 אם אתה משתמש בשיקול זה, שהעד הזומם לא עשה מה שזמם לעשות, כבסיס לקל וחומר — \u0003בטלת תורת עדים זוממין\u0004 מעיקרה, שכך יש לומר:"],["\u0003ומה הסוקל\u0004 את חבירו, כלומר עד זומם שגרם שהנאשם ימות בסקילה על ידי בית הדין — \u0003אינו נסקל,\u0004 שהרי הלכה היא שאם קיימו כבר את פסק הדין אין העדים הזוממים נהרגים, עד זומם \u0003הבא לסקול ולא סקל,\u0004 שלא נסקל הנאשם, \u0003אינו דין שלא יסקל?\u0004 ואם כן בטלה בכלל תורת עדים זוממים! \u0003אלא מחוורתא כדשנינן מעיקרא\u0004 \u0005[מחוור,\u0006 ברור, \u0005כמו שתירצנו מתחילה],\u0006 מדיוק הכתוב \"ועשיתם לו\" ולא לזרעו וכו', ולא כדברי בר פדא.","שנינו במשנה: \u0003מעידין אנו באיש פלוני שהוא חייב גלות\u0004 — אין אומרים יגלה זה תחתיו, אלא לוקה ארבעים. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר ריש לקיש:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 ברוצח בשגגה \u0003\"הוא ינוס אל אחת הערים\"\u0004 (דברים יט, ה), ויש כאן הדגשה: דווקא \u0003הוא, ולא זוממין.\u0004","\u0003ר' יוחנן אומר:\u0004 הדבר נלמד מ\u0003קל וחומר,\u0004 ובאופן זה: \u0003ומה הוא,\u0004 הרוצח, \u0003שעשה מעשה\u0004 — \u0003במזיד\u0004 \u0003אינו גולה,\u0004 גם אם לא דנו אותו למיתה, כגון שלא התרו בו. \u0003הן,\u0004 העדים הזוממים, \u0003שלא עשו מעשה\u0004 של הריגה בפועל, אף על פי שעשו \u0003במזיד אינו דין שלא יגלו?\u0004","ומקשים: \u0003והיא נותנת\u0004 מאותה הבחנה עצמה היה צריך לומר להיפך, \u0003והלא דין הוא: הוא,\u0004 הרוצח, \u0003שעשה מעשה\u0004 של הריגה בפועל — \u0003במזיד\u0004 \u0003לא ליגלי\u0004 \u0005[יגלה],\u0006 \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא תיהוי ליה\u0004 \u0005[תהיה לו]\u0006 \u0003כפרה\u0004 על מעשהו, וייענש בשלמות בידי שמים. \u0003הן,\u0004 העדים הזוממים, \u0003שלא עשו מעשה\u0004 רציחה ממש — למרות שעשו \u0003במזיד נמי ליגלו\u0004 \u0005[גם כן שיגלו],\u0006 \u0003כי היכי דליהוי להו\u0004 \u0005[כדי שתהיה להם]\u0006 \u0003כפרה,\u0004 ולפיכך צריך היה לומר שהם צריכים לגלות! \u0003אלא מיחוורתא\u0004 \u0005[מחוור,\u0006 ברור\u0005]\u0006 \u0003כ\u0004דברי \u0003ריש לקיש,\u0004 שהדבר נלמד מדיוק הכתוב — \"הוא\" ולא זוממים.","\u0003אמר עולא: רמז לעדים זוממין מן התורה מנין?\u0004 ובראשונה תוהים על הלשון: \u0003רמז לעדים זוממין?!\u0004 וכי רמז צריך? \u0003והא כתיב\u0004 \u0005[והרי נאמר]\u0006 במפורש: \u0003\"ועשיתם לו כאשר זמם\"\u0004 (דברים יט, יט)! \u0003אלא\u0004 כך צריך לומר את דברי עולא: \u0003רמז לעדים זוממין שלוקין\u0004 במקרים מסויימים \u0003מן התורה, מנין? דכתיב\u0004 \u0005[שנאמר]:\u0006 \"כי יהיה ריב בין אנשים ונגשו אל המשפט ושפטום \u0003והצדיקו את הצדיק והרשיעו את הרשע. והיה אם בן הכות הרשע\"\u0004 (דברים כה, א— ב), ולכאורה יש לתמוה: וכי \u0003משום והצדיקו את הצדיק\u0004 מתקיים \u0003והרשיעו את הרשע והיה אם בן הכות הרשע?\u0004 הלוא ברוב הסיכסוכים, גם אם מצדיקים את הצדיק — אין מכאן חיוב מלקות לצד האחר!","\u0003אלא,\u0004 צריך לפרש את הכתוב במקרה הבא: מדובר ב\u0003עדים שהרשיעו את הצדיק,\u0004 כלומר העידו עליו עדות שקר, \u0003ואתו\u0004 \u0005[ובאו]\u0006 \u0003עדים אחריני\u0004 \u0005[אחרים]\u0006 \u0003והצדיקו את הצדיק דמעיקרא\u0004 \u0005[שמתחילה],\u0006 שמעידים שצדיק הוא בדינו, \u0003ושוינהו להני\u0004 \u0005[ועשו\u0006 אם כן \u0005את אלה,\u0006 העדים הראשונים\u0005]\u0006 \u0003רשעים,\u0004 ובמקרה כזה צריך לקיים \u0003\"והיה אם בן הכות הרשע\".\u0004 ומכאן למדנו שיש דין מלקות בעדים זוממים.","ושואלים: \u0003ותיפוק ליה\u0004 \u0005[ותצא לו]\u0006 הלכה זו, שיש דין מלקות לעדים זוממים \u0003מ\u0004שום שהם עוברים על הלאו של \u0003\"לא תענה\u0004 ברעך עד שקר\" (שמות כ, יג)! ומשיבים: מפני לאו זה לא היו לוקים, \u0003משום דהוי\u0004 \u0005[שהריהו]\u0006 \u0003לאו שאין בו מעשה,\u0004 שהרי בעדות אין מעשה אלא דיבור בלבד, \u0003ו\u0004כלל הוא: \u0003כל לאו שאין בו מעשה —\u0004 \u0003אין לוקין עליו,\u0004 ולכן היה צריך ללמוד דין זה מן הכתוב \"והצדיקו\" וכו'.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ארבעה דברים נאמרו בעדים זוממין,\u0004 שבהם אין מענישים אותם כאשר זממו לעשות לנאשם, ואלו הם: \u0003אין נעשין בן גרושה ובן חלוצה, ואין גולין לערי מקלט, ואין משלמין את הכופר\u0004 אם העידו ששורו הרג אדם, \u0003ואין נמכרין ב\u0004תורת \u0003עבד עברי\u0004 אם העידו עליו שגנב, והיה צריך להימכר לעבד בגניבתו אם אין לו לשלם. \u0003משום\u0004 (בשם) \u0003ר' עקיבא אמרו: אף אין משלמין על פי עצמן.\u0004 שאם הוזמו בבית דין ולא הספיקו להענישם, והלכו לבית דין אחר והודו שהוזמו — אין הם משלמים על פי דברי עצמם את מה שהתחייבו לשלם.","ומסבירים את הדברים. \u0003אין נעשין בן גרושה ובן חלוצה\u0004 — \u0003כדאמרן\u0004 \u0005[כמו שאמרנו]\u0006 והסברנו את הטעם לעיל. \u0003ואין גולין לערי מקלט\u0004 — \u0003כדאמרן\u0004 \u0005[כמו שאמרנו].\u0006 \u0003ואין משלמין את הכופר\u0004 — \u0003קסברי\u0004 \u0005[סבורים]\u0006 חכמים אלה כי \u0003כופרא\u0004 \u0005[הכופר]\u0006 שמשלם מי שהרג שורו אדם — \u0003כפרה\u0004 הוא עליו, על שבהמתו המיתה את חבירו, ואין זה תשלום נזיקין, \u0003והני\u0004 \u0005[ואלה,\u0006 העדים הזוממים\u0005]\u0006 \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בני כפרה נינהו\u0004 \u0005[הם],\u0006 משום שלא הרג שורם אדם.","ושואלים: \u0003מאן\u0004 \u0005[מי\u0006 הוא\u0005]\u0006 ה\u0003תנא\u0004 הסבור ש\u0003כופרא\u0004 \u0005[הכופר]\u0006 הוא \u0003כפרה?\u0004 \u0003אמר רב חסדא:\u0004 שיטת \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה היא. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 מה שנאמר בדין שור הנוגח אדם: \"אם כופר יושת עליו \u0003ונתן פדין נפשו\"\u0004 (דברים כא, ל) כוונתו \u0003דמי ניזק,\u0004 שמשלם בעל השור ליורשי ההרוג את שוויו של ההרוג, כפי שהיה נישום כעבד העומד למכירה בשוק. \u0003ר' ישמעאל בנו של ר' יוחנן בן ברוקה אומר:\u0004 משלם להם \u0003דמי מזיק,\u0004 כפי שהוא, בעל השור עצמו שווה. \u0003מאי לאו בהא קא מיפלגי\u0004 \u0005[האם לא בזה הם חולקים?]\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003כופרא ממונא\u0004 [\u0005הכופר\u0006 חיוב \u0005ממון\u0006 הוא\u0005],\u0006 והוא משלם את דמי הניזק כמו כל מקרה שהזיק שורו, שהוא משלם עבור מה שהזיק. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' ישמעאל, \u0005סבור]:\u0006 \u0003כופרא\u0004 \u0005[הכופר]\u0006 הוא \u0003כפרה,\u0004 שהוא בעצם חייב מיתה בידי שמים, והוא משלם פדיון נפשו?","\u0003אמר רב פפא: לא,\u0004 אפשר לומר כי \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003כופרא\u0004 \u0005[הכופר]\u0006 הוא \u0003כפרה, והכא בהא קא מיפלגי\u0004 \u0005[\u0006וכאן, \u0005ב\u0006נושא \u0005זה הם חלוקים],\u0006 כיצד מעריכים את סכום הכסף הראוי לכפרה, \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003ב\u0004ערכו של ה\u0003ניזק שיימינן\u0004 \u0005[מעריכים אנו],\u0006 \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' ישמעאל, \u0005סבור]:\u0006 \u0003ב\u0004ערכו של ה\u0003מזיק שיימינן\u0004 \u0005[מעריכים אנו].\u0006","ומבררים: \u0003מאי טעמייהו דרבנן\u0004 \u0005[מה טעמם של חכמים]\u0006 המפרשים כתוב זה שלא כמשמעותו הפשוטה? \u0003נאמר השתה למטה\u0004 במי שהרג שורו אדם: \"אם כופר יושת עליו\" (שמות כא, ל), \u0003ונאמר השתה למעלה\u0004 (קודם), במי שפגע באשה הרה וגרם לה להפיל: \"ענוש ייענש כאשר ישית עליו בעל האשה\" (דברים, כא, כב), \u0003מה להלן\u0004 \u0005[שם]\u0006 בהפלה — מעריכים \u0003ב\u0004דמיו של ה\u0003ניזק\u0004 (דמי הוולדות), \u0003אף כאן\u0004 בכופר — \u0003ב\u0004דמיו של ה\u0003ניזק.\u0004","\u0003ור' ישמעאל\u0004 סבור: כי \u0003\"ונתן פדין נפשו\" כתיב\u0004 \u0005[נאמר],\u0006 ומשמע — פדיון נפשו של החייב. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם משיבים על כך? \u0003אין\u0004 \u0005[כן],\u0006 אמנם \u0003\"פדיון נפשו\" כתיב\u0004 \u0005[נאמר]\u0006 וכפרה היא, \u0003מיהו כי שיימינן בדניזק שיימינן\u0004 \u0005[מכל מקום, כאשר אנו מעריכים\u0006 את דמי פדיון הנפש \u0005ב\u0006דמיו \u0005של הניזק אנו מעריכים].\u0006","עוד שנינו בברייתא ש\u0003אין\u0004 עדים זוממים \u0003נמכרין בעבד עברי\u0004 אם העידו עליו שגנב. \u0003סבר רב המנונא למימר\u0004 \u0005[לומר]:\u0006 \u0003הני מילי היכא דאית ליה לדידיה\u0004 \u0005[דברים אלה\u0006 אמורים דווקא \u0005במקום שיש לו,\u0006 לזה שהעלילו עליו, כסף מספיק \u0005משלו]\u0006 לשלם את דמי גניבתו, שבמקרה זה אין הוא נמכר על גניבתו, \u0003דמיגו דאיהו לא נזדבן\u0004 \u0005[שמתוך שהוא לא היה נמכר\u0006 בגניבתו\u0005],\u0006 אלא היה משלם את דמי הגניבה — \u0003אינהו נמי לא מיזדבנו\u0004 \u0005[הם גם כן אינם נמכרים]\u0006 על עדותם שהוזמה. \u0003אבל היכא דלית ליה לדידיה\u0004 \u0005[במקום שאין לו עצמו\u0006 כסף\u0005]\u0006 והיה צריך להימכר אילו היתה מתקבלת עדותם של אלו, \u0003אף על גב דאית להו לדידהו\u0004 — \u0003מיזדבנו\u0004 \u0005[אף על פי שיש להם עצמם\u0006 — \u0005נמכרים],\u0006 כיון שעל ידי עלילתם היו גורמים לו שיימכר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: ולימרו ליה\u0004 \u0005[ויאמרו לו\u0006 העדים\u0005]:\u0006 \u0003אי אנת הוה לך מי הוה מיזדבנת\u0004 \u0005[אם אתה היה לך\u0006 כסף, \u0005האם היית נמכר]?\u0006 \u0003אנן נמי לא מיזדבנינן\u0004 \u0005[אנו גם כן איננו נמכרים].\u0006 שכיון שיש להם כסף — הם יכולים לשלם את הסכום הזה, ודיים בכך. \u0003אלא\u0004 יש לדחות את הנוסח הזה ולומר בלשון אחרת, כי \u0003סבר רב המנונא למימר\u0004 \u0005[לומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלו\u0006 אמורים\u0005]\u0006 דווקא \u0003היכא דאית ליה או לדידיה או לדידהו\u0004 \u0005[במקום שיש\u0006 כסף \u0005או לו, או להם,\u0006 לעדים\u0005],\u0006 \u0003אבל היכא דלית ליה לא לדידיה ולא לדידהו\u0004 — \u0003מזדבני\u0004 \u0005[אבל במקום שאין\u0006 כסף \u0005לא לו ולא להם\u0006 — \u0005נמכרים].\u0006 שכיון שאינם יכולים לשלם מה שהעידו עליו שגנב, והם היו מביאים אותו להימכר — אף הם נמכרים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 אי אפשר לומר כן, כי בדין מכירה לעבד עברי \"אם אין לו \u0003ונמכר בגנבתו\"\u0004 (דברים כב, ב) \u0003אמר רחמנא\u0004 \u0005[הכתוב],\u0006 ודיוק הלשון בא להדגיש: דווקא \u0003בגנבתו\u0004 הוא נמכר, \u0003ולא בזממו.\u0004","שנינו עוד בברייתא, \u0003משום ר' עקיבא אמרו:\u0004 אף אין (עדים זוממים) משלמים על פי עצמם. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' עקיבא? קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 שממון זה שמשלמים עדים זוממים, \u0003קנסא\u0004 \u0005[קנס]\u0006 \u0003הוא, ו\u0004כלל הוא: \u0003קנס אין משלם על פי\u0004 הודאת \u0003עצמו,\u0004 אלא רק על פי עדים. \u0003אמר רבה: תדע\u0004 שהוא קנס, \u0003שהרי\u0004 עדים אלה \u0003לא עשו מעשה\u0004 לא הזיקו בפועל, \u0003[ונהרגים] ומשלמין,\u0004 ומכאן שקנס הוא שקנסה התורה אותם על כוונתם הרעה. \u0003אמר רב נחמן: תדע\u0004 שקנס הוא ולא תשלום נזיקין, \u0003שהרי\u0004 ה\u0003ממון\u0004 שרצו לחייבו נשאר בסופו של דבר \u0003ביד בעלים, ו\u0004בכל זאת \u0003משלמים\u0004 לו."],["ותמהים: \u0003מאי ניהו\u0004 \u0005[מה הוא]\u0006 מה עניינו של זה שממון ביד בעלים — הלוא הוא ש\u0003לא עשו\u0004 מעשה בפועל, אם כן \u0003היינו\u0004 \u0005[זהו]\u0006 טעמו של \u0003רבה,\u0004 ולא טעם אחר! ומתקנים: \u0003אימא\u0004 \u0005[אמור]\u0006 בהמשך דברי רבה, \u0003וכן אמר רב נחמן:\u0004 תדע שהרי ממון ביד בעלים. שרב נחמן אינו חולק על דברי רבה, אלא מנסח אותם באופן אחר.","ובקשר למה שאמר ר' עקיבא, מביאים: \u0003אמר רב יהודה אמר רב: עד זומם משלם לפי חלקו.\u0004 ומבררים, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"משלם לפי חלקו\"?\u0004 \u0003אילימא דהאי\u0004 \u0005[אם תאמר ש\u0006עד \u0005זה,\u0006 אחד העדים\u0005]\u0006 \u0003משלם פלגא\u0004 \u0005[חצי]\u0006 מהסכום ששני העדים זממו לחייבו, \u0003והאי פלגא\u0004 \u0005[ו\u0006עד \u0005זה\u0006 השני משלם את ה\u0005חצי\u0006 השני\u0005] —\u0006 \u0003תנינא\u0004 \u0005[\u0006הרי כבר \u0005שנינו\u0006 דבר זה\u0005]\u0006 במשנה במפורש להלן: \u0003משלשין בממון\u0004 כלומר, מחלקים את תשלום הממון בין העדים הזוממים, \u0003ואין משלשין במלקות,\u0004 שאם רצו לחייבו מלקות ארבעים — מלקים כל אחד מהם ארבעים מלקות, ואין מחלקים את שיעור המלקות ביניהם!","\u0003אלא,\u0004 צריך לומר שזו הכוונה בביטוי \"משלם לפי חלקו\": \u0003כגון דאיתזום חד מינייהו\u0004 \u0005[שהוזם\u0006 רק \u0005אחד מהם],\u0006 שאז הוא \u0003משלם פלגא דידיה\u0004 \u0005[החצי שלו].\u0006 ותוהים: \u0003ומי\u0004 \u0005[והאם]\u0006 הוא בכלל \u0003משלם\u0004 במקרה כזה? \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003אין עד זומם משלם ממון עד שיזומו שניהם,\u0004 ואם הוזם רק אחד — אינו משלם!","\u0003אמר רבא:\u0004 אין מדובר כאן בהזמה ממש, אלא \u0003ב\u0004זמן שאחד העדים \u0003אומר \"עדות שקר העדתי\".\u0004 ותוהים: \u0003כל כמיניה\u0004 \u0005[וכי זה בכוחו]?\u0006 הלוא כלל הוא: \u0003כיון שהגיד שוב אינו חוזר ומגיד,\u0004 שכיון שהעיד אדם בבית הדין — אין הוא יכול לחזור בו מעדותו הראשונה ולהעיד עדות שונה!","ומשיבים: \u0003אלא\u0004 מדובר \u0003ב\u0004עד ה\u0003אומר \"העדנו והוזמנו בבית דין פלוני\",\u0004 וכיון שאומר שכבר הוזם, הרי הוא עתה כמודה שהוא חייב ממון, ולכן הוא משלם את חלקו שלו. ומקשים: הלכה זו \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי\u0006 היא\u0005]\u0006 — ש\u0003לא כר' עקיבא, דאי\u0004 \u0005[שאם]\u0006 \u0003כר' עקיבא הא\u0004 \u0005[הרי]\u0006 \u0003אמר:\u0004 עד זומם \u0003אף אינו משלם על פי\u0004 עדות \u0003עצמו!\u0004","ואם כן, אין דברי ר' עקיבא יכולים להיות מוסברים כך, \u0003אלא,\u0004 מדובר כאן \u0003ב\u0004עד \u0003אומר \"העדנו והוזמנו בבית דין פלוני וחוייבנו ממון\",\u0004 שאז אינו עוד מודה בקנס, אלא בחיוב ממון גמור, שנתחייב בבית דין לשלם סכום מסויים, והרי זה כשאר חיובי ממון שיש על אדם, והודאתו מחייבת אותו.","ומסבירים מה החידוש שבכך: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003כיון דלחבריה לא מצי מחייב ליה\u0004 \u0005[שאת חבירו אינו יכול לחייב]\u0006 בעדות זו, שהרי אינו נאמן להודות בשם חבירו, נאמר כי \u0003איהו נמי לא מיחייב\u0004 \u0005[הוא\u0006 עצמו \u0005גם כן אינו מתחייב\u0006 בכך\u0005],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שכיון שהודה שהוא חייב ממון — משלם.","אמרו העדים הזוממים \u0003\"מעידין אנו את איש פלוני שגירש את אשתו ולא נתן לה כתובתה\"\u0004 ונמצא שזממו לחייבו שלא כדין בתשלום דמי כתובתה. והשאלה המתעוררת מעתה היא מה ישלמו הזוממים, שכן אי אפשר לחייבם לתת את הכל, שיכולים הם לטעון: \u0003והלא בין היום ובין למחר\u0004 כלומר, יכול לקרות במוקדם או במאוחר, שיגרש את אשתו או שימות, ואז \u0003סופו ליתן לה כתובתה,\u0004 ואם כן, לא זממו לחייב אותו בדבר שאינו חייב בו.","ולכן, שיעור התשלומים נקבע בכך ש\u0003אומדין\u0004 (מעריכים) \u0003כמה\u0004 כסף \u0003אדם\u0004 אחר \u0003רוצה\u0004 (מוכן) \u0003ליתן בכתובתה של זו\u0004 על צד הספק, \u0003שאם נתאלמנה או נתגרשה\u0004 יקבל הקונה את הכתובה, \u0003ואם מתה\u0004 — \u0003יירשנה בעלה.\u0004 ועל בסיס זה מחשבים, כמבואר בגמרא.","נאמר במשנה שאומדים כמה אדם מוכן לשלם עבור הסיכוי שבסופו של דבר הוא יזכה בכתובה. ויש לשאול: \u0003כיצד\u0004 בדיוק \u0003שמין\u0004 (מעריכים) דבר זה? \u0003אמר רב חסדא: בבעל\u0004 כלומר, מעריכים כמה אדם מוכן לתת לבעל עבור הסיכוי לקבל את כתובה זו, באם תמות האשה לפניו, שאז בעלה יורשה.","\u0003רב נתן בר אושעיא אומר:\u0004 אומדים את הסכום הזה \u0003באשה\u0004 כמה מוכן אדם לשלם לאשה עבור הסיכוי שהיא תקבל את הכתובה, אם ימות בעלה או יגרשנה.","\u0003אמר רב פפא:\u0004 אומדים \u0003באשה,\u0004 כדברי רב נתן, \u0003ו\u0004אולם \u0003בכתובתה\u0004 בלבד, ואין מביאים בחשבון נכסי מלוג, שהביאה האשה לבית בעלה והבעל אוכל פירותיהם, שהרי גם את פירותיהם של אלה מפסיד הבעל כשהוא מגרשה, אלא אומדים לפי הכתובה בלבד.","אמרו העדים הזוממים: \u0003\"מעידין אנו באיש פלוני שהוא חייב לחבירו אלף זוז\u0004 שלוה ממנו, \u0003על מנת ליתנן\u0004 (לפרוע) \u0003לו מכאן\u0004 (מעכשיו) \u0003ועד שלשים יום\", והוא,\u0004 הלווה שהעידו עליו, \u0003אומר\u0004 שבאמת לוה סכום זה, אבל תנאי התשלום היה על מנת ליתנו \u0003מכאן ועד עשר שנים,\u0004 ולאחר מכן הוזמו העדים.","אף כאן אין מחייבים את הזוממים לשלם הכל, אלא \u0003אומדים כמה אדם רוצה ליתן ויהיו בידו אלף זוז\u0004 בהלוואה, ואומדים את ההבדל \u0003בין\u0004 מה שהוא מוכן לתת עבור שימוש במעות אלה, אם \u0003נותנן מכאן ועד שלשים יום,\u0004 ל\u0003בין\u0004 אם היה צריך להיות \u0003נותנן מכאן ועד עשר שנים.\u0004 וההפרש בין הסכומים הללו הוא זה שבאו העדים הזוממים להפסידו, ואותו ישלמו.","\u0003אמר רב יהודה אמר שמואל: המלוה את חבירו לעשר שנים\u0004 — \u0003שביעית משמטתו,\u0004 שהרי בתוך עשר שנים חלה שנת שמיטה, ובאותה שנה נשמטים גם חובות אלה."],["\u0003ואף על גב דהשתא לא קרינן ביה\u0004 \u0005[ואף על פי שעכשיו,\u0006 בשנה השביעית, \u0005אין אנו קוראים,\u0006 לא מתקיים \u0005בו]\u0006 עדיין האיסור האמור בשביעית \u0003\"לא יגש\u0004 את רעהו כי קרא שמיטה לה'\" (דברים טו, ב), שהרי זמן פרעון החוב עדיין לא הגיע, וממילא אין המלוה יכול לתבוע את הלווה, מכל מקום \u0003סוף אתי\u0004 \u0005[בסופו\u0006 של דבר הרי \u0005יבוא]\u0006 \u0003לידי \"לא יגש\",\u0004 ואם כן חוב הוא כשאר החובות, והשביעית משמטת אותו.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב כהנא\u0004 על כך ממה ששנינו במשנתנו שאם העידו על אדם שלוה אלף זוז לשלושים יום, ובאמת לוה לעשר שנים, והוזמו — \u0003אומדים כמה אדם רוצה ליתן ויהיו אלף זוז בידו בין ליתן מכאן ועד שלשים יום, ובין ליתן מכאן ועד עשר שנים,\u0004 ואת ההפרש הם משלמים. \u0003ו\u0004מעתה יש לשאול: \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שמילוה לעשר שנים \u0003שביעית משמטתו\u0004 — \u0003כולהו נמי בעי שלומי ליה\u0004 \u0005[\u0006את \u0005הכל,\u0006 כל סכום ההלוואה, \u0005גם כן צריכים\u0006 העדים הזוממים \u0005לשלם לו\u0006 ללווה\u0005],\u0006 שהרי חוב שפרעונו בעוד עשר שנים — פירושו של דבר שאיננו מוחזר כלל!","\u0003אמר רבא: הכא במאי עסקינן\u0004 \u0005[כאן,\u0006 במשנתנו, \u0005במה אנו עוסקים]\u0006 — בחובות שאין שביעית משמטתם, כגון \u0003במלוה על המשכון,\u0004 או \u0003במוסר שטרותיו לבית דין. דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003המלוה על המשכון, והמוסר שטרותיו לבית דין\u0004 — \u0003אין משמיטין.\u0004 ובמקרה זה לא זממו העדים להפסיד את הלווה בתשלום כל סכום ההלוואה.","\u0003איכא דאמרי\u0004 \u0005[יש האומרים]\u0006 את הדברים בגרסה הפוכה, \u0003אמר רב יהודה אמר שמואל: המלוה את חבירו לעשר שנים\u0004 — \u0003אין שביעית משמטתו. ואף על גב דאתי\u0004 \u0005[ואף על פי ש\u0006הוא \u0005יבוא\u0006 בעתיד\u0005]\u0006 \u0003לידי \"לא יגש\", השתא מיהא לא קרינן ביה\u0004 \u0005[עכשיו על כל פנים אין אנו קוראים בו]\u0006 \u0003\"לא יגש\",\u0004 שהרי בשנה השביעית אין החוב עומד לפרעון.","\u0003אמר רב כהנא: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 דבר זה במשנתנו: \u0003אומדין כמה אדם רוצה ליתן ויהיו אלף זוז בידו, בין ליתן מכאן ועד שלשים יום, ובין ליתן מכאן ועד עשר שנים. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 \u0003שביעית משמטתו\u0004 — \u0003כולהו נמי בעו שלומי ליה\u0004 \u0005[\u0006את \u0005הכל,\u0006 ולא רק את ההפרש, \u0005גם כן היה צריך לשלם לו\u0006 ללווה\u0005],\u0006 שהרי בלי עדותם היה נפטר מלהחזיר את החוב. ומכאן הוכחה שמילוה לעשר שנים אינו נשמט.","\u0003אמר רבא:\u0004 מכאן אין להוכיח, \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003במלוה על המשכון, ובמוסר שטרותיו לבית דין, דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003המלוה על המשכון, והמוסר שטרותיו לבית דין\u0004 — \u0003אין משמיטין.\u0004","\u0003ו\u0004עוד \u0003אמר רב יהודה אמר שמואל\u0004 בענין שמיטת כספים: אדם \u0003האומר לחבירו\u0004 בלשון תנאי \"הריני מלוה לך \u0003על מנת שלא תשמטני שביעית\"\u0004 והלווה מסכים לכך, בכל זאת \u0003שביעית משמטת.\u0004 ושואלים: \u0003לימא קסבר\u0004 \u0005[האם לומר שסבור]\u0006 \u0003שמואל\u0004 שבכגון זה \u0003מתנה על מה שכתוב בתורה הוא,\u0004 שהתנאי בא לבטל את הכתוב בתורה, \u0003ו\u0004לדעתו \u0003כל המתנה על מה שכתוב בתורה\u0004 — \u0003תנאו בטל?\u0004","\u0003והא איתמר\u0004 \u0005[והרי נאמר]\u0006 שנחלקו רב ושמואל בנושא זה, \u0003האומר לחבירו:\u0004 \"הרי אני מוכר לך דבר \u0003על מנת שאין לך עלי אונאה\"\u0004 כלומר, שגם אם היתה כאן הונאה, וקיבל סכום גדול מן המגיע לו — לא תהיה עליו תביעה בענין זה, \u0003רב אומר: יש לו עליו אונאה,\u0004 ואי אפשר לבטל את דין האונאה למרות התנאי, \u0003ושמואל אומר: אין לו עליו אונאה.\u0004 משמע אם כן כי לדעת שמואל בדבר שבממון אפשר להתנות על מה שכתוב בתורה, לפי שהוא כמוותר על ממון המגיע לו ואין זה נחשב מתנה על דברי תורה!","ומשיבים: \u0003הא איתמר עלה\u0004 \u0005[הרי נאמר עליה]\u0006 על מחלוקת זו, \u0003אמר רב ענן: לדידי מפרשא ליה מיניה דשמואל\u0004 \u0005[לי מתפרש הדבר ממנו משמואל\u0006 עצמו\u0005]\u0006 שיש לחלק בענין זה ולדייק בלשון התנאי, שאם אומר \u0003\"על מנת שאין לך עלי אונאה\"\u0004 — \u0003אין לו עליו אונאה,\u0004 כיון שיש כאן מחילה פרטית של חבירו על ממון שיתחייב לו. אבל אם אמר \u0003\"על מנת שאין בו אונאה\"\u0004 שלא יחול איסור אונאה בעסקה זו — \u0003הרי יש בו אונאה.\u0004","ולפי זה \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לענין שביעית נקיים הבחנה זו בלשונות התנאי, שאם אמר \"הריני מלוה לך \u0003על מנת שלא תשמטני בשביעית\"\u0004 — \u0003אין שביעית משמטתו,\u0004 משום שזה הוא תנאי ממוני בין שניהם. אבל אם אמר \u0003\"על מנת שלא תשמטני שביעית\"\u0004 כלומר, שדין שביעית לא יחול על הלוואה זו — \u0003שביעית משמטתו,\u0004 שאין הוא יכול לבטל דין מן התורה.","ובקשר למה שהוזכר במשנתנו, מביאים \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003המלוה את חבירו סתם\u0004 ולא קבע זמן פרעון — \u0003אינו רשאי לתובעו פחות משלשים יום.\u0004 ומעירים: \u0003סבר\u0004 \u0005[סבור היה]\u0006 \u0003רבה בר בר חנה\u0004 כשהיה יושב \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב למימר\u0004 \u0005[לומר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלו\u0006 אמורים\u0005]\u0006 דווקא \u0003במלוה בשטר,\u0004 משום \u0003דלא עבד איניש דטרח דכתב\u0004 \u0005[שאין עשוי אדם שיטרח שיכתוב]\u0006 \u0003שטר\u0004 להלוואה שהיא \u0003בציר מתלתין יומין\u0004 \u0005[פחות משלושים יום],\u0006 ולכן אנו מניחים שהלוואה זו היתה לפחות לשלושים יום, \u0003אבל מלוה על פה\u0004 — \u0003לא. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב: הכי\u0004 \u0005[כך]\u0006 \u0003אמר חביבי\u0004 (דודי, ר' חייא): \u0003אחד המלוה בשטר ואחד המלוה על פה,\u0004 אם לא קבע זמן לפרעון ההלוואה — אינם נפרעים בפחות משלושים יום.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003המלוה את חבירו סתם\u0004 — \u0003אינו רשאי לתובעו פחות משלשים יום, אחד המלוה בשטר ואחד המלוה על פה.\u0004","ובענין זה מסופר, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לרב מתנה: לא תיתיב אכרעיך\u0004 \u0005[תשב על רגליך]\u0006 \u0003עד דמפרשת לה להא שמעתא\u0004 \u0005[שתפרש אותה, את ההלכה הזו]\u0006 כלומר, עומד אני על כך שתסביר לי אותו מיד: \u0003מנא הא מילתא דאמור רבנן\u0004 \u0005[מניין אותו דבר שאמרו חכמים]:\u0006 \u0003המלוה את חבירו סתם אינו רשאי לתובעו פחות משלשים יום, אחד המלוה בשטר ואחד המלוה על פה?\u0004 מה המקור לכך?","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"קרבה שנת השבע שנת השמטה\"\u0004 (דברים טו, ט), ויש לשאול: \u0003ממשמע שנאמר \"קרבה שנת השבע\" איני יודע שהיא שנת שמטה? אלא מה תלמוד לומר \"שנת השמטה\"\u0004 — \u0003לומר לך: [יש] שמטה אחרת שהיא כזו\u0004 כלומר, יש מעין \"שנת שמיטה\" אחרת, \u0003ואיזו\u0004 — \u0003זו המלוה את חבירו סתם, שאינו רשאי לתובעו בפחות משלשים יום.\u0004 וכיצד ניתן לקרוא לכך \"שנה\"? ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003שלשים יום בשנה חשוב שנה.\u0004 ולפיכך יש לפרש: לפני שנת השבע יש גם זמן אחר שהוא כעין שנת שמיטה, שאין רשאי לתבוע את חובו.","\u0003ואמר רב יהודה אמר רב: הפותח בית הצואר\u0004 של בגד \u0003בשבת\u0004 — \u0003חייב חטאת\u0004 אם עשה זאת בשוגג, משום שבכך הוא מתקן את הבגד ועושה מלאכה גמורה בשבת. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב כהנא: וכי מה\u0004 ההבדל \u0003בין זה למגופת\u0004 (מכסה של) \u0003חבית,\u0004 שמותר לשבור את הטיט המחבר אותה לחבית, ולפתוח כך את החבית? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זה\u0004 בבית הצואר של בגד \u0003חבור\u0004 של ממש הוא, \u0003ו\u0004אילו \u0003זה\u0004 חיבור המגופה לחבית \u0003אינו חבור,\u0004 אלא עשוי מראש להינתק.","\u0003ואמר רב יהודה אמר רב: שלשת לוגין מים\u0004 שאובים \u0003שנפל לתוכן קורטוב\u0004 (משהו, מדה קטנה) \u0003של יין, ומראיהן\u0004 (ציבעם) של מים אלו \u0003כמראה יין, ונפלו\u0004 מים אלה \u0003למקוה\u0004 שיש בו פחות מארבעים סאה, הרי אף על פי שאמרו חכמים ששלושה לוגים מים שאובים שנפלו למקוה פוסלים אותו, במקרה זה \u0003לא פסלוהו,\u0004 משום שאין אלה נחשבים כמים, אלא כיין, ויין איננו פוסל במקוה. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב כהנא:\u0004 \u0003וכי מה בין זה למי צבע? דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]\u0006 \u0003ר' יוסי אומר: מי צבע פוסלין את המקוה בשלשת לוגין.\u0004 והרי אף כאן, המים רק צבועים בצבע יין! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 יש לחלק, \u0003התם \"מיא דצבעא\" מקרי\u0004 \u0005[שם, \"מי צבע\" נקראים\u0006 הם\u0005]\u0006 ועדיין מים הם, \u0003הכא \"חמרא מזיגא\" מקרי\u0004 \u0005[כאן, \"יין מזוג\"\u0006 הוא \u0005נקרא].\u0006","ומקשים על דברי רב: \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003ר' חייא\u0004 ששלושה לוגים מים שנפל לתוכם קורטוב יין \u0003הורידו\u0004 (פסלו) \u0003את המקוה!\u0004 \u0003אמר רבא: לא קשיא\u0004 \u0005[אין זה קשה]\u0006 על דברי רב, כי \u0003הא\u0004 \u0005[זו,\u0006 דברי רב\u0005]\u0006 הם כשיטת \u0003ר' יוחנן בן נורי, הא רבנן\u0004 \u0005[זו,\u0006 הברייתא ששנה ר' חייא, כשיטת \u0005חכמים]\u0006 החולקים עליו. ומהי אותה מחלוקת? \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003שלשת לוגין מים\u0004 שאובים"],["\u0003חסר קורטוב, שנפל לתוכן קורטוב יין\u0004 והשלימן לשלושה לוגים, \u0003ומראיהן\u0004 של המים המעורבים \u0003כמראה יין, ונפלו למקוה\u0004 חסר — \u0003לא פסלוהו. וכן שלשה לוגין מים\u0004 שאובים \u0003חסר קורטוב, שנפל לתוכן קורטוב חלב ומראיהן כמראה מים,\u0004 שהרי החלב אין לו צבע ניכר במים, \u0003ונפלו למקוה\u0004 חסר — \u0003לא פסלוהו,\u0004 שהרי לא היו כאן שלושה לוגים שלמים של מים, אבל אם היו שלושה לוגים שלמים — פוסלים את המקוה.","\u0003ר' יוחנן בן נורי אומר: הכל\u0004 כלומר, כל מקרה ומקרה נידון \u0003הולך\u0004 (נקבע) \u0003אחר המראה\u0004 ולכן, אם היה למים המעורבים מראה יין — לא פסלו את המקוה, ואם היה להם מראה מים — פסלוהו. ואפשר לומר שדעת רב יהודה בשם רב היא כשיטה זו, שהכל הולך אחר המראה, ולכן כיון שמראה שלושת הלוגים של המים הוא כמראה יין — אינם פוסלים את המקוה. ואילו ר' חייא סבור כדעת התנא הראשון, שהכל תלוי בכמות המים, וכיון שהיו שלושה לוגין מלאים של מים — הריהם פוסלים, גם אם מראיהם מראה יין.","ושואלים: \u0003הא מיבעיא בעי לה\u0004 \u0005[הרי\u0006 דבר זה \u0005שאל,\u0006 נסתפק \u0005בו]\u0006 \u0003רב פפא. דבעי\u0004 \u0005[ששאל]\u0006 \u0003רב פפא:\u0004 האם \u0003רב תני\u0004 \u0005[שונה]\u0006 בנוסחת משנה זו \u0003\"חסר קורטוב\" ברישא\u0004 \u0005[בתחילה],\u0006 \u0003אבל שלשה לוגין\u0004 מים, אפילו מראיהם כיין, \u0003לתנא קמא פסלי\u0004 \u0005[ל\u0006דעת \u0005התנא הראשון פוסלים],\u0006 \u0003ואתא\u0004 \u0005[ובא]\u0006 \u0003ר' יוחנן\u0004 בן נורי \u0003למימר\u0004 \u0005[לומר]:\u0006 \u0003הכל הולך אחר המראה,\u0004 והואיל ומראיהם מראה יין — אינם פוסלים. \u0003ורב אומר כר' יוחנן בן נורי.\u0004","\u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003רב לא תני\u0004 \u0005[שונה]\u0006 \u0003\"חסר קורטוב\" ברישא\u0004 \u0005[בתחילה],\u0006 אלא: שלושה לוגין מים שנפל לתוכן קורטוב יין. ולשיטה זו אף תנא קמא סבור שאם מראיהם כיין — אינם פוסלים, \u0003ור' יוחנן בן נורי כי פליג\u0004 \u0005[כאשר\u0006 הוא \u0005חולק]\u0006 — רק \u0003אסיפא\u0004 \u0005[על הסוף]\u0006 \u0003הוא דפליג\u0004 \u0005[שחולק],\u0006 במקרה שהיו שלושה לוגים חסר קורטוב, ונוסף להם קורטוב חלב, שלדעת התנא הראשון, הואיל ואין כאן שלושה לוגים מים — אינם פוסלים, ואילו ר' יוחנן בן נורי מחמיר ואומר שהם פוסלים, משום שמראיהם כמראה מים,","\u0003ו\u0004אם כן \u0003רב\u0004 ש\u0003אמר\u0004 ששלושה לוגים שנפל לתוכם יין וצבעם אינם פוסלים — \u0003כדברי הכל\u0004 אמר?","ומשיבים: זה אינו קושי, \u0003לרב פפא מיבעיא ליה\u0004 \u0005[מסופק היה לו\u0006 הדבר\u0005],\u0006 \u0003לרבא פשיטא ליה\u0004 \u0005[היה פשוט לו]\u0006 איך צריך לשנות את המשנה ולהבינה.","ובענין זה מביאים מה ש\u0003אמר רב יוסף: לא שמיעא לי הא שמעתא\u0004 \u0005[שמעתי את ההלכה הזו]\u0006 ביחס לספק של חסר קורטוב, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: את אמרת לה ניהלן\u0004 \u0005[אתה\u0006 עצמך \u0005אמרת לנו אותה],\u0006 אלא שבתוך מחלתך שכחת, \u0003והכי אמרת ניהלן\u0004 \u0005[וכך אמרת לנו],\u0006 ש\u0003רב לא תני\u0004 \u0005[שונה]\u0006 \u0003\"חסר קורטוב\" ברישא\u0004 \u0005[בתחילה],\u0006 \u0003ור' יוחנן\u0004 בן נורי \u0003אסיפא פליג\u0004 \u0005[\u0006רק \u0005על\u0006 הדין \u0005שבסוף\u0006 הוא \u0005חולק],\u0006 \u0003ורב\u0004 ש\u0003אמר כדברי הכל.\u0004","\u0003ו\u0004עוד בענין דומה, \u0003אמר רב יהודה אמר רב: חבית מליאה מים\u0004 שאובים \u0003שנפלה לים הגדול, הטובל\u0004 \u0003שם\u0004 במקום שנפלו מי החבית — \u0003לא עלתה\u0004 (הועילה) \u0003לו טבילה\u0004 לטהרו. מדוע? \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003לשלשה לוגין\u0004 שאובים שהיו בחבית זו \u0003שלא יהו במקום אחד\u0004 שמא לא נתערבו במי הים, והטובל בהם לא נטהר. ומסייגים הלכה זו: \u0003ו\u0004דברים אלה אמורים \u0003דוקא\u0004 בחבית שנפלה \u0003לים הגדול דקאי וקיימא\u0004 \u0005[שנשאר עומד]\u0006 במקומו, ואין המים שבתוכו נעים הרבה, \u0003אבל נהרא בעלמא\u0004 \u0005[נהר סתם]\u0006 — \u0003לא,\u0004 משום שהמים שנשפכו מן החבית נשטפים ומתערבים מיד במי הנהר הזורמים.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003חבית מליאה יין שנפלה לים הגדול\u0004 — \u0003הטובל שם לא עלתה לו טבילה, חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003לשלשה לוגין שאובין שלא יהו במקום אחד. וכן ככר של תרומה שנפל שם\u0004 למקום היין — \u0003טמא,\u0004 משום שנטמא על ידי היין.","ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003\"וכן\"?\u0004 מה נוסף בכך? הרי לכאורה זו חזרה מיותרת, שאם אנו חוששים שהיין נשאר במקומו — החשש קיים לגבי כל ענין! ומסבירים: \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 \u0003התם\u0004 \u0005[שם]\u0006 לענין אדם טמא הטובל — יש לנהוג על פי הכלל: \u0003אוקי גברא אחזקיה\u0004 \u0005[העמד\u0006 את \u0005האיש על חזקתו]\u0006 שהיה טמא, ומכיון שלא ברור לנו שנטהר — הרי הוא נשאר בחזקת טמא. \u0003הכא\u0004 \u0005[כאן]\u0006 בכיכר של תרומה, יש לומר \u0003אוקי\u0004 \u0005[העמד]\u0006 \u0003תרומה אחזקה\u0004 \u0005[על חזקתה]\u0006 שהיא טהורה, ולא תטמאנה מספק, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאנו חוששים לדבר, אפילו להוציא מידי חזקה.","אמרו העדים: \u0003\"מעידין אנו באיש פלוני שחייב לחבירו מאתים זוז\" ונמצאו זוממין\u0004 בעדותם זו — הרי הם \u0003לוקין ו\u0004גם \u0003משלמין\u0004 מה שרצו לחייב אותו פלוני לשלם, ומדוע? \u0003שלא השם\u0004 (הכתוב, הטעם) \u0003המביאן לידי\u0004 עונש \u0003מכות\u0004 הוא ה\u0003מביאן לידי\u0004 עונש \u0003תשלומין,\u0004 שהם לוקים משום שהעידו שקר, ומשלמים משום \"כאשר זמם\", \u0003דברי ר' מאיר. וחכמים אומרים: כל המשלם\u0004 כעונש על עבירה מסויימת — \u0003אינו לוקה\u0004 עליה.","וכן אם אמרו: \u0003\"מעידין אנו באיש פלוני שהוא חייב מלקות ארבעים\" ונמצאו זוממין\u0004 — הרי הם \u0003לוקין שמונים\u0004 מלקות, כלומר שני עונשי מלקות הם לוקים, הן \u0003משום \"לא תענה ברעך עד שקר\"\u0004 (שמות כ, יג) \u0003ו\u0004הן \u0003משום \"ועשיתם לו כאשר זמם\"\u0004 (דברים יט, יט), אלו \u0003דברי ר' מאיר. וחכמים אומרים: אין לוקין אלא ארבעים,\u0004 משום \"כאשר זמם\"."],["על המחלוקת הראשונה שבמשנתנו בין ר' מאיר וחכמים, בעדים זוממים שמשלמים כפי שזממו, האם הם גם לוקים, שואלים: \u0003בשלמא לרבנן\u0004 \u0005[נניח ל\u0006שיטת \u0005חכמים]\u0006 הרי \"והכהו... \u0003כדי רשעתו\"\u0004 (דברים כה, ב) \u0003כתיב\u0004 \u0005[נאמר]\u0006 במי שנתחייב מלקות, ומדיוק המלים נלמד: \u0003משום רשעה אחת אתה מחייבו,\u0004 בעונש אחד, \u0003ואי\u0004 (ואין) \u0003אתה מחייבו\u0004 \u0003משום שתי רשעיות,\u0004 בשני עונשים. \u0003אלא ר' מאיר מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שמחייב אדם בשני עונשים על עבירה אחת?","\u0003אמר עולא: גמר\u0004 \u0005[לומד\u0006 הוא\u0005]\u0006 דין זה \u0003ממוציא שם רע\u0004 על אשתו, שזנתה קודם שנשאה, \u0003מה מוציא שם רע לוקה ומשלם,\u0004 שהרי נאמר שם \"ויסרו אותו, וענשו אותו מאה כסף\" (דברים כב, יח-יט) — \u0003אף כל\u0004 העובר עבירה שיש בה צד מלקות וצד תשלומים \u0003לוקה ומשלם.\u0004 ומקשים על השוואה זו: \u0003מה למוציא שם רע שכן קנס,\u0004 תשלום קצוב מיוחד שחייבה אותו התורה, ואיך ניתן ללמוד ממנו לתשלום שאינו קנס, כגון זה של עדים זוממים? ומשיבים: \u0003סבר לה\u0004 \u0005[סבור\u0006 ר' מאיר \u0005בענין זה]\u0006 \u0003כר' עקיבא,\u0004 ש\u0003אמר:\u0004 מה שמשלמים \u0003עדים זוממין\u0004 כאשר זממו — \u0003קנסא\u0004 \u0005[קנס]\u0006 \u0003הוא.\u0004","ומעירים: \u0003איכא דמתני להא\u0004 \u0005[יש ששונים את\u0006 האמרה \u0005הזו]\u0006 של \u0003עולא אהא\u0004 \u0005[על\u0006 דבר \u0005זה],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 נאמר בקרבן הפסח \u0003\"לא תותירו ממנו עד בקר והנתר ממנו עד בקר\u0004 באש תשרופו\" (שמות יב, י), \u0003בא הכתוב ליתן\u0004 מצות \u0003עשה\u0004 של שריפה \u0003אחר לא תעשה\u0004 של \"לא תותירו\", \u0003לומר שאין לוקין עליו,\u0004 אם הותיר במזיד. אלו \u0003דברי ר' יהודה.\u0004 כי לאו זה הוא \"לאו הניתק לעשה\", שיש מצות עשה שבאה לתקנו ולהשלימו, ואין לוקים על לאו שכזה.","\u0003ר' עקיבא אומר: לא מן השם הוא זה\u0004 כלומר, לא מטעם זה אין לוקים עליו, \u0003אלא משום דהוה ליה\u0004 \u0005[שהריהו]\u0006 הלאו של \"לא תותירו\" \u0003לאו שאין בו מעשה,\u0004 שהרי ההותרה היא הימנעות ממעשה, ולא עשיית מעשה אסור, \u0003וכל לאו שאין בו מעשה אין לוקין עליו.\u0004 ומדייקים: \u0003מכלל\u0004 מחלוקת זו יש להבין ש\u0003ר' יהודה\u0004 המחייב מלקות \u0003סבר\u0004 \u0005[סבור]\u0006 \u0003לאו שאין בו מעשה לוקין עליו. מנא ליה\u0004 \u0005[מנין לו\u0006 שלוקים על לאו כזה\u0005]?\u0006","\u0003אמר עולא: גמר\u0004 \u0005[לומד]\u0006 ר' יהודה \u0003ממוציא שם רע, מה מוציא שם רע\u0004 שהוא \u0003לאו שאין בו מעשה,\u0004 שהרי עבר עבירה בדיבור, ולא עשה מעשה, \u0003לוקין עליו\u0004 — \u0003אף כל לאו שאין בו מעשה לוקין עליו.\u0004 ועל לימוד זה מקשים: \u0003מה למוציא שם רע,\u0004 שיש בו צד חמור, \u0003שכן\u0004 גם \u0003לוקה ו\u0004גם \u0003משלם\u0004 על אותה עבירה, מה שאין כן בדינים אחרים, וכיון שכן — אי אפשר ללמוד ממנו ללאו אחר שאין בו מעשה שילקו עליו!","\u0003אלא אמר ריש לקיש: גמר\u0004 \u0005[לומד]\u0006 ר' יהודה כלל זה \u0003מעדים זוממין, מה עדים זוממין\u0004 — \u0003לאו שאין בו מעשה לוקין עליו, אף כל לאו שאין בו מעשה\u0004 — \u0003לוקין עליו.\u0004 וחוזרים ומקשים: אף מכאן אין להביא ראיה, \u0003מה לעדים זוממין שכן\u0004 יש בהם חומרה מיוחדת, ש\u0003אין צריכין התראה\u0004 מוקדמת לפני המעשה כדי להענישם, וכרגיל אין אדם נענש בעונש גוף אלא אם כן התרו בו מראש שלא יעבור עבירה זו!","ומשיבים: \u0003מוציא שם רע יוכיח,\u0004 שיש בו צורך בהתראה, ולוקה על לאו שאין בו מעשה. \u0003וחזר הדין\u0004 חוזרת ההוכחה למקומה, שאנו אומרים: \u0003לא ראי זה כראי זה,\u0004 אין דומה דין עדים זוממים לדין מוציא שם רע, \u0003ולא ראי זה כראי זה,\u0004 אינו דומה דין מוציא שם רע לדין עדים זוממים, \u0003הצד השוה שבהן\u0004 הוא: \u0003לאו שאין בו מעשה ולוקין עליו, אף כל לאו שאין בו מעשה לוקין עליו.\u0004","ומקשים: \u0003מה להצד השוה שבהן שכן\u0004 שניהם הם \u0003קנס,\u0004 ולא ניתן ללמוד מהם, איפוא, לאיסורים אחרים שאין בהם קנס! את הקושיה הזו דוחים: \u0003הא לא קשיא\u0004 \u0005[זו אינה קשה]\u0006 כי \u0003ר' יהודה לא סבר לה\u0004 \u0005[אינו סבור אותה\u0006 בענין זה\u0005]\u0006 \u0003כר' עקיבא,\u0004 שמה שעדים זוממים משלמים נחשב קנס.","\u0003אלא\u0004 יש דחיה אחרת: \u0003מה להצד השוה שבהן\u0004 — \u0003שכן יש בהן,\u0004 בכל אחד מהם, \u0003צד חמור\u0004 שאינו קיים בדינים אחרים, במוציא שם רע — שלוקה ומשלם, ובעדים זוממים — שאינם צריכים התראה, וכיון שיש בהם צד חמור ומיוחד אי אפשר ללמוד מהם להלכות אחרות! ומסבירים: \u0003ור' יהודה\u0004 ענין זה של \u0003צד חמור לא פריך\u0004 \u0005[אינו מקשה],\u0006 שלדעתו צד חמור שאינו שווה בשני הדינים אינו נימוק מספיק כדי לדחות בגללו את הלימוד מן הצד השווה שבהם.","ושבים לדון במשנתנו, בעדים שהעידו על פלוני שחייב מלקות, שלדעת ר' מאיר לוקים גם משום \"לא תענה ברעך עד שקר\" וגם משום \"ועשיתם לו כאשר זמם\", ואילו לדעת חכמים לוקים רק משום \"כאשר זמם\". ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003האי\u0004 \u0005[\u0006את הפסוק \u0005הזה]\u0006 \u0003\"לא תענה ברעך עד שקר\"\u0004 (שמות כ, יג) \u0003מאי דרשי ביה\u0004 \u0005[מה\u0006 הם \u0005דורשים בו]\u0006 מה הם למדים ממנו אם אין לוקים עליו?","ומשיבים: \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 פסוק \u0005נצרך להם]\u0006 \u0003ל\u0004שם \u0003אזהרה לעדים זוממין,\u0004 שכל עונש האמור בתורה צריך אזהרה — איסור מפורש לעשות אותו דבר שנענשים עליו, וכך גם עונשם של עדים זוממים, צריך שיהא איסור בצידו. ושואלים: \u0003ור' מאיר,\u0004 הסבור שלאו זה לוקים עליו, \u0003אזהרה לעדים זוממין\u0004 \u0003מנא ליה\u0004 \u0005[מנין לו]?\u0006 \u0003אמר ר' ירמיה: נפקא ליה\u0004 \u0005[יוצא לו]\u0006 דין זה \u0003מ\u0004הכתוב האמור בפרשת עדים זוממים \u0003\"והנשארים ישמעו ויראו ולא יסיפו\u0004 לעשות \u0003עוד\u0004 כדבר הרע הזה בקרבך\" (דברים יט, כ), ו\"לא יוסיפו\" הוא האזהרה, שאסור לעשות כמעשה העדים הזוממים.","ומן הצד האחר, \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 מה הם למדים ממקרא זה? \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 פסוק \u0005נצרך לו]\u0006 לשיטת חכמים,"],["\u0003להכרזה,\u0004 שכאשר מוציאים אותם להריגה מצוה על בית הדין להודיע ולפרסם ברבים שעל עבירה זו הם נענשים, כדי להרתיע את הכל למונעם מן העבירה. ומן הצד האחר, \u0003ור' מאיר\u0004 מהיכן למד הוא דין זה של \u0003הכרזה? מ\u0004המלים \u0003\"ישמעו ויראו\" נפקא\u0004 \u0005[יוצא\u0006 לו\u0005],\u0006 ואילו האזהרה באה מסוף הכתוב, \"ולא יוסיפו עוד\"\u0005.\u0006","כאשר מענישים את העדים הזוממים ב\"כאשר זמם לעשות לאחיו\" \u0003משלשין\u0004 (מחלקים אותו ביניהם) \u0003ב\u0004עונש של \u0003ממון, ואין משלשין ב\u0004עונש \u0003מכות.\u0004 ומסבירים: \u0003כיצד? העידוהו\u0004 שני עדים \u0003שהוא חייב לחבירו מאתים זוז ונמצאו זוממין\u0004 — \u0003משלשין\u0004 \u0003ביניהם\u0004 העדים את הסכום הזה ומשלמים לו יחד מאתיים זוז. \u0003אבל אם העידוהו שהוא חייב מלקות ארבעים ונמצאו זוממין\u0004 — \u0003כל אחד ואחד\u0004 מן העדים \u0003לוקה ארבעים.\u0004","ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שאין מחלקים במלקות? \u0003אמר אביי: נאמר \"רשע\" בחייבי מלקיות\u0004 (דברים כה, א) \u0003ונאמר \"רשע\" בחייבי מיתות בית דין\u0004 (במדבר לה, לא), \u0003מה להלן\u0004 לגבי חייבי מיתות בית דין — \u0003אין מיתה למחצה, אף כאן\u0004 במלקות — \u0003אין מלקות למחצה,\u0004 שמספר המלקות הוא שיעור שלם, ואין מקום לחלק אותו, ואם האדם נידון למלקות — מלקים אותו את כל השיעור כולו.","\u0003רבא אמר,\u0004 טעם אחר: \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 לקיים \u0003\"כאשר זמם לעשות לאחיו\"\u0004 (דברים יט, יט) \u0003וליכא\u0004 \u0005[ואין\u0006 זה מתקיים \u0005כאן]\u0006 אם אין מלקים אותו ארבעים. ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003ממון נמי\u0004 \u0005[גם כן],\u0006 הלוא כל אחד מהם רצה לגרום לאחיו נזק זה! ומשיבים: \u0003ממון מצטרף,\u0004 שהרי בסופו של דבר הוא מקבל סכום מלא, \u0003מלקות לא מצטרף\u0004 אין חלקי עונש מלקות מצרפים, שהרי מלקות לאחד אינם מלקות לאחר.","\u0003אין העדים נעשים זוממין עד שיזימו\u0004 המזימים \u0003את\u0004 העדים \u0003עצמן\u0004 כלומר, שההזמה מתייחסת לגוף עדים ולא לתוכן עדותם.","\u0003כיצד? אמרו \"מעידין אני באיש פלוני שהרג את הנפש\",\u0004 וכללו בעדותם, כנדרש, גם את המקום והזמן המדוייק אליו מתייחסת עדותם. ובאו עדים אחרים ו\u0003אמרו להם: היאך אתם מעידין? שהרי נהרג זה, או ההורג זה, היה עמנו אותו היום\u0004 שאתם מעידים עליו \u0003במקום פלוני,\u0004 שאינו המקום עליו העידו העדים הראשונים, אף על פי שיש בזה הכחשת תוכן דברי העדות הראשונה — \u0003אין אלו\u0004 הראשונים נחשבים בכך לעדים \u0003זוממין. אבל\u0004 אם \u0003אמרו להם\u0004 העדים השניים: \u0003היאך אתם מעידין? שהרי אתם\u0004 עצמכם \u0003הייתם עמנו אותו היום במקום פלוני\u0004 — \u0003הרי אלו זוממין, ונהרגין\u0004 העדים הראשונים \u0003על פיהם.\u0004","\u0003באו\u0004 עוד שני עדים \u0003אחרים\u0004 והעידו גם כן שכך היה מעשה, שאותו פלוני הרג את הנפש — \u0003והזימום\u0004 המזימים הראשונים, שאמרו שאף אלה היו איתם במקום אחר באותו יום, וכן \u0003באו\u0004 עוד \u0003אחרים והזימום\u0004 העדים המזימים, \u0003אפילו\u0004 היו אלו \u0003מאה\u0004 כיתות של עדים שהוזמו כולם על ידי אותם שני עדים מזימים — \u0003כולם יהרגו,\u0004 שהרי דין הזמה קיים לגבי כולם, וכוח שני עדים גדול ככוחם של עדים רבים. \u0003ר' יהודה אומר: איסטטית\u0004 (כת סוטה) \u0003היא זו\u0004 של העדים המזימים, ויש לחשוד בה שהם רוצים להזים את כל מי שמעיד בעדות זו, \u0003ואינו נהרג אלא כת הראשונה בלבד.\u0004","על ההלכה במשנה שהעדים נעשים זוממים רק כאשר מזימים אותם עצמם, שמעידים עליהם שהם לא היו באותו מקום, שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר רב אדא:\u0004 ש\u0003אמר קרא\u0004 \u0005[המקרא]\u0006 בפרשת עדים זוממים: \u0003\"והנה עד שקר העד שקר ענה\u0004 באחיו\" (דברים יט, יח), והכוונה: \u0003עד שתשקר\u0004 (תתברר כשקר) \u0003גופה של עדות\u0004 כלומר, שהעדות בגופם של העדים הוכחה כבלתי נכונה, שכן העדים לא היו שם כלל באותו זמן.","\u0003דבי\u0004 \u0005[\u0006החכם \u0005מבית מדרשו]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]\u0006 ראיה אחרת: נאמר \"כי יקום עד חמס באיש \u0003לענות בו סרה\"\u0004 (דברים יט, טז) \u0003עד שתסרה\u0004 (תתקלקל) \u0003גופה של עדות,\u0004 ולא הכחשה בענין אחר.","\u0003אמר רבא: באו שנים ואמרו \"במזרח בירה\u0004 (ארמון) \u0003הרג פלוני את הנפש\", ובאו שנים\u0004 אחרים \u0003ואמרו\u0004 לעדים הללו: \u0003והלא במערב בירה עמנו הייתם\u0004 באותה שעה, ואיך מעידים אתם על מה שהיה בצד האחר? \u0003חזינן\u0004 \u0005[רואים אנו],\u0006 \u0003אי כדקיימי\u0004 \u0005[אם כאשר עומדים\u0006 אנשים\u0005]\u0006 \u0003במערב\u0004 ה\u0003בירה מיחזא חזו\u0004 \u0005[רואים הם]\u0006 \u0003למזרח בירה\u0004 ואת הנעשה שם, אם כן \u0003אין אלו זוממין,\u0004 שיכול להיות שראו את המאורע ממקומם במערב הבירה. \u0003ואם לאו\u0004 \u0005[לא],\u0006 שאי אפשר לראות משם — \u0003הרי אלו זוממין.\u0004","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הדבר, ומה החידוש בכך? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003ליחוש לנהורא בריא\u0004 \u0005[שנחשוש לאור\u0006 עיניים \u0005בהיר\u0006 יותר\u0005],\u0006 שמא סתם אדם אינו יכול לראות במרחק זה, אבל העדים הללו יכולים לראות, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין חוששים לדבר כגון זה.","\u0003ו\u0004עוד \u0003אמר רבא: באו שנים ואמרו \"ב\u0004עיר \u0003סורא בצפרא בחד בשבתא\u0004 \u0005[בבוקר ב\u0006יום \u0005ראשון בשבת\u0006 בשבוע\u0005]\u0006 \u0003הרג פלוני את הנפש\", ובאו שנים ואמרו\u0004 לעדים הראשונים: \u0003\"בפניא בחד בשבתא\u0004 \u0005[בערב ב\u0006אותו יום \u0005ראשון בשבת]\u0006 \u0003עמנו הייתם ב\u0004עיר \u0003נהרדעא\", חזינן\u0004 \u0005[רואים אנו],\u0006 \u0003אי מצפרא לפניא מצי אזיל\u0004 \u0005[אם מן הבוקר לערב יכול\u0006 אדם \u0005ללכת]\u0006 \u0003מסורא לנהרדעא\u0004 — הרי \u0003לא הוו\u0004 \u0005[אינם]\u0006 \u0003זוממין,\u0004 שהרי יתכן שראו את אותו שהרג בבוקר בסורא, ואחר כך הלכו לנהרדעא, \u0003ואי לאו\u0004 \u0005[ואם לא]\u0006 שאין הדבר אפשרי — \u0003הוו\u0004 \u0005[הריהם]\u0006 \u0003זוממין.\u0004","ותוהים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003ליחוש לגמלא פרחא\u0004 \u0005[נחשוש לגמל פורח],\u0006 שמא רכבו על גמל מהיר ביותר, ואף שכרגיל אי אפשר לעבור מרחק זה באותו זמן — הם הצליחו לעשות זאת, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין אנו חוששים לכך.","\u0003ו\u0004עוד \u0003אמר רבא: באו שנים ואמרו \"בחד בשבתא\u0004 \u0005[באחד בשבת,\u0006 ביום ראשון בשבוע\u0005]\u0006 \u0003הרג פלוני את הנפש\", ובאו שנים\u0004 אחרים \u0003ואמרו \"עמנו הייתם בחד בשבתא\u0004 \u0005[באחד בשבת],\u0006 \u0003אלא\u0004 למחרת \u0003בתרי בשבתא\u0004 \u0005[בשני בשבת]\u0006 \u0003הרג פלוני\u0004 זה \u0003את הנפש\". ולא עוד אלא, אפילו אמרו\u0004 העדים השניים \"לפני כן, ב\u0003ערב שבת הרג פלוני את הנפש\"\u0004 — הרי העדים הראשונים \u0003נהרגין,\u0004 למרות שאותו אדם מתחייב מיתה גם ללא עדותם, ומדוע? \u0003דבעידנא דקא מסהדי, גברא לאו בר קטלא הוא\u0004 \u0005[שבזמן שהעידו, האיש לא היה בן מוות]\u0006 שהרי עדיין לא נידון בבית הדין למוות, והם אמרו דבר שקר וזממו להורגו.","ושואלים: \u0003מאי קא משמע לן? תנינא\u0004 \u0005[מה הוא משמיע לנו\u0006 בכך? הלוא \u0005שנינו]\u0006 במקרה בו העידו שתי כתות שונות של עדים על אדם שהרג: \u0003לפיכך, נמצאת\u0004 כת \u0003אחת מהן זוממת\u0004 — \u0003הוא\u0004 הנאשם, \u0003והן\u0004 העדים זוממים, \u0003נהרגין\u0004 על ידי בית דין; הוא נהרג — משום שהיתה כת שהעידה עליו שהרג, והם, כת העדים שהוזמו, נהרגים כדין עדים זוממים, שכן שיקרו בעדותם. \u0003ו\u0004הכת \u0003השניה,\u0004 שלא הוזמה, \u0003פטורה.\u0004 משמע שאף במקום שהנאשם חייב מיתה, מכל מקום כיון שהעדים העידו עליו עדות שקר כאשר עדיין לא נתחייב מיתה בבית דין — הרי הם זוממים!","ומשיבים: \u0003סיפא\u0004 \u0005[הסוף]\u0006 של ההלכה — \u0003מה שאין כן בגמר דין, איצטריכא ליה\u0004 \u0005[נצרך היה לו]\u0006 לאומרו, שבו יש חידוש, ולשם כך הובא הדין הראשון. ומהו אותו דין? שאם \u0003באו שנים\u0004 ביום שלישי, \u0003ואמרו \"בחד בשבתא\u0004 \u0005[באחד בשבת]\u0006 \u0003נגמר דינו של פלוני\u0004 בבית דין מסויים למיתה\", \u0003ובאו שנים ואמרו \"בחד בשבתא עמנו הייתם\u0004 במקום פלוני, ולא יכולתם להיות באותו בית דין, \u0003אלא בערב שבת נגמר דינו של\u0004 אותו \u0003פלוני\"\u0004 — אין העדים הראשונים נהרגים. \u0003ולא עוד אלא, אפילו אמרו\u0004 העדים השניים \u0003\"בתרי בשבתא\u0004 \u0005[בשני בשבת]\u0006 \u0003נגמר דינו של פלוני\"\u0004 — \u0003אין אלו\u0004 העדים הראשונים \u0003נהרגין.\u0004 ומדוע? \u0003דבעידנא דקא מסהדי, גברא בר קטלא הוא\u0004 \u0005[שבזמן שהעידו\u0006 עליו, ביום שלישי, כבר היה \u0005האיש בן מוות]\u0006 שהרי כבר נגמר דינו למיתה, והרי אלו כבאים להרוג אדם מת.","ומוסיפים: \u0003ו\u0004כשם שהוא לענין דין מיתה, \u0003כן\u0004 הדין \u0003לענין תשלומי קנס,\u0004 וכגון זה:","\u0003באו שנים ואמרו \"בחד בשבתא\u0004 \u0005[באחד בשבת]\u0006 \u0003גנב וטבח ומכר\u0004 שור או שה\", וחייב לשלם קנס, פי ארבעה (או חמישה) ממה שגנב, \u0003ובאו שנים ואמרו \"בחד בשבתא\u0004 \u0005[באחד בשבת]\u0006 \u0003עמנו הייתם, אלא בתרי בשבתא\u0004 \u0005[בשני בשבת]\u0006 \u0003גנב וטבח ומכר\"\u0004 — \u0003משלמין\u0004 העדים הראשונים לנאשם תשלומי ארבעה או חמישה, שהרי כשהעידו עליו עדיין לא גנב. \u0003ולא עוד אלא, אפילו אמרו\u0004 העדים השניים \"קודם לכן, \u0003בערב שבת גנב וטבח ומכר\"\u0004 — \u0003משלמין\u0004 העדים הראשונים ארבעה או חמישה. ומדוע? \u0003דבעידנא דקא מסהדי גברא לאו בר תשלומין הוא\u0004 \u0005[שבזמן שהעידו עליו\u0006 העדים הראשונים, עדיין \u0005לא היה האיש\u0006 הנאשם \u0005בר תשלומים],\u0006","שהרי עדיין לא נתחייב בית דין לשלם קנס זה, ויכול היה להודות בעצמו ולהיפטר, ואם כן זממו לחייב אדם שלא היה חייב. אולם אם \u0003באו שנים\u0004 ביום שלישי \u0003ואמרו \"בחד בשבתא\u0004 \u0005[באחד בשבת]\u0006 \u0003גנב וטבח ומכר ונגמר דינו\u0004 לשלם ארבעה או חמישה\", \u0003ובאו שנים ואמרו \"בחד בשבתא\u0004 \u0005[באחד בשבת]\u0006 \u0003עמנו הייתם, אלא ערב שבת גנב וטבח ומכר ונגמר דינו\"\u0004 — אין העדים הראשונים משלמים. \u0003ולא עוד אלא, אפילו אמרו\u0004 העדים השניים \u0003\"בחד בשבתא\u0004 \u0005[באחד בשבת]\u0006 \u0003גנב וטבח ומכר\u0004 כדברי הראשון, \u0003ו\u0004אולם \u0003בתרי בשבתא\u0004 \u0005[בשני בשבת]\u0006 \u0003נגמר דינו\u0004 לשלם\" — \u0003אין\u0004 הראשונים \u0003משלמין, דבעידנא דקא מסהדי\u0004 \u0005[ש\u0006הרי \u0005בזמן שבו העידו,\u0006 ביום שלישי\u0005]\u0006 \u0003גברא בר\u0004 \u0005[האיש בן]\u0006 \u0003תשלומין הוא,\u0004 שהרי התחייב כבר בתשלומים בבית דין, ולכן אינם נחשבים לעדים זוממים.","שנינו במשנה שאם כת אחת של עדים הזימה כתות רבות שהעידו על אדם שהרג, \u0003ר' יהודה אומר: איסטטית היא זו,\u0004 הכת של המזימים, ואין הורגים אלא את כת העדים הזוממים הראשונה שהזימו."],["ותוהים: \u0003אי\u0004 \u0005[אם]\u0006 סבור ר' יהודה ש\u0003איסטטית היא\u0004 כת עדים \u0003זו,\u0004 ואנו חושדים בהם שאינם עדי אמת — \u0003אפילו כת ראשונה\u0004 שהוזמה על ידם \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 תיהרג! \u0003אמר ר' אבהו:\u0004 מדובר במקרה \u0003ש\u0004כבר \u0003קדמו והרגו\u0004 את הכת הראשונה. והוא מה שאמר ר' יהודה שאינה נהרגת אלא הכת הראשונה, שכבר נהרגה.","ושואלים: אם כך הוא, \u0003מאי דהוה הוה\u0004 \u0005[מה שהיה היה]\u0006 ומה טעם לקבוע דבר זה כהלכה? \u0003אלא\u0004 יש לדחות הסבר זה. \u0003אמר רבא, הכי קאמר\u0004 \u0005[כך הוא אומר]\u0006 כך צריך להבין את דברי ר' יהודה: \u0003אם אינה אלא כת אחת\u0004 שהוזמה — \u0003נהרגת, אי איכא טפי\u0004 \u0005[אם יש יותר]\u0006 מכת אחת — \u0003אין נהרגין\u0004 כלל. ומקשים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003\"בלבד\" קאמר\u0004 \u0005[אומר],\u0006 כאשר הוא אומר שאין נהרגת אלא כת ראשונה בלבד — משמע שמדובר כשיש יותר, ולפי פירושו של רבא אין לשון זו מדוייקת! ומעירים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר.","ובקשר למחלוקת שבמשנתנו מספרים, \u0003ההיא איתתא דאתאי סהדי ואישתקור\u0004 \u0005[אשה אחת שהביאה עדים\u0006 להעיד באיזה ענין לטובתה, \u0005ונמצאו שקרנים],\u0006 \u0003אייתי סהדי ואישתקור\u0004 \u0005[הביאה עדים\u0006 אחרים, \u0005ונמצאו\u0006 גם הם \u0005שקרנים].\u0006 \u0003אזלה אייתי סהדי אחריני\u0004 \u0005[הלכה\u0006 ו\u0005הביאה עדים אחרים]\u0006 ש\u0003לא אישתקור\u0004 \u0005[נמצאו שקרנים],\u0006 ודנו חכמים אם יש לקבל את עדותם של אלו. \u0003אמר ריש לקיש: הוחזקה\u0004 אשה \u0003זו\u0004 להביא עדי שקר, ולכן, לא נקבל את עדותם של אלו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אלעזר:\u0004 גם \u0003אם היא\u0004 אשה זו \u0003הוחזקה\u0004 כשקרנית, \u0003כל ישראל מי\u0004 \u0005[האם]\u0006 \u0003הוחזקו?\u0004 ומדוע בגללה נחשוד בעדים אלו שהם משקרים?","מסופר, \u0003זימנין הוו יתבי\u0004 \u0005[פעם\u0006 אחרת \u0005היו יושבים]\u0006 ריש לקיש ור' אלעזר \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן,\u0004 \u0003אתא כי האי מעשה לקמייהו\u0004 \u0005[בא מעשה כגון זה לפניהם]\u0006 לדון בו. \u0003אמר ריש לקיש: הוחזקה זו\u0004 כשקרנית. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן: אם הוחזקה זו\u0004 כשקרנית — \u0003כל ישראל מי\u0004 \u0005[האם]\u0006 \u0003הוחזקו\u0004 כשקרנים? כששמע ריש לקיש תשובה זו מר' יוחנן, בדיוק כפי שאמר לו קודם לכן ר' אלעזר, \u0003הדר חזיה\u0004 \u0005[החזיר\u0006 פניו \u0005והביט]\u0006 \u0003ל\u0004עבר \u0003ר' אלעזר בישות\u0004 \u0005[ב\u0006עין \u0005רעה],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שמעת מילי מבר נפחא\u0004 \u0005[דברים מבן הנפח,\u0006 מר' יוחנן\u0005]\u0006 \u0003ולא אמרת לי משמיה\u0004 \u0005[בשמו]?\u0006 אילו ידעתי שזו שיטת ר' יוחנן הייתי מקבל אותה.","ומציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי \u0003ריש לקיש\u0004 ש\u0003אמר\u0004 את דבריו, שאשה זו הוחזקה כמביאה עדי שקר, סבור \u0003כר' יהודה\u0004 במשנתנו, שחושד בעדותה של אותה כת של עדים כשקר, למרות שאין לכך ראיה ברורה, אלא על סמך אומדנא, \u0003ו\u0004אילו \u0003ר' יוחנן דאמר כרבנן\u0004 \u0005[שאומר כ\u0006דעת \u0005חכמים]\u0006 שאין מסתמכים על אומדנא כזאת, כל זמן שאין לכך ראיות של ממש?","ודוחים: \u0003אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]\u0006 \u0003ריש לקיש: אנא דאמרי לך\u0004 \u0005[אני שאמרתי\u0006 דברי\u0005]\u0006 \u0003אפילו לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים],\u0006 שכן \u0003עד כאן לא קא אמרי רבנן התם\u0004 \u0005[\u0006שמענו \u0005שאמרו חכמים שם,\u0006 במשנתנו\u0005]\u0006 שסומכים על הכת המזימה אף שהזימה כמה כתות עדים, אלא \u0003דליכא דקא מהדר\u0004 \u0005[כאשר אין\u0006 לפנינו \u0005מי שמחזר]\u0006 לשכור עדי שקר, ואפשר לומר שאמת אמרו. \u0003אבל הכא איכא הא דקא מהדרא\u0004 \u0005[כאן יש\u0006 לפנינו אשה \u0005זו שמחזרת]\u0006 אחרי עדי שקר ויש לחשוד בה.","\u0003ור' יוחנן אמר לך\u0004 \u0005[\u0006יכול היה \u0005לומר לך]:\u0006 \u0003אנא דאמרי\u0004 \u0005[אני שאמרתי\u0006 את דברי\u0005]\u0006 \u0003אפילו לר' יהודה,\u0004 שכן \u0003עד כאן לא קאמר\u0004 \u0005[\u0006שמענו \u0005שאמר]\u0006 \u0003ר' יהודה התם\u0004 \u0005[שם,\u0006 במשנתנו\u0005]\u0006 שיש לחשוד בכת המזימה, אלא כשהדברים עצמם מורים כן, \u0003דאמרינן: אטו כולי עלמא גבי הני הוו קיימי\u0004 \u0005[שאנו אומרים:\u0006 \u0005וכי כולם,\u0006 כל העדים שהוזמו, \u0005אצל\u0006 מזימים \u0005אלה היו עומדים]?\u0006 ויש איפוא להניח שכל מה שהזימו — לא היה נכון. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 יש לומר כי \u0003הני ידעי בסהדותא, והני לא ידעי בסהדותא\u0004 \u0005[\u0006עדים \u0005אלה,\u0006 שלא הוכח ששיקרו, \u0005יודעים בעדות, ואלה אינם יודעים בעדות],\u0006 ולכן גם אם הוכח שהעדים הראשונים משקרים, אינו הוכחה שגם האחרים משקרים.","\u0003אין העדים זוממין נהרגין עד שיגמר הדין\u0004 של הנידון בבית הדין ליהרג על פי עדותם. ומנין שכך הוא? \u0003שהרי הצדוקין אומרים\u0004 אינו כן, אלא אין העדים הזוממים נהרגים, אלא \u0003עד שיהרג\u0004 הנידון על פי עדותם, משום \u0003שנאמר \"נפש תחת נפש\"\u0004 (שמות כא, כב. וראה דברים יט, כא).","\u0003אמרו להם חכמים: והלא כבר נאמר \"ועשיתם לו כאשר זמם לעשות לאחיו\"\u0004 (דברים יט, יט) \u0003והרי\u0004 מכאן משמע שמדובר כש\u0003אחיו\u0004 (כלומר, הנידון) \u0003קיים. ואם כן למה נאמר \"נפש תחת נפש\"\u0004 — ללמדנו פרט אחר בדין זה: \u0003יכול\u0004 כבר \u0003משעה שקבלו\u0004 הדיינים את \u0003עדותן\u0004 בבית דין \u0003יהרגו,\u0004 למרות שלא נגמר דינו למיתה — \u0003תלמוד לומר: \"נפש תחת נפש\", הא אינם נהרגין עד שיגמר הדין,\u0004 משעה שעומדים ליטול את נפשו, ולא קודם לכן.","ובענין ההלכה האמורה במשנה, \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 \u0003בריבי\u0004 (אדם גדול אחד): אם עדיין \u0003לא הרגו\u0004 את הנידון — העדים הזוממים \u0003נהרגין,\u0004 אם \u0003הרגו\u0004 — \u0003אין נהרגין. אמר\u0004 לו \u0003אביו\u0004 של אותו חכם, שגם הוא היה איש חשוב: \u0003בני, לאו\u0004 (וכי לא) \u0003קל וחומר הוא,\u0004 שאם כאשר לא הרגו הם נהרגים — כל שכן שאם הרגו הם נהרגים!","\u0003אמר לו: לימדתנו רבינו שאין עונשין מן הדין\u0004 (מקל וחומר) אלא צריך הוכחה מפורשת בכתוב זה. ומביאים ראיה לכלל זה, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 על הכתוב בפרשת עונשם של איסורי עריות \u0003\"איש אשר יקח [את] אחתו בת אביו או בת אמו\"\u0004 (ויקרא כ, יז), אמרו חכמים: \u0003אין לי\u0004 מן הכתוב \u0003אלא בת אביו שלא\u0004 (שאינה) \u0003בת אמו,\u0004 או \u0003בת אמו שלא בת אביו.\u0004 ואולם, אחות שהיא \u0003בת אמו ו\u0004גם \u0003בת אביו מנין\u0004 שגם עליה חייב? \u0003תלמוד לומר \"ערות אחתו גלה\"\u0004 (ויקרא כ, יז), כלומר, כל שהיא אחותו — חייב עליה.","וממשיכה הברייתא בדיון: \u0003עד שלא יאמר\u0004 הכתוב במפורש — \u0003יש לי\u0004 להוכיח דבר זה \u0003בדין\u0004 (מקל וחומר): \u0003אם ענש על בת אביו שלא בת אמו, ו\u0004כן ענש על \u0003בת אמו שלא בת אביו\u0004 — אחותו שהיא \u0003בת אביו ובת אמו לא כל שכן\u0004 שייענש עליה? \u0003הא\u0004 (הרי) \u0003למדת\u0004 מכאן \u0003שאין עונשין מן הדין,\u0004 אלא צריך הוכחה מן הכתוב.","וממשיכה הברייתא: \u0003עונש\u0004 לאחותו שהיא בת אביו ואמו \u0003שמענו\u0004 בכתוב זה, \u0003אזהרה\u0004 כלומר, מקור שבו נאמר האיסור הזה, \u0003מנין\u0004 לנו? \u0003תלמוד לומר \"ערות אחותך בת אביך או בת אמך...\u0004 לא תגלה\" (ויקרא יח, ט). \u0003אין לי אלא\u0004 אזהרה ל\u0003בת אביו שלא בת אמו, ובת אמו שלא בת אביו,\u0004 אבל אחותו שהיא \u0003בת אביו ובת אמו מנין\u0004 שהוא מוזהר עליה? \u0003תלמוד לומר \"ערות בת אשת אביך מולדת אביך אחותך הוא\"\u0004 (ויקרא יח יא) לומר: כל שהיא אחותך — יש עליה איסור.","ולכאורה אפשר היה לטעון גם כאן: \u0003עד שלא יאמר\u0004 הכתוב במפורש, \u0003יש לי\u0004 ללמוד דבר זה \u0003מן הדין\u0004 (מקל וחומר): \u0003מה אם הוזהר על\u0004 אחותו שהיא \u0003בת אמו שלא בת אביו,\u0004 וכן הוזהר על \u0003בת אביו שלא בת אמו,\u0004 אחות זו שהיא גם \u0003בת אביו ו\u0004גם \u0003בת אמו לא כל שכן\u0004 שהוא מוזהר עליה? \u0003הא למדת ש\u0004אף \u0003אין מזהירין מן הדין.\u0004","ומבררים: עד כאן לא למדנו אלא לענין חייבי מיתות, \u0003חייבי מלקיות מנין\u0004 שגם בהם אין עונשים מן הדין — \u0003תלמוד לומר\u0004 גזירה שווה \u0003\"רשע\" \"רשע\",\u0004 שמילה זו נאמרה גם בחייבי מיתות בית דין (\"אשר הוא רשע למות\". במדבר לה, לא), וגם בחייבי מלקות (\"והיה אם בן הכות הרשע\". דברים כה, ב).","\u0003חייבי גליות מנין\u0004 שאין לומדים את עונשם בדרך קל וחומר — \u0003אתיא\u0004 \u0005[בא]\u0006 הדבר בגזירה שווה של \u0003\"רצח\" \"רצח\",\u0004 שנאמר גם ברוצח במזיד (במדבר לה, כא) וגם ברוצח בשגגה (במדבר לה, יא), ללמדנו שבכל עונשי גוף אין למדים הלכה מקל וחומר.","ובענין ששנינו במשנתנו \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' יהודה בן טבאי\u0004 בלשון שבועה: \u0003אראה בנחמה\u0004 (אזכה לראות את הנחמה והגאולה לעתיד לבוא) \u0003אם לא הרגתי\u0004 בבית הדין \u0003עד זומם.\u0004 ואמר זאת כדי \u0003להוציא\u0004 (לבטל, לשלול) \u0003מ\u0004סברה זו המצויה ב\u0003לבן של צדוקים. שהיו\u0004 הצדוקים \u0003אומרים: אין העדים זוממין נהרגין\u0004 אלא \u0003עד שיהרג הנדון,\u0004 והוא הרג את העד הזומם אף על פי שלא נהרג הנידון.","\u0003אמר לו שמעון בן שטח: אראה בנחמה אם לא שפכת דם נקי\u0004 במה שעשית, \u0003שהרי אמרו חכמים: אין העדים זוממין נהרגין עד שיזומו שניהם, ואין לוקין עד שיזומו שניהם,\u0004 ובמקרה זה הרי הוזם רק אחד מהם ולא שניהם.","\u0003מיד קבל עליו ר' יהודה בן טבאי שאינו מורה הוראה אלא לפני שמעון בן שטח,\u0004 שלא יטעה שוב. \u0003וכל ימיו של ר' יהודה בן טבאי היה משתטח\u0004 בבכיה \u0003על קברו של אותו העד,\u0004 לבקש מחילה על שגרם לו מיתה, \u0003והיה קולו נשמע\u0004 מרחוק, \u0003וכסבורין העם לומר: קולו של הרוג\u0004 הוא זה, שבוכה. \u0003אמר\u0004 להם יהודה בן טבאי: \u0003קולי שלי הוא, תדעו\u0004 שכן הוא — \u0003למחר\u0004 (בעתיד) \u0003הוא\u0004 (כלומר, בלשון נקיה, אני) \u0003מת,\u0004 ואז \u0003אין קולו נשמע.\u0004","ומעירים על כך, \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי:\u0004 זו אינה הוכחה שאין זה קולו של ההרוג, אם לאחר מות ר' יהודה בן טבאי השתתק הקול, \u0003דלמא בדינא קם בהדיה\u0004 \u0005[שמא בדין\u0006 שמים \u0005עמד אתו],\u0006 ולכן איננו צועק עוד בעולם הזה, \u0003אי נמי פיוסי פייסיה\u0004 \u0005[או גם כן\u0006 שמא \u0005פייס אותו\u0006 ר' יהודה בן טבאי בעולם הבא\u0005]\u0006 ולכן הוא השתתק, ואין מכאן בעצם הוכחה גמורה.","נאמר: \u0003\"על פי שנים עדים או שלשה עדים יומת המת\"\u0004 (דברים יז, ו), ויש לשאול: \u0003אם מתקיימת העדות בשנים\u0004 — \u0003למה פרט הכתוב בשלשה? אלא\u0004 בא הכתוב \u0003להקיש\u0004 (להשוות) \u0003שלשה לשנים,\u0004 ללמדנו שדינם שווה: \u0003מה שלשה מזימין את השנים\u0004 — \u0003אף השנים יזומו את השלשה. ומנין\u0004 ששנים יכולים להזים \u0003אפילו מאה\u0004 עדים — \u0003תלמוד לומר\u0004 \"שלושה \u0003עדים\",\u0004 והרי מדובר כאן על עדים! אלא בא הדבר לרבות כל קבוצה של עדים, אפילו יותר משלושה, שגם שנים יכולים להזים אותם.","\u0003ר' שמעון אומר:\u0004 דבר אחר למדים מייתור הכתוב, \u0003מה שנים\u0004 שהעידו על אדם שחייב מיתה \u0003אינן נהרגין\u0004 על עדות זו \u0003עד שיהיו שניהם זוממין\u0004 — \u0003אף שלשה\u0004 שבאו להעיד כאחד, והוזמו, \u0003אינן נהרגין עד שיהיו שלשתם זוממין. ומנין\u0004 שכך הוא הדין \u0003אפילו\u0004 ב\u0003מאה\u0004 עדים — \u0003תלמוד לומר \"עדים\"\u0004 לומר, שכל עדים שבאו בקבוצה אחת דינם כעדות אחת לענין זה.","\u0003ר' עקיבא אומר: לא בא השלישי\u0004 הנזכר בכתוב זה \u0003להקל, אלא להחמיר עליו, ולעשות דינו כיוצא באלו\u0004 כמו השנים שהעיד עימם. כלומר, שאף שאפשר היה לומר שעדותו של השלישי מיותרת לאחר שכבר העידו שנים, ושמא השלישי והבאים אחריו ייפטרו, לכן בא לומר שכיון שהיה יחד איתם והוזם יחד אתם — אף הוא נהרג.","וכאן אפשר גם ללמוד מוסר השכל: \u0003ואם כן ענש הכתוב לנטפל\u0004 (למי שנספח) \u0003לעוברי עבירה\u0004 שיהיה דינו \u0003כעוברי עבירה\u0004 למרות שהעבירה כבר נעשית בלעדיו — \u0003על אחת כמה וכמה ישלם שכר לנטפל לעושי מצוה כעושי מצוה.\u0004","ועוד אפשר ללמוד מהשוואה זו: \u0003ומה שנים\u0004 אם \u0003נמצא אחד מהן קרוב או פסול\u0004 — \u0003עדותן בטלה,\u0004 שהרי אין כאן עוד עדות שני עדים, \u0003אף שלשה\u0004 שבאו להעיד כאחד אם \u0003נמצא אחד מהן קרוב או פסול עדותן\u0004 של כולם \u0003בטלה,\u0004 אף שהשניים האחרים לא נפסלו. \u0003מנין אפילו\u0004 היו \u0003מאה\u0004 עדים — \u0003תלמוד לומר \"עדים\".\u0004"],["\u0003אמר ר' יוסי: במה דברים אמורים\u0004 שאם פסול אחד מהם לעדות — בטלה כל העדות כולה — \u0003בדיני נפשות\u0004 החמורים, \u0003אבל בדיני ממונות\u0004 אף על פי שאחד העדים פסול — \u0003תתקיים העדות בשאר\u0004 העדים, ואם יש בשאר עדות מספקת, דנים על פיה. \u0003רבי אומר:\u0004 אינו כן אלא, \u0003אחד דיני ממונות ואחד דיני נפשות\u0004 דינם שווה בזה.","אבל \u0003אימתי\u0004 נאמר דבר זה שעד אחד פסול פוסל את כל העדות כולה — \u0003בזמן שהתרו בהן,\u0004 כאשר העדים התרו בנאשמים לפני שעברו, שהוכיחו על ידי כך שהם רוצים להיות עדים בדבר, ולכן הפסולים והכשרים נחשבים כחלק מעדות אחת. \u0003אבל בזמן שלא התרו בהן\u0004 — \u0003מה יעשו שני אחין שראו באחד שהרג את הנפש\u0004 יחד עם אחרים? וכי ייפטר הרוצח מעונש רק מפני שהיו שם במקרה שני קרובים?! אלא אימתי נפסלת העדות — כאשר כוונתם להעיד, אבל אם אינם באים להעיד כאחד — אין הם פוסלים את העדות.","על הדברים שאמרנו במשנה, שמאה עדים דינם כשני עדים, לדיני הזמה ועוד, \u0003אמר רבא: והוא שהעידו\u0004 כל העדים \u0003כולם בתוך כדי דיבור,\u0004 שאז הם נחשבים לכת אחת של עדים. אבל אם היה הפסק, וכל קבוצת עדים העידה לעצמה — אין אלה נחשבים לעדות אחת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדפתי לרבינא: מכדי\u0004 \u0005[הרי]\u0006 \u0003תוך כדי דיבור היכי דמי\u0004 \u0005[כיצד הוא\u0006 בדיוק\u0005]\u0006 שיעורו — \u0003כדי שאילת תלמיד לרב,\u0004 שאומר לו \"שלום עליך רבי\", כלומר, כדי אמירת שלוש מלים. והרי \u0003מאה\u0004 עדים המעידים \u0003טובא הוו\u0004 \u0005[הרבה הם]\u0006 ובוודאי שעדות כולם היא יותר משיעור זמן זה, שהרי לא ייתכן שמאה אנשים יעידו בתוך כדי דיבור!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 הכוונה היא ש\u0003כל חד וחד\u0004 \u0005[אחד ואחד]\u0006 מעיד \u0003בתוך כדי דיבור של חבירו,\u0004 וכך נוצר רצף של עדות אחת.","שנינו במשנה: \u0003ר' עקיבא אומר לא בא שלישי\u0004 להקל עליו אלא להחמיר עליו. ועוד אמרו: \u0003ומה שנים\u0004 אם היה אחד מהם קרוב או פסול — עדותם בטלה, אף בכל מספר עדים — קרוב ופסול פוסלים את העדות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: אלא מעתה,\u0004 שאנו אומרים שאם היה קרוב או פסול עד לאירוע הריהו פוסל את העדות כולה, אם כן \u0003הרוג\u0004 עצמו \u0003יציל\u0004 את הנאשם בהריגתו, שהרי הוא עצמו ראה את המעשה כאשר נהרג, וכיון שהוא פסול לעדות (שהרי הוא נוגע בדבר) אם כן נמצא שכל עדות על הריגה היא פסולה! אמר לו: מדובר \u0003כשהרגו מאחוריו,\u0004 והנהרג לא ראה כלל מי היה הרוצח.","אמר לו: אמנם מצוי הדבר שכך הורגים אדם בלא ידיעתו, אך עדיין יש להקשות: כשדנים אדם למיתה על שרבע זכר, מדוע לא נאמר ש\u0003נרבע יציל\u0004 את הרובע ממיתה, משום שהוא פסול לעדות, ויפסול את שאר העדים שראו את המעשה! ומשיבים: מדובר \u0003כשרבעו מאחוריו\u0004 ולא ראה ולא ידע מי רבע אותו, ולכן יכול ליהרג על פי העדים האחרים.","אמר לו: ועדיין נאמר שה\u0003הורג ורובע\u0004 עצמם \u0003יצילו\u0004 את עצמם ממיתה על מה שעשו, שהרי הם בוודאי ראו את המאורע, והם פסולים לעדות, שאין אדם יכול להעיד על עצמו! \u0003אישתיק\u0004 \u0005[שתק]\u0006 אביי, שלא מצא תשובה לדבר. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 רב פפא \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003רבא\u0004 עם שאלה זו, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 נאמר שם \"על פי שני עדים או על פי שלשה עדים \u0003יקום דבר\"\u0004 (דברים יט, טו) — לומר, \u0003במקימי דבר הכתוב מדבר\u0004 כלומר, דווקא בעדים, שהם מקיימים את הדבר מבחינה משפטית, ולא בבעלי הדבר, ולכן אין מקום לקושיות אלה.","שנינו במשנה ש\u0003אמר ר' יוסי: במה דברים אמורים .\u0004 — בדיני נפשות, אבל בדיני ממונות תתקיים העדות בשאר. ורבי חולק וסבור שאין הבדל בין דיני נפשות לדיני ממונות. ועוד אמרו שכל זה אמור בזמן שהתרו בהם, אבל כשלא התרו בהם, אפילו היה ביניהם פסול — העדות כשירה, כי אחרת \u0003מה יעשו שני אחים\u0004 שראו באחד שהרג את הנפש. ושואלים: \u0003היכי אמרינן להו\u0004 \u0005[איך אנו,\u0006 בית הדין, \u0005אומרים להם]\u0006 לעדים כדי לברר אם באו להעיד?","\u0003אמר רבא: הכי אמרינן להו\u0004 \u0005[כך אנו אומרים להם]\u0006 לבאים לבית דין: האם \u0003למיחזי אתיתו או לאסהודי אתיתו\u0004 \u0005[לראות\u0006 את הדין \u0005באתם או להעיד באתם]?\u0006 \u0003אי אמרי לאסהודי אתו\u0004 \u0005[אם אומרים\u0006 ש\u0005להעיד באו],\u0006 \u0003נמצא אחד מהן קרוב או פסול\u0004 — \u0003עדותן\u0004 של כולם \u0003בטלה, אי אמרי למיחזי אתו\u0004 \u0005[אם אומרים\u0006 ש\u0005לראות באו],\u0006 אם כן \u0003מה יעשו שני אחין שראו באחד שהרג את הנפש,\u0004 האם לא יוכלו לבוא לבית הדין?","ובענין המחלוקת שבמשנה \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו ביחס לפסק ההלכה, ש\u0003אמר רב יהודה אמר שמואל: הלכה כר' יוסי. ורב נחמן אומר: הלכה כרבי.\u0004"],["\u0003היו שנים\u0004 שני עדים \u0003רואין אותו\u0004 את מי שעבר עבירה שנהרגים עליה, \u0003מחלון זה\u0004 של הבית, \u0003ושנים רואין אותו\u0004 את המאורע \u0003מחלון זה\u0004 אחר, \u0003ואחד\u0004 היה \u0003מתרה בו\u0004 בנאשם \u0003באמצע\u0004 בין שתי כתות העדים, \u0003בזמן שמקצתן\u0004 של העדים משתי הכתות הללו \u0003רואין אלו את אלו\u0004 — \u0003הרי אלו עדות אחת, ואם לאו\u0004 — \u0003הרי אלו שתי עדיות\u0004 שונות. \u0003לפיכך,\u0004 כיון שאלה שתי כתות עדים שונות, \u0003אם נמצאת אחת מהן זוממת\u0004 והכת השניה לא הוזמה — \u0003הוא\u0004 הנאשם, \u0003והן\u0004 הזוממים, \u0003נהרגין;\u0004 הנאשם נהרג — משום עדותה של הכת שלא הוזמה, והם נהרגים — משום שהוכח שהיו עדים זוממים. \u0003ו\u0004הכת \u0003השניה,\u0004 שלא הוזמה, \u0003פטורה.\u0004","\u0003ר' יוסי אומר: לעולם אין נהרגין\u0004 בכל מקרה \u0003עד שיהו שני עדיו מתרין בו\u0004 בנאשם, שנאמר \u0003\"על פי שנים עדים\u0004 יומת המת\" (דברים יז, ו), לומר שפי שני העדים צריך להתרות ולהזהיר את הנאשם, ולא די בהתראה של אדם אחר, כדעת סתם משנה לעיל. \u0003דבר אחר\u0004 למדו מכאן: \u0003\"על פי שנים עדים\"\u0004 — \u0003שלא תהא סנהדרין שומעת\u0004 את עדות העדים \u0003מפי התורגמן\u0004 המתרגם לדיינים את דברים העדים, אלא הדיינים צריכים לשמוע את העדות מפי העדים עצמם.","\u0003אמר רב זוטרא בר טוביא אמר רב: מנין לעדות מיוחדת\u0004 שכל אחד מן העדים ראה את המאורע בפני עצמו \u0003שהיא פסולה\u0004 — \u0003שנאמר \"לא יומת על פי עד אחד\"\u0004 (שם). ונברר, \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \"עד \u0003אחד\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003עד אחד ממש,\u0004 שמעיד רק הוא לבדו — הלוא \u0003מרישא שמעינן לה\u0004 \u0005[מן ההתחלה\u0006 של הכתוב \u0005שומעים אנו זאת],\u0006 שנאמר \u0003\"על פי שנים עדים\"\u0004 וממילא משמע שאין סומכים על עד אחד! \u0003אלא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אחד\"\u0004 — כוונתו \u0003אחד אחד,\u0004 שאם כל אחד מהם היה לחוד אין ממיתים על פיהם.","ומעירים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003\"לא יומת על פי עד אחד\",\u0004 הרי זה בא \u0003להביא\u0004 (לרבות) \u0003שנים שרואים אותו, אחד מחלון זה ואחד מחלון זה, ואין רואין זה את זה, שאין מצטרפין\u0004 לעדות כלל. \u0003ולא עוד אלא, אפילו\u0004 ראו אותו מעשה עצמו \u0003בזה אחר זה,\u0004 אף ששניהם עמדו \u0003בחלון אחד,\u0004 וראו את המעשה מאותו מקום עצמו — \u0003אין מצטרפין.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי:\u0004 מה צורך להביא שני מקרים? \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005],\u0006 \u0003ומה\u0004 אם \u0003אחד\u0004 רואה \u0003מחלון זה ואחד מחלון זה, דהאי קא חזי\u0004 \u0005[שזה רואה]\u0006 \u0003כולו מעשה, והאי קא חזי\u0004 \u0005[וזה רואה]\u0006 \u0003כולו מעשה\u0004 — \u0003אמרת לא מצטרפי\u0004 \u0005[אומר אתה שאין מצטרפים\u0006 לעדות\u0005];\u0006 \u0003בזה אחר זה, דהאי חזי פלגא\u0004 \u0005[שזה רואה חצי]\u0006 \u0003מעשה והאי חזי פלגא\u0004 \u0005[וזה רואה חצי]\u0006 \u0003מעשה, מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שלא יצטרפו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא נצרכא\u0004 \u0005[נצרכה]\u0006 \u0003אלא לבועל את הערוה\u0004 כלומר, שהיה זה מעשה עבירה מתמשך, וכל אחד מהם ראה מעשה עבירה שיש בו כדי לחייב את הבועל, ובכל זאת אין מצטרפים כיון שראו בזה אחר זה ולא ביחד.","ובענין זה של צירוף עדות \u0003אמר רבא:\u0004 גם אם לא היו העדים רואים כלל זה את זה, \u0003אם היו רואין את המתרה\u0004 ששניהם היו רואים אדם שלישי, שהיה מתרה בנאשם, \u0003או המתרה רואה אותן\u0004 (את שני העדים הבודדים) — \u0003מצטרפין. ו\u0004עוד \u0003אמר רבא: מתרה שאמרו,\u0004 אין צורך שיהיה זה אדם אחר שיתרה בנאשם, אלא \u0003אפילו מפי עצמו,\u0004 כלומר אם ההרוג עצמו מתרה בהורג, \u0003ואפילו מפי השד\u0004 שנשמעה התראה ואין ידוע מי התרה — הרי זו התראה, ואין צורך באדם מסויים שיעשה זאת.","\u0003אמר רב נחמן: עדות מיוחדת\u0004 של שני עדים, שכל אחד לעצמו ראה את העדות — \u0003כשירה בדיני ממונות,\u0004 וראיה לדבר, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא יומת על פי עד אחד\"\u0004 (שם), ללמדנו: דווקא \u0003בדיני נפשות הוא\u0004 ש\u0003אין כשירה\u0004 עדות כזו, \u0003אבל בדיני ממונות\u0004 — \u0003כשירה.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב זוטרא:\u0004 אם סבור אתה שעדות מיוחדת נחשבת כמצטרפת לענין כלשהו, \u0003אלא מעתה בדיני נפשות תציל\u0004 אותו, שאם היתה עדות מיוחדת, והוזמו חלק מן העדים — תיבטל העדות כולה בגללם! \u0003אלמה תנן\u0004 \u0005[מדוע שנינו\u0006 במשנה\u0005]\u0006 שאם ראו שנים מחלון זה ושנים מחלון אחר, והוזמה כת אחת — \u0003הוא\u0004 הנידון \u0003והן\u0004 הזוממים \u0003נהרגין?\u0004 ומעירים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 הדבר לדברי רב נחמן.","שנינו במשנה ש\u0003ר' יוסי אמר\u0004 שאין הנידון נהרג אלא עד שיהיו העדים עצמם מתרים בו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: ומי אית ליה\u0004 \u0005[והאם יש לו]\u0006 \u0003לר' יוסי האי סברא\u0004 \u0005[סברה זו]\u0006 שחייבת תמיד להיות התראה, ומפי העדים? \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 \u0003ר' יוסי אומר: השונא\u0004 שהרג את הנפש, אף על פי שלא היתה לו התראה — אינו יכול לטעון שהיה שוגג, אלא הרי זה \u0003נהרג\u0004 בבית דין, \u0003מפני שהוא כמועד ומותרה.\u0004 משמע שר' יוסי סבור שלא תמיד צריכים הוכחה על ידי התראה!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ההוא\u0004 אותו דבר שהובא בשם ר' יוסי — שיטת \u0003ר' יוסי בר יהודה היא,\u0004 שאינו מצריך תמיד התראה. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' יוסי בר יהודה אומר: חבר\u0004 (תלמיד חכם) \u0003אין צריך התראה, לפי ש\u0004מעיקרה \u0003לא ניתנה התראה אלא\u0004 כדי \u0003להבחין\u0004 על ידה \u0003בין שוגג למזיד,\u0004 ותלמיד חכם ודאי יודע מה אסור, ושיש עבירה במה שהוא עושה. אבל ר' יוסי (הוא ר' יוסי בן חלפתא) סבור שצריך תמיד התראה כדי לחייב אדם על הריגה, ולא עוד אלא, שהתראה זו צריכה להיות על ידי העדים המעידים עליו.","שנינו במשנה, \u0003דבר אחר: \"על פי שנים עדים\"\u0004 — \u0003שלא תהא סנהדרין שומעת מפי התורגמן.\u0004 מסופר: \u0003הנהו לעוזי דאתו לקמיה\u0004 \u0005[אותם\u0006 אנשים \u0005לועזים\u0006 שדברו בלשון לועזית \u0005שבאו\u0006 לדין \u0005לפני]\u0006 \u0003רבא,\u0004 \u0003אוקי\u0004 \u0005[העמיד]\u0006 \u0003רבא תורגמן בינייהו\u0004 \u0005[ביניהם]\u0006 ושמע את העדות. ושואלים: \u0003והיכי עביד הכי\u0004 \u0005[ואיך עשה כך]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003שלא תהא סנהדרין שומעת מפי התורגמן!\u0004 ומשיבים: \u0003רבא מידע הוה ידע\u0004 \u0005[היה יודע]\u0006 \u0003מה דהוו אמרי\u0004 \u0005[שהיו אומרים]\u0006 שהבין את השפה, \u0003ואהדורי\u0004 \u0005[ולהשיב\u0006 להם בשפתם\u0005]\u0006 \u0003הוא\u0004 ש\u0003לא הוה ידע\u0004 \u0005[היה יודע],\u0006 והעמיד מתורגמן כדי שיוכל לחקור את העדים, אבל הוא עצמו הבין את דבריהם, כדין המשנה."],["ובענין פסול עדים, מסופר: שני אנשים בשם \u0003אילעא וטוביה,\u0004 שהיו עדים על שטר הלוואה, \u0003קריביה דערבא הוה\u0004 \u0005[קרוביו של הערב\u0006 להלוואה \u0005היו],\u0006 ונשאלה שאלה לגבי כשרותם כעדים בשטר זה. \u0003סבר\u0004 \u0005[סבור\u0006 היה\u0005]\u0006 \u0003רב פפא למימר\u0004 \u0005[לומר]:\u0006 \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003לוה ומלוה רחיקי נינהו\u0004 \u0005[רחוקים הם]\u0006 ולכן עדותם בשטר זה כשירה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרב פפא: אי לית ליה\u0004 \u0005[אם אין לו]\u0006 \u0003ללוה\u0004 לשלם את חובו, \u0003לאו בתר ערבא אזיל\u0004 \u0005[האם לא אחר הערב הולך]\u0006 ה\u0003מלוה\u0004 לגבות את חובו? אם כן, נמצא שהערב קשור בהלוואה הזו, ולכן יש לפסול את העדים הללו בשטר זה משום קירבת משפחה.","ועוד בענין עדות על אדם שחייב מיתה. \u0003מי שנגמר דינו\u0004 בבית דין למיתה, \u0003וברח,\u0004 וחזר \u0003ובא לפני אותו בית דין\u0004 שנתחייב בו — \u0003אין סותרין את דינו\u0004 לדון אותו מחדש, אלא עושים בו כפי שפסקו קודם לכן. משום כך, \u0003כל מקום שיעמדו שנים ויאמרו: \"מעידים אנו באיש פלוני שנגמר דינו\u0004 למיתה \u0003בבית דין של פלוני, ופלוני ופלוני עדיו\"\u0004 — \u0003הרי זה יהרג\u0004 על סמך עדותם זו.","ועוד כמה דינים כלליים בענין זה: \u0003סנהדרין,\u0004 שבכוחה לדון דיני נפשות, \u0003נוהגת\u0004 בין \u0003בארץ ו\u0004בין \u0003בחוצה לארץ.\u0004 ועוד אמרו: \u0003סנהדרין ההורגת\u0004 פעם \u0003אחד בשבוע\u0004 (בשבע שנים) \u0003נקראת חובלנית.\u0004 משום שחכמי הסנהדרין היו מדקדקים הרבה בעדויות, ונדיר היה שיימצא אדם נהרג על ידם. \u0003ר' אליעזר בן עזריה אומר:\u0004 סנהדרין ההורגת \u0003אחד לשבעים שנה\u0004 נקראת חובלנית. \u0003ר' טרפון ור' עקיבא אומרים: אילו היינו בסנהדרין\u0004 היינו דנים באופן כזה ש\u0003לא\u0004 היה \u0003נהרג אדם מעולם. רבן שמעון בן גמליאל אומר:\u0004 אם כך היו עושים \u0003אף הן\u0004 היו \u0003מרבין\u0004 בכך \u0003שופכי דמים\u0004 (רוצחים) \u0003בישראל,\u0004 שהרי אז הכל יודעים שאין עונש מוות קיים בפועל, ולא היו נרתעים מלרצוח.","נאמר במשנה שמי שנגמר דינו וברח, וחזר לפני אותו בית דין — אין סותרים את דינו. ונדייק מכאן: \u0003לפני אותו בית דין הוא\u0004 ש\u0003אין סותרין, הא\u0004 \u0005[הרי]\u0006 אם בא \u0003לפני בית דין אחר\u0004 — \u0003סותרין,\u0004 וחוזרים ודנים בו. אולם \u0003הא תני סיפא\u0004 \u0005[הרי שנה בסופה\u0006 של המשנה\u0005]:\u0006 \u0003כל מקום שיעמדו שנים ויאמרו: \"מעידין אנו את איש פלוני שנגמר דינו בבית דין פלוני, ופלוני ופלוני עדיו\"\u0004 — \u0003הרי זה נהרג,\u0004 משמע שגם בבית דין אחר אין סותרים, אלא מסתמכים על מה שהוחלט בבית דין אחר. ואם כן, יש סתירה בין הדיוק של הרישא והסיפא!","\u0003אמר אביי: לא קשיא\u0004 \u0005[אין זה קשה],\u0006 \u0003כאן\u0004 בתחילת המשנה, שלמדנו ממנה שסותרים את דינו בבית דין אחר, מדובר כשבא לפני בית דין ש\u0003בארץ ישראל\u0004 לאחר שנגמר דינו בחוצה לארץ, \u0003כאן\u0004 בסוף המשנה, שלמדנו ממנה שאין סותרים — כשבא לפני בית דין \u0003בחוצה לארץ\u0004 לאחר שנגמר דינו בארץ ישראל.","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' יהודה בן דוסתאי אומר משום\u0004 (בשם) \u0003ר' שמעון בן שטח: ברח\u0004 הנידון \u0003מארץ לחוצה לארץ\u0004 — \u0003אין סותרין\u0004 \u0003את דינו\u0004 אלא מבצעים מה שפסק בית דין שבארץ. ברח \u0003מחוצה לארץ לארץ\u0004 — \u0003סותרין את דינו, מפני זכותה של ארץ ישראל,\u0004 שמא ימצא לו בית הדין זכות.","שנינו במשנה ש\u0003סנהדרין נוהגת\u0004 בארץ ובחוץ לארץ. ומבררים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שגם בחוץ לארץ יש סנהדרין? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 נאמר בדיני רוצחים \u0003\"והיו אלה לכם לחקת משפט לדרתיכם\u0004 בכל מושבותיכם\" (במדבר לה, כט) \u0003למדנו לסנהדרין שנוהגת בארץ ובחוצה לארץ,\u0004 \u0003אם כן, מה תלמוד לומר \"בשעריך\"\u0004 (\"שופטים ושוטרים תתן לך בכל שעריך\". דברים טז, יח), שמשמע מכאן שרק בארץ ישראל (שרק בה ישנם \"שעריך\" — השייכים לעם ישראל) יש מצוה להקים בתי דין? יש לומר כך: \u0003בשעריך,\u0004 בארץ, \u0003אתה מושיב בתי דינים בכל פלך ופלך\u0004 (מחוז ומחוז) \u0003ובכל עיר ועיר, ו\u0004אילו \u0003בחוצה לארץ אתה מושיב\u0004 סנהדרין \u0003בכל פלך ופלך, ו\u0004אולם \u0003אי\u0004 (אין) \u0003אתה מושיב בכל עיר ועיר.\u0004 וגם הוא מדוייק מ\"בשעריך\" — שבכל שער עיר שבארץ ישראל ראוי לעשות סנהדרין, ולא בחוץ לארץ.","","שנינו במשנה: \u0003סנהדרין ההורגת\u0004 אחת לשבע שנים נקראת חובלנית. ור' אלעזר בן עזריה אומר: אחת לשבעים שנה. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 האם כוונתו של ר' אלעזר בן עזריה לומר שסנהדרין ההורגת \u0003אחת לשבעים שנה\u0004 (ולא אחת לשבע שנים) \u0003נקראת חבלנית, או דלמא\u0004 \u0005[שמא]\u0006 כוונתו לומר כי \u0003אורח ארעא\u0004 \u0005[דרך העולם]\u0006 \u0003היא\u0004 שסנהדרין הורגת אחת לשבעים שנה, ואז אינה נקראת חבלנית? שאלה זו לא נפתרה ונשארה ב\u0003תיקו\u0004 \u0005[תעמוד]\u0006 הבעיה במקומה. שנינו שם ש\u0003ר' טרפון ור' עקיבא אומרים: אילו היינו\u0004 בסנהדרין לא נהרג בה אדם מעולם. ושואלים: \u0003היכי הוו עבדי\u0004 \u0005[כיצד היו עושים]\u0006 שלא ייהרג אדם, כאשר באים עדים ומעידים עליו שהרג אדם במזיד? \u0003ר' יוחנן ור' אלעזר דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 היו שואלים את העדים: האם \u0003ראיתם\u0004 אם \u0003טריפה\u0004 ש\u0003הרג\u0004 אותו איש או \u0003שלם הרג?\u0004 שמא היה האיש הזה חולה מחלה אנושה קודם לכן, והיה כבר נחשב כמת. ודבר כזה, שאי אפשר לדעת אותו בבירור, ממילא פוסל כל עדות של עדי הריגה.","","\u0003אמר רב אשי:\u0004 גם \u0003אם תמצא לומר\u0004 שבדקוהו לאחר מיתה, ו\u0003שלם הוה\u0004 \u0005[היה],\u0006 עדיין ניתן היה לערער ולומר: \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003במקום\u0004 בו תקע את ה\u0003סייף\u0004 בגוף ההרוג \u0003נקב הוה\u0004 \u0005[היה]\u0006 שכבר נתקע בו סייף, ואתם ראיתם אדם שעשה זאת בפעם השניה, כשהיה כבר בעצם הרוג.","ושואלים: \u0003בבועל את הערוה היכי הוו עבדי\u0004 \u0005[איך היו עושים]\u0006 כדי לפטור אותו? \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם],\u0006 היו שואלים אותם: האם \u0003ראיתם\u0004 ממש את הביאה, \u0003כמכחול\u0004 הנכנס \u0003בשפופרת?\u0004 ומכיון שדבר זה קשה לראות אותו, אפשר לטעון שלא היתה עדות גמורה על הביאה. ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 שאינם סבורים כר' טרפון ור' עקיבא, \u0003היכי דיינו\u0004 \u0005[איך היו דנים]\u0006 במקרה כגון זה? הלוא השאלה בכל זאת קיימת! ומשיבים: הם סברו \u0003כ\u0004דעת \u0003שמואל,\u0004 ש\u0003אמר שמואל: במנאפים\u0004 יש לדון \u0003משיראו כמנאפים,\u0004 כעושים מעשה של ביאה, גם בלא ראיה של \"כמכחול בשפופרת\".","","\u0003אלו הן הגולין\u0004 — \u0003ההורג נפש בשגגה,\u0004 הוא זה שגולה. אולם בכך יש פרטים: \u0003היה מעגל במעגילה\u0004 שהיו טחים את הגג בטיח, ומחליקים אותו במכשיר עגול שהיו מגלגלים על הגג, \u0003ונפלה עליו\u0004 המעגילה על אדם \u0003והרגתו,\u0004 או \u0003היה משלשל בחבית\u0004 להורידה מן הגג \u0003ונפלה עליו\u0004 על אדם \u0003והרגתו,\u0004 או \u0003היה יורד בסולם ונפל עליו\u0004 על האיש \u0003והרגתו\u0004 — בכל אלה \u0003הרי זה גולה. אבל אם היה מושך במעגילה\u0004 כלפי עצמו, \u0003ונפלה\u0004 המעגילה מידיו \u0003עליו\u0004 על אדם אחר \u0003והרגתו,\u0004 או \u0003היה דולה בחבית\u0004 ומעלה אותה, \u0003ונפסק החבל ונפלה עליו\u0004 על אדם \u0003והרגתו,\u0004"],["\u0003היה עולה בסולם ונפל עליו\u0004 על אדם אחר \u0003והרגו\u0004 — \u0003הרי זה אינו גולה. זה הכלל: כל ש\u0004אירע לו הדבר \u0003בדרך ירידתו\u0004 של ההורג — \u0003גולה, ו\u0004כל הריגה שנעשתה \u0003שלא בדרך ירידתו\u0004 — \u0003אינו גולה.\u0004","על האמור במשנה שאין גולה אלא כשאירע הדבר בדרך ירידה, שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 ש\u0003אמר שמואל:\u0004 שכן \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בפרשת הגולים לעיר מקלט \u0003\"ויפל עליו וימת\"\u0004 (במדבר לה, כג) ללמדנו שאינו חייב גלות אלא \u0003עד שיפול דרך נפילה.\u0004","ומביאים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 מה שנאמר שם \u0003\"בשגגה\"\u0004 (במדבר לה, יא) — הרי זה בא ללמד \u0003פרט למזיד\u0004 שאינו גולה. ומה שנאמר בפרשה אחרת של חייבי גלות \u0003\"בבלי דעת\"\u0004 (דברים יט, ד) — הרי זה \u0003פרט למתכוין.\u0004","ותוהים על הברייתא: מה צריך ללימוד מיוחד לגבי \u0003מזיד?\u0004 והלוא \u0003פשיטא\u0004 \u0005[פשוט\u0006 הוא\u0005]\u0006 שאינו גולה, שכן \u0003בר קטלא\u0004 \u0005[בן מוות]\u0006 \u0003הוא! אלא אמר רבא: אימא\u0004 \u0005[אמור]\u0006 שהכוונה ב\"מזיד\" היא \u0003פרט לאומר מותר\u0004 כלומר, מי שהיה סבור שמותר להרוג את האיש. ובמקרה כזה, אף שאינו חייב מיתה, אינו גולה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אי\u0004 \u0005[אם]\u0006 מדובר פה באדם ה\u0003אומר מותר,\u0004 הלוא אדם כזה \u0003אנוס הוא,\u0004 ואיך אפשר לכנותו מזיד? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003שאני אומר\u0004 לא כן, אלא \u0003האומר מותר,\u0004 כיון שנתכוון להרוג — \u0003קרוב למזיד הוא.\u0004","ועוד שנינו שם: \u0003\"בבלי דעת\"\u0004 — \u0003פרט למתכוין.\u0004 ותוהים: \u0003מתכוין? פשיטא\u0004 \u0005[פשוט],\u0006 הלוא \u0003בר קטלא\u0004 \u0005[בן מוות]\u0006 \u0003הוא! אמר רבה:\u0004 הכוונה היא \u0003פרט למתכוין להרוג את הבהמה ו\u0004אירע לו ש\u0003הרג את האדם,\u0004 וכן אם התכוון \u0003ל\u0004הרוג את ה\u0003גוי והרג את ישראל,\u0004 וכן אם התכוון \u0003ל\u0004הרוג \u0003נפל\u0004 (ולד שאינו בר קיימא) שאין חייבים על הריגתו, \u0003והרג\u0004 ולד \u0003בן קיימא.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בדין רוצח בשגגה, על הפסוק \"ואם בפתע בלא איבה הדפו או השליך עליו כל כלי בלא צדיה\" (במדבר לה, כב): \u0003\"אם בפתע\"\u0004 — הרי זה בא למעט: \u0003פרט לקרן זוית,\u0004 שאם בא הנרצח כנגדו מקרן זוית, ופגע בו בשגגה — אינו גולה. \u0003\"בלא איבה\"\u0004 (במדבר לה, כב) — בא למעט: \u0003פרט לשונא,\u0004 שאף שהדברים נראים לגמרי כשגגה, אנו מניחים שאין הדברים כן. \u0003\"הדפו\"\u0004 (במדבר לה, כב) — כוונתו \u0003שדחפו בגופו\u0004 ונהרג, שגם על כך הוא חייב לגלות. \u0003\"או השליך עליו\"\u0004 — \u0003להביא\u0004 (לרבות) \u0003ירידה שהיא צורך עליה,\u0004 כגון שהיה מתכופף על מנת להרים דבר־מה, ובתוך כדי תנועה זו הרגו, שגם הוא גולה. \u0003\"בלא צדיה\"\u0004 כוונתו — \u0003פרט למתכוין\u0004 לזרוק אבן \u0003לצד זה והלכה לה לצד אחר.\u0004","וכן נאמר ברוצח בשגגה \u0003\"ואשר לא צדה\"\u0004 (שמות כא, יג), ומכאן למדים: \u0003פרט למתכוין לזרוק\u0004 אבן \u0003שתים\u0004 (שתי אמות), \u0003ו\u0004אירע ש\u0003זרק ארבע\u0004 אמות, ונהרג בה אדם. ועוד ממה שנאמר בפרשה אחרת בדין זה \u0003\"ואשר יבא את רעהו ביער\"\u0004 (דברים יט, ה) יש ללמוד: \u0003מה יער\u0004 שהוא מקום הפקר, שיש \u0003רשות לניזק ולמזיק ליכנס לשם, אף כל\u0004 מקום ש\u0003רשות לניזק ולמזיק ליכנס לשם\u0004 יש בו דין גלות, ואין בכלל זה מי שנכנס לחצר חבירו שלא ברשותו, שאם נהרג שם בשגגה — אין בעל הבית גולה.","ומביאים דיון הקשור במה שנזכר בברייתא. \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003ר' אבהו מר' יוחנן: היה עולה בסולם ונשמט השליבה\u0004 של הסולם \u0003מתחתיו, ונפלה והרגה\u0004 את חבירו, \u0003מהו,\u0004 מה דינו לענין גלות? \u0003כי האי גוונא\u0004 \u0005[כגון זה]\u0006 הריגה בדרך \u0003עליה היא\u0004 ופטור מגלות, \u0003או\u0004 הריגה דרך \u0003ירידה היא,\u0004 וחייב? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כבר\u0004 \u0003נגעת\u0004 בענין זה בברייתא, \u0003ב\u0004דין \u0003ירידה שהיא צורך עליה\u0004 שאף זה בכלל חייבי גלות.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 ר' אבהו ממה ששנינו במשנה, \u0003זה הכלל: כל שבדרך ירידתו\u0004 — \u0003גולה, שלא בדרך ירידתו\u0004 — \u0003אינו גולה,\u0004 ומה שנאמר בלשון כוללת \"כל \u0003שלא בדרך ירידתו\" לאיתויי מאי\u0004 \u0005[להביא\u0006 לרבות \u0005מה]\u0006 הוא בא שלא נתפרש קודם? \u0003לאו לאיתויי כהאי גוונא\u0004 \u0005[האם לא להביא\u0006 מקרה \u0005כגון זה],\u0006 שכיון שלא היה הדבר בדרך ירידתו אלא בעלייתו, למרות שההריגה נגרמה על ידי השליבה שהפיל למטה — אינו גולה? ענה לו ר' יוחנן: \u0003וליטעמיך\u0004 \u0005[ולשיטתך]\u0006 שלשון זו לשון ריבוי היא, מה שנאמר קודם במשנה \u0003\"כל שבדרך ירידתו\u0004 גולה\", \u0003לאיתויי מאי\u0004 \u0005[להביא מה]?\u0006 איזה מקרה מקביל יש לכך?","אלא גם אתה מודה שדבר זה בא \u0003לאיתויי\u0004 \u0005[להביא,\u0006 לרבות\u0005]\u0006 \u0003קצב\u0004 החותך בשר ועצמות בסכין קצבים, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 הובא הכלל \u0003לאיתויי\u0004 \u0005[להביא]\u0006 מקרה של \u0003קצב. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003קצב שהיה מקצב\u0004 וחותך אברים בקופיץ שבידו, \u0003תנא חדא\u0004 \u0005[שנה\u0006 חכם \u0005אחד]:\u0006 אם הרג אדם כאשר היה האיש \u0003לפניו\u0004 — \u0003חייב,\u0004 אם פגע בו כשהיה האיש \u0003לאחריו\u0004 — \u0003פטור. ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003לאחריו\u0004 — \u0003חייב, לפניו\u0004 — \u0003פטור. ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003בין לפניו בין לאחריו\u0004 — \u0003חייב, ותניא אידך\u0004 \u0005[ושנויה\u0006 עוד ברייתא \u0005אחרת]:\u0006 \u0003בין לפניו בין לאחריו\u0004 — \u0003פטור,\u0004 ולכאורה יש בברייתות אלה ארבע דעות שונות באותו נושא עצמו. \u0003ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה],\u0006 שהרי כאשר קצב רוצה להכות בכח על הבשר שלפניו, הוא מרים את הקופיץ ומוריד אותו לאחריו, לצורך התנופה, ולאחר מכן הוא מרים את הקופיץ מאחרי גבו ומוריד אותו לפניו על גוש הבשר שרצונו לחתוך. ונמצא שבמהלך זה הוא מוריד ומעלה את הקופיץ גם לפניו וגם לאחריו.","וכך יש להסביר את הברייתות, שכל אחת מהן מדברת במקרה אחר: \u0003כאן\u0004 שחייב לפניו ופטור לאחריו — \u0003בירידה שלפניו\u0004 כשהוריד את הקופיץ לפניו, \u0003ועליה שלאחריו\u0004 בזמן העלאת הגרזן מאחרי גבו. \u0003כאן\u0004 שאמרו שלאחריו חייב ולפניו פטור — הוא \u0003בעליה שלפניו\u0004 שמעלה את הקופיץ מלפניו, \u0003וירידה שלאחריו\u0004 כדי שיוכל להניפו בכוח.","\u0003כאן\u0004 שאמרנו שבשניהם חייב — \u0003בירידה שלפניו ו\u0004ירידה \u0003של אחריו, כאן\u0004 שבשניהם פטור — \u0003בעליה שלפניו ו\u0004עליה \u0003של אחריו.\u0004 והוא מה שנאמר במשנה בשני הכללים שהובאו בה: כל שהרג בירידה חייב, וכל שדרך עליה פטור, בין מלפניו ובין לאחריו. עד כאן דברי ר' יוחנן. ושבים לדון בשאלתו של רבי אבהו, בענין מי שהיה עולה בסולם.","ומציעים: \u0003לימא כתנאי\u0004 \u0005[האם לומר\u0006 שהיא \u0005כ\u0006מחלוקת \u0005תנאים],\u0006 ששנינו: \u0003היה עולה בסולם ונשמטה שליבה מתחתיו, תני חדא\u0004 \u0005[שנה\u0006 בברייתא \u0005אחת]\u0006 \u0003חייב, ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]\u0006 \u0003פטור. מאי לאו בהא קא מיפלגי\u0004 [\u0005האם לא\u0006 בנושא \u0005זה הם חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה סבור]\u0006 \u0003ירידה היא,\u0004 ולכן חייב, \u0003ומר סבר\u0004 \u0005[וחכם זה סבור]\u0006 \u0003עליה היא,\u0004 ופטור?","ודוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003עליה היא. ולא קשיא\u0004 \u0005[קשה]\u0006 ההבדל בין הברייתות, \u0003כאן\u0004 מדובר \u0003לניזקין,\u0004 שודאי חייב לשלם דמי נזיקין, ככל מזיק אחר, שלא חלקו בו באיזה אופן הזיק, אם בשוגג או במזיד. \u0003כאן\u0004 — \u0003לגלות,\u0004 הריהו פטור, משום גזירת הכתוב.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 \u0003הא והא\u0004 \u0005[זה וזה\u0006 מדברים\u0005]\u0006 \u0003ל\u0004ענין \u0003גלות, ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — \u0003דאתליע\u0004 \u0005[שהתליע]\u0006 העץ, \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003לא אתליע\u0004 \u0005[התליע],\u0006 והיה זה כאונס, שלא יכול לדעת שתישבר השליבה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003הא והא\u0004 \u0005[זה וזה]\u0006 מדובר ש\u0003לא אתליע\u0004 \u0005[התליע]\u0006 העץ, \u0003ולא קשיא\u0004 \u0005[ואינו קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שפטור — \u0003דמיהדק\u0004 \u0005[שהיתה\u0006 השליבה \u0005מהודקת]\u0006 ולא היה לו להעלות על הדעת שתיפול, \u0003והא\u0004 \u0005[וזה]\u0006 שחייב — ש\u0003לא מיהדק\u0004 \u0005[היתה מהודקת].\u0006","\u0003נשמט הברזל\u0004 (הלהב) של גרזן או קרדום \u0003מקתו,\u0004 ועף \u0003והרג\u0004 את הנפש, \u0003רבי אומר: אינו גולה, וחכמים אומרים: גולה.\u0004 ניתז חלק \u0003מן העץ המתבקע\u0004 על ידי הגרזן, והרג את הנפש, \u0003רבי אומר: גולה, וחכמים אומרים: אינו גולה.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר להם רבי לחכמים: וכי נאמר\u0004 בכתוב \u0003\"ונשל הברזל מעצו\"\u0004 כלומר, מן הקת שלו? \u0003והלא לא נאמר אלא\u0004 \"ונשל הברזל \u0003מן העץ\"?\u0004 והכוונה היא שניתז חלק מן העץ שהוא חוטב! \u0003ועוד\u0004 ראיה לכך, \u0003נאמר \"עץ\" למטה\u0004 (\"ונשל הברזל מן העץ\") \u0003ונאמר \"עץ\" למעלה\u0004 קודם לכן (\"ונדחה ידו בגרזן לכרות העץ\"), \u0003מה \"עץ\" האמור למעלה\u0004 כוונתו \u0003מן העץ המתבקע, אף \"עץ\" האמור למטה\u0004 כוונתו מן \u0003העץ המתבקע,\u0004 ולא עץ הגרזן.","\u0003אמר רב חייא בר אשי אמר רב: ושניהם,\u0004 גם רבי וגם חכמים, \u0003מקרא אחד דרשו,\u0004 שנאמר \u0003\"ונשל הברזל מן העץ\"\u0004 (דברים יט, ה), \u0003רבי סבר: יש אם למסורת,\u0004 שבסיס הלימוד הוא על פי מסורת הכתיב, ולאו דווקא על פי הניקוד המקובל, ולכן אפשר לקרוא כאילו \u0003\"ונישל\" כתיב,\u0004 שהברזל מתיז חתיכת עץ מן העץ, \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003יש אם למקרא,\u0004 שבסיס הלימוד הוא בדרך הקריאה המקובלת, והרי \u0003\"ונשל\" קרינן\u0004 \u0005[קוראים אנו],\u0006 ומשמע שהברזל עצמו נשל מן העץ והרג.","ושואלים: \u0003ו\u0004כי \u0003רבי יש אם למסורת סבירא ליה\u0004 \u0005[סבור הוא]?\u0006"],["\u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יצחק בר' יוסף אמר ר' יוחנן: רבי, ור' יהודה בן רועץ, ובית שמאי, ור' שמעון, ור' עקיבא, כולהו סבירי להו\u0004 \u0005[כולם סבורים]\u0006 \u0003יש אם למקרא\u0004 שהבסיס למדרש הוא דרך הקריאה המקובלת של הכתובים, ולא מסורת הכתב, ואיך אפשר לפרש את דברי רבי על פי שיטה אחרת? ומשיבים: \u0003היינו דקאמר להו\u0004 \u0005[זהו\u0006 הטעם \u0005שהוא,\u0006 רבי, \u0005אמר להם\u0006 לחכמים\u0005]\u0006 \u0003\"ועוד\".\u0004 כלומר, אם סבורים אתם שיש אם למסורת — הרי ראיה אחת, ואם לא — יש לי ראיה אחרת לדבר.","\u0003אמר רב פפא: מאן דשדא פיסא לדיקלא\u0004 \u0005[מי שזרק רגב\u0006 אדמה \u0005לדקל]\u0006 \u0003ואתר תמרי, ואזול תמרי וקטול\u0004 \u0005[והשיר תמרים\u0006 מהעץ, \u0005והלכו התמרים\u0006 ונפלו על אדם \u0005והרגו\u0006 אותו\u0005],\u0006 \u0003באנו\u0004 בשאלה זו \u0003למחלוקת\u0004 של \u0003רבי ורבנן\u0004 \u0005[וחכמים]\u0006 כשמבקע עצים וניתזת חתיכה מן העץ והורגת, שלדעת רבי גולה ולדעת חכמים אינו גולה. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכן הוא, שהרי זו לכאורה אותה מחלוקת, ומה צורך יש להשמיענו? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 נפילת התמרים אינה נחשבת כדבר הנעשה מכוחו, אלא \u0003ככח כחו דמי\u0004 \u0005[נחשב],\u0006 וגם לרבי אינו חייב גלות, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאין הדבר נחשב כוח כוחו אלא מכוחו ממש.","ושואלים: אם כן, \u0003אלא כח כחו ל\u0004דעת \u0003רבי היכי משכחת לה\u0004 \u0005[כיצד אתה מוצא אותה],\u0006 שבו גם הוא פוטר מגלות, היכן יש דוגמא לכך? ומשיבים: \u0003כגון דשדא פיסא ומחיה לגרמא\u0004 \u0005[שזרק רגב והיכה בעצם,\u0006 בענף של הדקל\u0005],\u0006 \u0003ואזיל גרמא ומחיה לכבאסא\u0004 \u0005[והלך הענף והיכה את אשכול התמרים]\u0006 \u0003ואתר תמרי\u0004 \u0005[והשיר תמרים],\u0006 \u0003ואזול תמרי וקטול\u0004 \u0005[והלכו התמרים והרגו],\u0006 שזה נקרא כוח כוחו.","\u0003הזורק אבן לרשות הרבים והרג\u0004 את הנפש — \u0003הרי זה גולה. ר' אליעזר בן יעקב אומר: אם מכשיצאתה\u0004 (לאחר שיצאה) \u0003האבן מידו הוציא הלה\u0004 ההרוג \u0003את ראשו וקבלה\u0004 (נפגע בה) — \u0003הרי זה פטור,\u0004 כי בשעה שזרק את האבן לרשות הרבים לא היה שם אדם.","\u0003זרק את האבן לחצרו\u0004 שלו \u0003והרג, אם\u0004 הוא באופן ש\u0003יש רשות לניזק ליכנס לשם\u0004 — \u0003גולה, ואם לאו\u0004 — \u0003אינו גולה. שנאמר\u0004 בפרשת ערי מקלט: \u0003\"ואשר יבא את רעהו ביער\"\u0004 (דברים יט, ה), ויש ללמוד: \u0003מה היער רשות\u0004 שווה \u0003לניזק ולמזיק ליכנס לשם, אף כל\u0004 מקום ש\u0003רשות לניזק ולמזיק להכנס לשם\u0004 חייב ההורג גלות. \u0003יצא\u0004 מכלל זה \u0003חצר בעל הבית, שאין רשות\u0004 שווה \u0003לניזק ולמזיק ליכנס לשם,\u0004 שהרי הניזק אינו רשאי להיכנס לחצר חבירו, ובעל הבית פטור מגלות.","\u0003אבא שאול אומר:\u0004 אפשר ללמוד מפסוק זה לימוד נוסף, \u0003מה חטבת עצים\u0004 שהוזכרה בפסוק הריהי דבר \u0003רשות,\u0004 שהוא רשאי לעשותו או לא לעשותו, \u0003אף כל\u0004 גולה בשגגה הוא דווקא כאשר ההריגה בשוגג היתה מתוך מעשה של \u0003רשות, יצא\u0004 מכלל זה \u0003האב המכה את בנו, ו\u0004כן \u0003הרב הרודה\u0004 (המעניש) \u0003את תלמידו,\u0004 א \u0003ו שליח בית דין\u0004 המכה, שכיון שכל אלה עושים מצוה, אם גרמו בשגגה להרוג את הנפש — אינם חייבים גלות.","שנינו במשנה שהזורק אבן לרשות הרבים והרג — הרי זה גולה. ותוהים: הזורק \u0003לרשות הרבים,\u0004 הלא \u0003מזיד הוא,\u0004 שהרי יודע הוא שמצויים שם אנשים, והרי זה כמזיד! \u0003אמר רב שמואל בר יצחק:\u0004 כאן לא מדובר בזורק אבן סתם, אלא \u0003בסותר\u0004 (הורס) \u0003את כותלו\u0004 ופגעה אחת האבנים מן הכותל באדם. ומשיבים: גם זה כמזיד הוא, \u0003איבעי ליה לעיוני\u0004 \u0005[צריך היה להסתכל]\u0006 אם ישנו אדם בצד האחר! ומשיבים: מדובר \u0003בסותר את כותלו בלילה,\u0004 שאין אנשים מצויים. ודוחים: \u0003בלילה נמי איבעי ליה לעיוני\u0004 \u0005[גם כן היה צריך להסתכל]\u0006 תחילה לפני שזרק את האבן, שכיון שרשות הרבים היא, שמא הולכים שם בני אדם!","ומשיבים: מדובר \u0003בסותר את כותלו ל\u0004תוך \u0003אשפה,\u0004 שבמקרה זה לא היה צריך להביא בחשבון שיש שם אנשים. ותוהים: \u0003האי\u0004 \u0005[אותה]\u0006 \u0003אשפה היכי דמי\u0004 \u0005[איך היתה בדיוק]?\u0006 \u0003אי שכיחי\u0004 \u0005[אם מצויים]\u0006 \u0003בה רבים,\u0004 כגון שהולכים להיפנות בה לצורכיהם — אם כן \u0003פושע הוא, אי לא שכיחי\u0004 \u0005[אם לא מצויים]\u0006 \u0003בה רבים,\u0004 הרי אף שהיא רשות הרבים מבחינת היותה שייכת לרבים, מכל מקום \u0003אנוס הוא,\u0004 שלא היה לו להעלות על דעתו שיש שם אדם!","\u0003אמר רב פפא: לא\u0004 \u0003צריכא\u0004 \u0005[נצרכה]\u0006 \u0003אלא ל\u0004מקרה של \u0003אשפה העשויה ליפנות\u0004 שאנשים ניפנים \u0003בה בלילה, ואין עשויה ליפנות בה ביום, ואיכא דמקרי ויתיב\u0004 \u0005[ו\u0006אולם \u0005יש ש\u0006אדם \u0005ניקרה\u0006 מזדמן \u0005ויושב]\u0006 ועושה שם את צרכיו בכל זאת. \u0003פושע לא הוי\u0004 \u0005[איננו]\u0006 הזורק את האבן — \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003אינה עשויה ליפנות בה ביום,\u0004 ומצד שני, \u0003אונס נמי לא הוי\u0004 \u0005[גם כן אין זה],\u0006 \u0003דהא איכא דמקרי ויתיב\u0004 \u0005[שהרי יש ש\u0006אדם \u0005מזדמן ויושב\u0006 שם\u0005],\u0006 והיה לו להביא בחשבון שיש אפשרות כגון זו, ולכן דינו כשוגג שגולה.","שנינו במשנה ש\u0003ר' אליעזר בן יעקב אומר\u0004 שאם הנפגע הוציא את ראשו לאחר שנזרקה האבן לרשות הרבים — הזורק פטור. ומביאים עוד בענין זה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר \"ונשל הברזל מן העץ \u0003ומצא\u0004 את רעהו ומת\" (דברים יט, ה) — \u0003פרט ל\u0004מי ש\u0003ממציא את עצמו\u0004 ונהרג. \u0003מכאן אמר ר' אליעזר בן יעקב: אם משיצתה האבן מידו הוציא הלה\u0004 הנפגע \u0003את ראשו וקבלה,\u0004 ונהרג \u0003—\u0004 \u0003פטור.\u0004","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 שהביטוי \u0003\"ומצא\" מעיקרא משמע\u0004 \u0005[מתחילה משמעו]?\u0006 כלומר, ש\"מצא\" הוא דבר שהיה מצוי עוד קודם המעשה? \u0003ורמינהי\u0004 \u0005[משליכים,\u0006 מראים סתירה\u0005]:\u0006 נאמר במי שמכר משדה אחוזתו וזכותו לפדותה: \"והשיגה ידו \u0003ומצא\u0004 כדי גאולתו\" (ויקרא כה, כו) — \u0003פרט ל\u0004מוכר לצורך זה מה שהיה \u0003מצוי\u0004 כבר בידו קודם לכן, בזמן שמכר שדה זה. לומר \u0003שלא ימכור\u0004 קרקע שיש לו \u0003ב\u0004מקום \u0003רחוק ויגאול בקרוב,\u0004 או ימכור \u0003ב\u0004קרקע \u0003רעה ויגאול ביפה,\u0004 שהוא אינו רשאי להשתמש בזכות שלו לגאול את השדה. ומפרשה זו משמע ש\"מצא\" הוא דבר שנמצא לאחר זמן, ולא שהיה מצוי קודם לכן!","\u0003אמר רבא:\u0004 אין זו קושיה, \u0003הכא מענייניה דקרא והתם מענייניה דקרא\u0004 \u0005[כאן מעניינו של הכתוב ושם מעניינו של הכתוב],\u0006 שכל אחד מהם מובן לפי עניינו והקשרו. ומפרטים: \u0003התם מענייניה דקרא\u0004 \u0005[שם מעניינו של הכתוב],\u0006 שנאמר \u0003\"ומצא\" דומיא\u0004 \u0005[בדומה]\u0006 למה שנאמר \u0003\"השיגה ידו\", מה השיגה ידו\u0004 כוונתו \u0003מהשתא\u0004 \u0005[מעכשיו],\u0006 שהרי אם היתה משגת ידו קודם לא היה מוכר כלל, \u0003אף \"מצא\" נמי מהשתא\u0004 \u0005[גם כן\u0006 פירושו \u0005מעכשיו]\u0006 ולא שהיה מצוי קודם לכן. ואילו \u0003הכא מענייניה דקרא\u0004 \u0005[כאן,\u0006 בענין גלות, \u0005מעניינו של הכתוב],\u0006 \u0003\"ומצא\" דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003יער, מה יער\u0004 הריהו \u0003מידי דאיתיה מעיקרא\u0004 \u0005[דבר שישנו מתחילה],\u0006 \u0003אף \"ומצא\" נמי\u0004 \u0005[גם כן]\u0006 \u0003מידי דאיתיה מעיקרא\u0004 \u0005[דבר שישנו מתחילה].\u0006","שנינו במשנה בענין \u0003הזורק את האבן,\u0004 שלדעת אבא שאול יש ללמוד מן הפסוק \"ואשר יבוא את רעהו ביער לחטוב עצים\", שכשם שחטיבת העצים היא רשות, אף כל רוצח בשגגה החייב גלות הוא זה העושה מעשה של רשות, ולא של מצוה. \u0003אמר ליה ההוא מרבנן\u0004 \u0005[לו אחד החכמים]\u0006 \u0003לרבא: ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]\u0006 ש\u0003מחטבת עצים\u0004 של \u0003רשות\u0004 אנו למדים? \u0003דלמא\u0004 \u0005[שמא]\u0006 מדובר \u0003מחטבת עצים של סוכה\u0004 שחוטב עצים לצורך סוכתו, \u0003ומחטבת עצים של מערכה\u0004 כלומר, לצורך עריכתם על גבי המזבח, שחטיבת עצים של מצוה היא, \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003אמר רחמנא ליגלי\u0004 \u0005[הכתוב שיגלה]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: כיון\u0004 שבמקרים אלו, \u0003אם\u0004 הבא לחטוב עצים \u0003מצא\u0004 עץ \u0003חטוב\u0004 כבר \u0003אינו חוטב,\u0004 ואם כן \u0003לאו\u0004 \u0005[אין\u0006 זו\u0005]\u0006 \u0003מצוה, השתא נמי\u0004 \u0005[עכשיו גם כן],\u0006 אף על פי שהוא עושה זאת לצורך מצוה — \u0003לאו\u0004 \u0005[אין\u0006 זו\u0005]\u0006 \u0003מצוה.\u0004 שאין חטיבת העצים מעשה מצוה לעצמו, אלא רק אמצעי עבור המצוה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבינא לרבא\u0004 ממה ששנינו במשנתנו: \u0003יצא האב המכה את בנו, והרב הרודה את תלמידו, ושליח בית דין.\u0004 ולפי אותה סברה שהעלית, \u0003לימא\u0004 \u0005[נאמר]\u0006 בענין האב המכה את בנו: \u0003כיון\u0004 ש\u0003אילו\u0004 היה הבן \u0003גמיר\u0004 \u0005[לומד]\u0006 \u0003לאו\u0004 \u0005[לא\u0006 היתה\u0005]\u0006 \u0003מצוה\u0004 להכותו, \u0003השתא נמי\u0004 \u0005[עכשיו גם כן],\u0006 כשמכה אותו לצורך, \u0003לאו\u0004 \u0005[אין\u0006 זו\u0005]\u0006 \u0003מצוה,\u0004 ולכן הוא צריך לגלות! ענה לו רבא: \u0003התם אף על גב דגמיר\u0004 \u0005[שם אף על פי ש\u0006הבן \u0005לומד]\u0006 \u0003מצוה\u0004 היא להכותו מפעם לפעם, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"יסר בנך ויניחך ויתן מעדנים לנפשך\"\u0004 (משלי כט, יז).","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר רבא: לאו מילתא היא דאמרי\u0004 \u0005[לא דבר\u0006 של ממש \u0005הוא שאמרתי],\u0006 האופן בו הוכחתי שהפסוק בענין הורג בשגגה אינו עוסק בחטיבת עצים של מצוה. אלא יש להוכיח זאת מן הלשון \u0003\"ואשר יבא את רעהו ביער\",\u0004 שמן הלשון \"אשר\" יש להבין כי \u0003מה יער\u0004 שמדובר עליו בפסוק זה הוא באופן \u0003דאי בעי עייל ואי בעי לא עייל\u0004 \u0005[שאם רוצה\u0006 אדם \u0005נכנס ואם רוצה אינו נכנס],\u0006 \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 שמדובר בפסוק על מי שחוטב עצים ל\u0003מצוה, מי סגיא דלא עייל\u0004 \u0005[האם יש אפשרות\u0006 האם רשאי \u0005שלא להיכנס]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר אהבה לרבא:\u0004 והאם \u0003כל היכא דכתיב\u0004 \u0005[מקום\u0006 בתורה \u0005שנאמר]\u0006 \u0003\"אשר\",\u0004 מדבר רק במקרה \u0003דאי בעי\u0004 \u0005[שאם רוצה]\u0006 \u0003הוא,\u0004 ולא מחמת מצוה או כורח? \u0003אלא מעתה\u0004 מה שנאמר \u0003\"ואיש אשר יטמא ולא יתחטא\u0004 ונכרתה הנפש ההיא... כי את מקדש ה' טמא\" (במדבר יט, כ), מדבר לפי זה דווקא במקרה ש\u0003אי בעי מיטמא אי בעי לא מיטמא\u0004 \u0005[\u0006ש\u0005אם\u0006 הוא \u0005רוצה\u0006 הוא \u0005נטמא אם\u0006 הוא \u0005רוצה אינו נטמא],\u0006 שנטמא בדבר הרשות. ואם כן, אם נטמא מפני שטיפל ב\u0003מת מצוה, דלא סגי דלא מיטמא\u0004 \u0005[שאי אפשר שלא ייטמא לו],\u0006 שהרי כל המוצאו חייב לטפל בקבורתו, \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 נאמר ש\u0003פטור\u0004 כשהוא נכנס טמא למקדש?","ענה לו רבא: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 באותו ענין"],["\u0003\"טמא יהיה\"\u0004 (במדבר יט, יג) לומר: \u0003מכל מקום,\u0004 מכל סיבה שנטמא הרי הוא טמא.","ומקשים: הרי \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 כתוב \u0005נצרך לו]\u0006 לענין אחר, \u0003לכדתניא\u0004 \u0005[לכמו ששנויה\u0006 בברייתא\u0005]:\u0006 \u0003\"טמא יהיה\"\u0004 — הרי זה בא \u0003לרבות טבול יום\u0004 אדם שנכנס למקדש באותו יום שטבל מטומאתו, שאף הוא חייב כרת, \u0003\"טומאתו בו\"\u0004 (במדבר יט, יג) — \u0003לרבות מחוסר כיפורים\u0004 כגון מצורע שנטהר מטומאתו אבל עדיין לא הקריב קרבן לגמר טהרתו! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003אנא\u0004 \u0005[אני]\u0006 \u0003מ\"עוד טומאתו\" קא אמינא\u0004 \u0005[אני אומר],\u0006 אני למד דין זה. כלומר, מכיון שנאמר \"עוד טומאתו בו\", הרי \"עוד\" זה בא לרבות וללמד שבכל אופן שיש בו טומאה הוא חייב. זו היתה גרסה אחת של הסוגיה.","\u0003איכא דמתני לה\u0004 \u0005[יש ששונה אותה]\u0006 את כל המשא והמתן הזה \u0003אהא\u0004 \u0005[על\u0006 ברייתא \u0005זו]:\u0006 נאמר \u0003\"בחריש ובקציר תשבת\"\u0004 (שמות לד, כא), \u0003ר' עקיבא אומר:\u0004 אף שכתוב זה עוסק בשנת השמיטה, \u0003אינו צריך לומר\u0004 לאסור \u0003חריש של שביעית\u0004 או \u0003קציר של שביעית\u0004 עצמה, \u0003שהרי כבר נאמר \"שדך לא תזרע וכרמך לא תזמר\"\u0004 (ויקרא כה, ד), ואם כן, מה בא כתוב זה ללמדנו? \u0003אלא\u0004 לאסור \u0003אפילו חריש של ערב שביעית שנכנס\u0004 כלומר, שמועיל \u0003ל\u0004שנה ה\u0003שביעית, ו\u0004כן \u0003קציר של\u0004 תבואה שהגיעה לבישולה בשנה ה\u0003שביעית, שיצא\u0004 ונקצר \u0003למוצאי שביעית\u0004 שגם הם אסורים.","\u0003ר' ישמעאל אומר:\u0004 פסוק זה אינו עוסק כלל באיסור שביעית, אלא באיסור חריש וקציר בשבת, וכך יש ללמוד מפסוק זה: \u0003מה חריש\u0004 הוא תמיד מעשה של \u0003רשות,\u0004 שלא מצאנו חרישה שהיא מצוה לעצמה — \u0003אף קציר\u0004 זה הנזכר בכתוב הריהו דווקא קציר של \u0003רשות. יצא\u0004 מכלל זה \u0003קציר העומר שהוא מצוה,\u0004 והוא מותר גם בשבת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא מרבנן\u0004 \u0005[אחד החכמים]\u0006 \u0003לרבא: ממאי\u0004 \u0005[ממה,\u0006 מנין\u0005]\u0006 יודע ר' ישמעאל שהחרישה שמדובר עליה באותו פסוק היא \u0003חרישה\u0004 של \u0003רשות? דלמא\u0004 \u0005[שמא]\u0006 מדובר ב\u0003חרישת\u0004 שדה לצורך תבואה שתשמש לקצירת ה\u0003עומר\u0004 שהיא \u0003מצוה, ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003אמר רחמנא\u0004 \u0005[אמרה התורה]\u0006 \u0003\"תשבת\"! אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003כיון\u0004 ש\u0003אם מצא\u0004 שדה \u0003חרוש\u0004 \u0003אינו חורש\u0004 כלומר, אינו מצווה לחרוש במיוחד לצורך העומר, והוא זורע לצורך העומר במה שנחרש כבר, אם כן \u0003לאו\u0004 \u0005[אין]\u0006 בחריש זה כשלעצמו \u0003מצוה.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבינא לרבא\u0004 ממשנתנו: \u0003יצא האב המכה את בנו, והרב הרודה את תלמידו, ושליח בית דין\u0004 שאם הרגו בשגגה, בזמן שקיימו את מצוותם — פטורים מגלות. ויש לברר: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 פטור האב המכה את בנו? \u0003לימא\u0004 \u0005[נאמר]\u0006 \u0003כיון\u0004 ש\u0003אילו גמיר\u0004 \u0005[היה לומד]\u0006 הבן, \u0003לאו\u0004 \u0005[לא]\u0006 היתה זו \u0003מצוה\u0004 להכותו, \u0003השתא נמי לאו\u0004 \u0005[עכשיו גם כן,\u0006 כשמכהו לצורך, \u0005אין\u0006 זו\u0005]\u0006 \u0003מצוה,\u0004 ויהיה חייב! השיב לו רבא: \u0003התם אף על גב דגמיר\u0004 \u0005[שם אף על פי ש\u0006הוא \u0005לומד],\u0006 \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מצוה קא עביד\u0004 \u0005[עושה\u0006 האב\u0005]\u0006 כאשר מכה אותו, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"יסר בנך ויניחך\"\u0004 (משלי כט, יז).","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר רבא: לאו מילתא היא דאמרי\u0004 \u0005[אין זה דבר\u0006 של ממש מה \u0005שאמרתי],\u0006 שלא זה ההסבר מנין שאין הפסוק עוסק בחריש של מצוה. אלא זה הוא ההסבר: \u0003קצירה\u0004 שנאמרה בכתוב זה היא \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003חרישה, מה חרישה\u0004 הנזכרת בפסוק זה, אם \u0003מצא חרוש\u0004 — \u0003אינו חורש,\u0004 שאין כלל חרישה שהיא מצוה לעצמה, \u0003אף קצירה נמי\u0004 \u0005[גם כן]\u0006 הנזכרת בפסוק זה, הרי היא כזו שאם \u0003מצא קצור אינו קוצר, ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 שמדובר בפסוק זה כשחורש וקוצר לצורך \u0003מצוה,\u0004 וכי \u0003מצא קצור אינו קוצר?!\u0004 הלא \u0003מצוה לקצור ולהביא\u0004 את העומר! ומכאן שמדובר בקציר של רשות.","\u0003האב גולה על ידי\u0004 (בגלל) \u0003הבן,\u0004 שאם הרג את הבן בשגגה — הריהו גולה בגלל הריגה זו לעיר מקלט. \u0003ו\u0004כן \u0003הבן גולה על ידי האב\u0004 אם הרגו בשגגה. \u0003הכל גולין על ידי ישראל\u0004 שמי שהרג בשגגה אדם מישראל הרי זה גולה, \u0003וישראל גולין על ידיהן, חוץ מגר תושב. וגר תושב אינו גולה\u0004 כשהורג בשגגה \u0003אלא על ידי גר תושב\u0004 אחר.","נאמר במשנה: \u0003האב גולה על ידי הבן.\u0004 ומקשים: \u0003והאמרת\u0004 \u0005[והרי אמרת]\u0006 במשנה הקודמת: \u0003יצא האב המכה את בנו,\u0004 שאינו גולה! ומשיבים: במשנתנו מדובר \u0003דגמיר\u0004 \u0005[ש\u0006הבן \u0005לומד],\u0006 ואין זו הכאה של מצוה. ומקשים: \u0003והאמרת אף על גב דגמיר\u0004 \u0005[והרי אמרת\u0006 ש\u0005אף על פי ש\u0006הוא \u0005לומד]\u0006 \u0003מצוה קעביד\u0004 \u0005[הוא עושה]!\u0006 ומשיבים: כאן מדובר \u0003בשוליא דנגרי\u0004 \u0005[בשוליה של נגרים],\u0006 במי שאביו מלמדו נגרות, והיכה אותו אביו משום שאינו לומד כראוי.","ומקשים: גם \u0003שוליא דנגרי\u0004 — \u0003חיותא היא דלמדיה\u0004 \u0005[\u0006ב\u0005שוליית הנגרים\u0006 — \u0005חיים הוא שלימדו],\u0006 ומצוה עושה האב כשמלמד אותו, ורשות בידו להכותו לשם כך! ומשיבים: מדובר \u0003דגמיר אומנותא אחריתי\u0004 \u0005[שלומד אומנות אחרת]\u0006 ולכן יש בידו פרנסה לחיים, ולכן אין רשות לאב להכותו שילמד דווקא מקצוע זה.","שנינו במשנה: \u0003והבן גולה על ידי האב וכו'. ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005],\u0006 שהרי על הכתוב \"ונס שמה רוצח \u0003מכה נפש\u0004 בשגגה\" (במדבר לה, יא) אמרו: \u0003פרט למכה אביו,\u0004 שעונשו חמור יותר ממכה נפש סתם, ואינו יכול לגלות. \u0003אמר רב כהנא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זו]\u0006 כשיטת \u0003ר' שמעון, והא\u0004 \u0005[וזו]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 שנחלקו מה דינו של ההורג את אביו במזיד, שחייב שתי מיתות: סייף — כרוצח, משום שהרג את אביו, וחנק — משום שחבל בו, ודינו למות בחמורה שביניהן.","\u0003ל\u0004דעת \u0003ר' שמעון\u0004 ש\u0003אמר\u0004 שדין \u0003חנק חמור מסייף,\u0004 ולכן דינו בחנק, הרי דווקא \u0003שגגת\u0004 עבירה שבמזיד חייב עליה מיתת \u0003סייף\u0004 \u0003ניתנה לכפרה\u0004 על ידי גלות, אבל \u0003שגגת חנק\u0004 שהיא חמורה יותר, \u0003לא ניתנה לכפרה\u0004 על ידי גלות.","ואילו \u0003לרבנן דאמרי\u0004 \u0005[ל\u0006דעת \u0005חכמים שאומרים]\u0006 \u0003סייף חמור מחנק,\u0004 ולכן דינו של הורג אביו בסייף, הרי \u0003הורג אביו [בשוגג]\u0004 \u0003שגגת סייף הוא, ושגגת סייף\u0004 הרי \u0003ניתנה לכפרה\u0004 אצל כל רוצח, והיא הדעה המובאת במשנתנו.","\u0003רבא אמר:\u0004 מה ששנינו שמכה אביו אינו גולה — אין כוונתו למי שהיכה ותוך כדי כך הרג את אביו בשגגה, שאדם כזה גולה. אלא כוונתו: \u0003פרט לעושה חבורה באביו בשוגג,\u0004 שהוא אינו גולה. והחידוש שבדבר הוא, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003כיון\u0004 שאם עשה חבורה באביו \u0003במזיד בר קטלא\u0004 \u0005[בן מוות]\u0006 \u0003הוא,\u0004 אם כן, אם עשה זאת \u0003בשוגג נמי ליגלי\u0004 \u0005[גם כן יגלה\u0006 על כך\u0005],\u0006 כמי ששגג ברצח, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שדין גלות בשגגה הוא דווקא בהורג, ולא בעבירות אחרות.","שנינו ש\u0003הכל גולין על ידי ישראל\u0004 וישראל גולין על ידיהן, שאם הרגו בשגגה את ישראל הרי הם גולים, ולהיפך. ושואלים: \u0003\"הכל גולין על ידי ישראל\" לאיתויי מאי\u0004 \u0005[להביא\u0006 לרבות \u0005מה],\u0006 את מי מוסיפים על ידי הביטוי \"הכל\"? ומשיבים: \u0003לאיתויי עבד וכותי.\u0004 ומעירים: \u0003תנינא להא\u0004 \u0005[שנינו\u0006 כבר \u0005את זה]\u0006 \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003עבד וכותי גולה ולוקה על ידי ישראל, ו\u0004כן \u0003ישראל גולה ולוקה על ידי כותי ועבד.\u0004","ודנים בברייתא זו, \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003עבד וכותי גולה על ידי ישראל ולוקה, גולה\u0004 — כגון \u0003דקטליה\u0004 \u0005[שהרגו]\u0006 את הישראל בשגגה, \u0003ולוקה —\u0004 \u0003דלטייה\u0004 \u0005[שקיללו]\u0006 ועבר בכך על מצות לא תעשה. \u0003אלא ישראל גולה ולוקה על ידי כותי\u0004 כיצד הוא? \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003גולה\u0004 — \u0003דקטליה\u0004 \u0005[שהרג אותו,\u0006 את הכותי\u0005]\u0006 בשגגה, \u0003אלא לוקה אמאי\u0004 \u0005[על מה]?\u0006 אם תאמר משום \u0003דלטייה\u0004 \u0005[שקילל אותו],\u0006 הלוא מן הפסוק ממנו למדו איסור זה, \u0003\"ונשיא בעמך לא תאר\"\u0004 (שמות כב, כז), דייקו כי מדובר בו דווקא \u0003בעושה מעשה עמך,\u0004 שנוהג כישראל כשר, ולא ברשע. וכותי זה, גם אם נידון כגר, מכל מקום אינו נוהג כהוגן, שכיון שהוא כותי הוא עובר על כמה וכמה מצוות, ואיננו עושה מעשה עמך!","\u0003אלא אמר רב אחא בר יעקב:\u0004 מה שהוזכר בברייתא זו שלוקה אינו בקללה, אלא \u0003כגון שהעיד בו\u0004 הישראל בכותי, וכן הכותי בישראל, שהוא חייב מלקות, \u0003והוזם.\u0004 ומקשים: \u0003דכוותיה גבי\u0004 \u0005[וכיוצא בו אצל]\u0006 \u0003עבד,\u0004 צריך אתה לפרש \u0003ש\u0004העבד \u0003העיד בו\u0004 באדם מישראל שחייב מלקות \u0003והוזם,\u0004 ואולם \u0003עבד בר עדות הוא?\u0004 הלוא אין העבד כשר להעיד! \u0003אלא אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים],\u0006 שהכותי והעבד לוקה בגלל ישראל, ולהיפך — \u0003כגון שהכהו הכאה\u0004"],["\u0003שאין בה\u0004 בגובה התשלום שחייב עליה, כדי \u0003שוה פרוטה,\u0004 ואז לוקים עליה. ש\u0003אמר ר' אמי אמר ר' יוחנן:\u0004 אף שהמכה את חבירו משלם לו תשלומי נזיקין, ואינו לוקה, אם \u0003הכהו\u0004 לחבירו \u0003הכאה שאין בה שוה פרוטה,\u0004 כיון שאין בה כדי תשלום — הרי זה \u0003לוקה\u0004 ארבעים מלקות חסר אחת, שעבר על \"לא תעשה\" שבתורה. ומעירים: \u0003ו\u0004צריך לומר לשיטה זו ש\u0003לא מקשינן\u0004 \u0005[אין אנו מקישים,\u0006 משווים\u0005]\u0006 \u0003הכאה לקללה\u0004 כפי שיש הסבורים כן, אלא אף על פי שבקללה האיסור הוא דווקא כאשר המקולל הוא \"עושה מעשה עמך\" ולא עובר עבירה, כגון כותי, מכל מקום לגבי הכאה, גם אם היכה אדם שאינו כשר — לוקה על הכאתו.","שנינו במשנה: \"הכל גולין על ידי ישראל, וישראל גולין על ידיהן, \u0003חוץ מעל ידי גר תושב\" וכו'.\u0004 ושואלים: \u0003אלמא\u0004 \u0005[מכאן]\u0006 יש להסיק ש\u0003גר תושב גוי הוא,\u0004 ולכן אין הוא גולה כשהרג ישראל. \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של המשנה\u0005]:\u0006 \u0003גר תושב גולה על ידי גר תושב,\u0004 ומכאן יש להסיק שאין הוא כגוי, שהרי אם גוי הוא — הלוא אין דין גלות בגוי, ונמצאת איפוא סתירה בין תחילת המשנה לסופה! \u0003אמר רב כהנא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן\u0004 בסוף המשנה מדובר \u0003בגר תושב שהרג גר תושב\u0004 שהריהו גולה, \u0003כאן\u0004 בתחילת המשנה מדובר \u0003בגר תושב שהרג\u0004 את \u0003ישראל\u0004 שאינו גולה, משום שאין דינו כישראל שניתן לו להתכפר בגלות.","\u0003איכא דרמי קראי אהדדי\u0004 \u0005[\u0006ו\u0005היה שהשליך מקראות זה על זה,\u0006 הראה סתירה ביניהם\u0005],\u0006 \u0003כתיב\u0004 \u0005[נאמר]\u0006 בכתוב אחד \u0003\"לבני ישראל ולגר ולתושב בתוכם תהיינה שש הערים\u0004 האלה למקלט\" (במדבר לה, טו), הרי שגר תושב גולה, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בפסוק אחר: \u0003\"והיו לכם הערים למקלט\"\u0004 (במדבר לה, יב), ודיוק הכתוב הוא \u0003\"לכם\"\u0004 — \u0003ולא לגרים\u0004 תושבים, שאינם גולים! על כך \u0003אמר רב כהנא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן\u0004 שאינם גולים — מדובר \u0003בגר תושב שהרג ישראל, כאן\u0004 שגולים — מדובר \u0003בגר תושב שהרג גר תושב.\u0004","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 לדין זה של המשנה ממה ששנינו בברייתא: \u0003לפיכך גר\u0004 (תושב) \u0003וגוי שהרגו\u0004 — \u0003נהרגין,\u0004 ואפילו הרגו בשוגג. ונדייק: \u0003קתני\u0004 \u0005[הריהו שונה]\u0006 \u0003גר דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003גוי,\u0004 שהרי שנה את שניהם יחד, והשווה את דינם. ומכאן נסיק: \u0003מה גוי לא שנא דקטל בר מיניה\u0004 \u0005[לא שונה אם הרג\u0006 את \u0005בן מינו]\u0006 כלומר, גוי כמותו, \u0003ולא שנא דקטל דלאו בר מיניה\u0004 \u0005[ולא שונה אם הרג\u0006 את \u0005שאינו בן מינו,\u0006 כגון ישראל\u0005]\u0006 — הרי זה \u0003נהרג\u0004 בכל מקרה. אם כן \u0003אף גר, לא שנא דקטל בר מיניה ולא שנא קטל דלאו בר מיניה\u0004 \u0005[לא שונה אם הרג\u0006 את \u0005בן מינו ולא שונה אם הרג\u0006 את \u0005שאינו בן מינו]\u0006 הריהו \u0003נהרג\u0004 עליו, ואינו גולה לעיר מקלט!","\u0003אמר רב חסדא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן\u0004 במשנתנו, שיש בו דין גלות מדובר \u0003שהרגו דרך ירידה, כאן\u0004 בברייתא, שאין בו דין גלות מדובר \u0003שהרגו דרך עלייה.\u0004 כיצד? אם גר תושב הרג גר תושב בשגגה \u0003דרך ירידה,\u0004 ש\u0003ישראל גלי\u0004 \u0005[גולה]\u0006 על כגון זה — \u0003איהו נמי סגי ליה\u0004 \u0005[הוא גם כן די לו]\u0006 \u0003בגלות.\u0004 ואולם אם הרגו \u0003דרך עלייה,\u0004 ש\u0003ישראל פטור\u0004 בכגון זה מגלות — \u0003הוא נהרג.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: ולאו\u0004 \u0005[והאם לא]\u0006 \u0003קל וחומר הוא? ומה דרך ירידה\u0004 ש\u0003ישראל גלי\u0004 \u0005[גולה]\u0006 על כך, \u0003איהו נמי סגי ליה\u0004 \u0005[הוא גם כן די לו]\u0006 \u0003בגלות,\u0004 ואינו נענש יותר. אם הרגו \u0003דרך עלייה,\u0004 ש\u0003ישראל פטור,\u0004 וכי \u0003איהו\u0004 \u0005[הוא]\u0006 \u0003נהרג\u0004 ונענש יותר?!","\u0003אלא אמר רבא:\u0004 בברייתא בה למדנו שגר תושב נהרג (אם הרג בשגגה גר תושב אחר) ולא גולה, מדובר \u0003באומר מותר,\u0004 שלא חשב שיש איסור בדבר. אבל בשוגג — גולה, כבמשנה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 הלוא \u0003אומר מותר אנוס הוא,\u0004 שכיון שלא ידע כלל — הריהו כאנוס, ומדוע ייהרג? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003שאני אומר\u0004 לא כך, אלא \u0003אומר מותר\u0004 — \u0003קרוב למזיד הוא,\u0004 שהרי מכל מקום נתכוון להרוג.","ומעירים: \u0003ו\u0004רבא ורב חסדא \u0003אזדו לטעמייהו\u0004 \u0005[הולכים\u0006 הם \u0005לשיטותיהם]\u0006 בענין זה. \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו בבעיה הבאה: גר תושב שהרג אדם \u0003כסבור\u0004 שהוא הורג \u0003בהמה ונמצא\u0004 שהיה זה \u0003אדם,\u0004 חשב שהרג \u0003גוי ונמצא גר תושב. רבא אומר: חייב\u0004 מיתה, ומדוע? לדעתו \u0003אומר מותר קרוב למזיד הוא.\u0004 ואילו \u0003רב חסדא אומר: פטור,\u0004 שלדעתו \u0003אומר מותר אנוס הוא.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב חסדא:\u0004 נאמר באבימלך מלך גרר, שלקח אליו את שרה אשת אברהם: \"ויבוא אלקים אל אבימלך בחלום הלילה ויאמר לו \u0003הנך מת על האשה אשר לקחת\u0004 והיא בעולת בעל\" (בראשית כ, ג), והרי כאשר לקח את שרה חשב שהיא פנויה, שהרי אברהם אמר לו ששרה אחותו היא, ולפיכך סבר שהדבר מותר, ובכל זאת נאמר לו שהוא חייב מיתה. \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה — הנך ראוי להיענש במיתה \u0003בידי אדם\u0004 בבית דין? ומכאן שהאומר מותר — חייב!","ודוחים: לא, הכוונה היא שחייב מיתה \u0003בידי שמים,\u0004 אבל בידי אדם אין על כך עונש. ומעירים: \u0003דיקא נמי דכתיב\u0004 \u0005[מדוייק גם כן\u0006 שכן הוא, \u0005ש\u0006הרי \u0005נאמר]\u0006 \"ואחשוך גם אנכי אותך \u0003מחטוא לי\"\u0004 (בראשית כ, ו), משמע שהחטא הוא כלפי שמים בלבד, ובדיני אדם לא היה חייב.","ומקשים על כך: \u0003ולטעמיך\u0004 \u0005[ולשיטתך],\u0006 שכך אתה מדייק מן הכתוב, מה שאמר יוסף לאשת פוטיפר \"ואיך אעשה הרעה הגדולה הזאת \u0003וחטאתי לאלהים\"\u0004 (בראשית, לט, ט), האם גם כן תדייק כך ותאמר שהכוונה היא רק \u0003לאלהים ולא לאדם?\u0004 הלא חטא זה הוא ניאוף, ועונשו גם בדיני בני נח במיתה! \u0003אלא\u0004 כוונת הדברים היא שהחטא הוא לאלהים, \u0003דינו מסור לאדם\u0004 לבצע בו דין מוות, \u0003הכא נמי\u0004 \u0005[כאן גם כן,\u0006 באבימלך\u0005]\u0006 אפשר לומר שחוטא הוא כלפי שמים ו\u0003דינו מסור לאדם,\u0004 ואם כן אין מכאן הוכחה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי לרבא:\u0004 הרי אמר אבימלך לפני ה' \u0003\"הגוי גם צדיק תהרג\"\u0004 (בראשית, כ, ד), ואם אבימלך אומר כן לפני ה' ואין הקדוש ברוך הוא אומר לו שרשע הוא, משמע שהודה לו, ומכאן שהאומר מותר נחשב כאנוס! ומשיבים: אינו כן, \u0003התם כדקא מהדרי עלויה\u0004 \u0005[שם הוא כפי שמשיבים לו\u0006 תשובה משמים\u0005]\u0006 שאינו צודק בטענתו, אמר לו הקדוש ברוך הוא: \u0003\"ועתה השב אשת האיש כי נביא הוא\"\u0004 (בראשית, כ, ז),"],["ויש לתמוה: מה עניינו של \"כי נביא הוא\"? וכי אשת \u0003נביא הוא דתיהדר\u0004 \u0005[שתוחזר],\u0006 ואילו זו \u0003דלאו\u0004 \u0005[שלא]\u0006 אשת \u0003נביא\u0004 היא \u0003לא תיהדר\u0004 \u0005[תוחזר]?!\u0006","\u0003אלא\u0004 צריך לפרש זאת \u0003כ\u0004פי ש\u0003אמר ר' שמואל בר נחמני.\u0004 ש\u0003אמר ר' שמואל בר נחמני אמר ר' יונתן: הכי קאמר ליה\u0004 \u0005[כך אמר לו]\u0006 הקדוש ברוך הוא לאבימלך \u0003\"ועתה השב אשת האיש\"\u0004 (בראשית כ, ז) \u0003מכל מקום\u0004 כלומר, בלא קשר לכך שהוא נביא. ומה שנאמר \"כי נביא הוא\" מובנו בהקשר אחר: \u0003ודקאמרת\u0004 \u0005[ומה שאתה אומר]\u0006 \u0003\"הגוי גם צדיק תהרג, הלא הוא אמר לי אחותי היא\" וגו'\u0004 (בראשית, ד— ה) לומר שאנוס אתה ופטור בדין זה — אין אתה צודק בכך, כי \u0003נביא הוא וממך למד\u0004 שעליו לנהוג כפי שנהג. שכן \u0003אכסנאי\u0004 (אורח) \u0003הוא שבא לעיר, על עסקי אכילה ושתייה שואלין אותו\u0004 מארחיו, האם הוא זקוק למאכל או למשקה, \u0003כלום שואלין אותו\u0004 על האשה שהיא עמו \u0003\"אשתך זו\" \"אחותך זו\"?\u0004 אלא הבין שאתם חשודים על חטיפת נשים, ומשום כך אמר על שרה שאחותו היא, ולכן היית חייב מיתה על שרה.","ומעירים: \u0003מכאן שבן נח נהרג\u0004 על עבירה שעונשה מיתה גם במקרה שהוא אומר מותר, \u0003שהיה לו ללמוד ולא למד.\u0004","\u0003הסומא\u0004 (העיוור) שהרג אדם בשגגה — \u0003אינו גולה, דברי ר' יהודה. ר' מאיר אומר:\u0004 אף הוא \u0003גולה. השונא אינו גולה,\u0004 משום שיש להניח שלא היה זה בשגגה גמורה. \u0003ר' יוסי אומר: השונא\u0004 לא רק שאינו גולה, אלא אף \u0003נהרג\u0004 על ידי בית הדין, \u0003מפני שהוא כמועד\u0004 (כמותרה) על ידי עדים שלא יעשה כן, שחזקתו שבכוונה עשה. \u0003ר' שמעון אומר: יש שונא גולה ויש שונא שאינו גולה. זה הכלל\u0004 בדבר זה: \u0003כל שהוא\u0004 הרואה \u0003יכול לומר לדעת הרג,\u0004 שהמעשה אירע באופן שיש מקום להניח שהיתה זו הריגה במזיד — הרי השונא נהרג על כך. ואף שהוא אומר שהיתה זו שגגה — אנו מניחים שלא היה כן. \u0003ו\u0004אם \u0003שלא לדעת הרג,\u0004 אלא רואים שהדבר היה כדרך תאונה — \u0003הרי זה גולה\u0004 אפילו כאשר הוא שונא.","על דין סומא שנחלקו בו ר' יהודה ור' מאיר במשנה, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר בפרשת הגולים לעיר מקלט, שהגולה הוא מי שהרג את רעהו \"\u0003בלא ראות\u0004\" (במדבר לה, כג), ומשמע שמדובר במי שבדרך כלל רואה — \u0003פרט לסומא,\u0004 שאינו רואה כלל, ולא רק במקרה זה, אלו \u0003דברי ר' יהודה. ר' מאיר אומר\u0004 להיפך: \u0003\"בלא ראות\"\u0004 — הרי זה בא \u0003לרבות את הסומא\u0004 שאף הוא גולה.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מהו הטעם]\u0006 של \u0003ר' יהודה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בפרשת הגולים \u0003\"ואשר יבא את רעהו ביער\"\u0004 (דברים יט, ה), והרי זה ביטוי כללי, הכולל כל אדם, ו\u0003אפילו\u0004 הוא \u0003סומא. אתא\u0004 \u0005[בא]\u0006 הכתוב \u0003\"בלא ראות\" מעטיה\u0004 \u0005[מיעט אותו]\u0006 שמי שאינו יכול לראות כלל, אינו בגדר הלכה זו.","\u0003 ור' מאיר\u0004 לומד בצורה אחרת: \u0003\"בלא ראות\"\u0004 בא \u0003למעט, \"בבלי דעת\"\u0004 (דברים יט, ד) גם הוא בא \u0003למעט,\u0004 אם כן \u0003הוי\u0004 \u0005[הריהו]\u0006 \u0003מיעוט אחר מיעוט,\u0004 וכלל הוא: \u0003אין מיעוט אחר מיעוט אלא לרבות,\u0004 ולכן מרבה אף את הסומא, שאף הוא גולה.","ושואלים: \u0003ור' יהודה\u0004 מה הוא משיב על כך? ומשיבים: \u0003\"בבלי דעת\" פרט למתכוין הוא דאתא\u0004 \u0005[שבא],\u0006 לומר שהמתכוון אינו גולה, ולשיטתו \"בלא ראות\" ו\"בלי דעת\" אינם מיעוט באותו נושא, ולכן אין זה בכלל מיעוט אחר מיעוט הבא לרבות.","שנינו במשנה שר' \u0003יוסי אומר השונא נהרג\u0004 מפני שהוא כמועד. ושואלים: \u0003והא לא אתרו ביה\u0004 \u0005[והרי\u0006 בפועל \u0005לא התרו בו\u0006 העדים\u0005],\u0006 ואין בית דין עונשים עונשי גוף אלא לאחר התראה! ומשיבים: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 כדעת \u0003ר' יוסי בר יהודה היא, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' יוסי בר יהודה אומר: חבר\u0004 (תלמיד חכם) \u0003אינו צריך התראה\u0004 כדי שיענישו אותו בית דין בעונשי הגוף על עבירה שעשה, \u0003לפי ש\u0004מעיקרה \u0003לא ניתנה התראה אלא להבחין בין שוגג למזיד,\u0004 והחבר — חזקה עליו שיודע, ולכן מזיד הוא.","שנינו במשנה \u0003ר' שמעון אומר: יש שונא גולה\u0004 ויש שונא שאינו גולה. ועל כך מוסיפים: \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003כיצד אמר ר' שמעון יש שונא גולה ויש שונא שאינו גולה?\u0004 כגון, \u0003נפסק\u0004 (נקרע) החבל שהיה בידו, ונפל חפץ שהיה תלוי בו, והרג את חבירו — הרי זה \u0003גולה\u0004 על ידו, שנראה שהיתה זו תאונה. אבל אם \u0003נשמט\u0004 חפץ מידו — \u0003אינו גולה,\u0004 שאנו מניחים שהיה זה הדבר במזיד, שהירפה את אחיזתו עד שנפל החפץ.","ושואלים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' שמעון אומר: לעולם אינו גולה עד שישמט מחצלו\u0004 (מעגילה) \u0003מידו,\u0004 שעושה בו מלאכה. וכיון שאמר דין זה בכלל, גם לגבי שונאו, אם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדין \u0003נפסק\u0004 על דין \u0003נפסק, קשיא\u0004 \u0005[קשה]\u0006 מדין \u0003נשמט\u0004 על דין \u0003נשמט!\u0004","ומשיבים: \u0003נפסק\u0004 על \u0003נפסק לא קשיא\u0004 \u0005[קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — \u0003באוהב, והא\u0004 \u0005[וזה]\u0006 — \u0003בשונא,\u0004 שבאוהב אנו מניחים שהיה אנוס והוא פטור מגלות, ובשונא אנו מניחים שלא התכוון, אבל מצד אחר לא היה אנוס לגמרי, ולכן גולה.","ו\u0003נשמט\u0004 על \u0003נשמט\u0004 גם כן \u0003לא קשיא\u0004 \u0005[קשה],\u0006 כי \u0003הא\u0004 \u0005[זו]\u0006 — דעת \u0003רבי, והא\u0004 \u0005[וזו]\u0006 — דעת \u0003רבנן\u0004 \u0005[\u0006\u0005חכמים]\u0006 שנחלקו במשנה לעיל (מכות ז,ב) במקרה שנשמט ברזל מן הקת והרג, שלדעת רבי אינו גולה, ולדעת חכמים גולה. שהברייתא הראשונה, האומרת שאם נשמט מידו אינו גולה — דעת רבי היא, לפי שיטת ר' שמעון. והברייתא השניה, האומרת שאם נשמט מחצלו גולה — דעת חכמים לשיטתו.","\u0003להיכן גולין\u0004 ההורגים בשגגה — \u0003לערי מקלט, לשלש\u0004 הערים \u0003שבעבר הירדן ולשלש\u0004 הערים \u0003שבארץ כנען. שנאמר \"את שלש הערים תתנו מעבר לירדן ואת שלש הערים תתנו בארץ כנען\" וגו'\u0004 (במדבר לה, יד). ומעירים: \u0003עד שלא נבחרו שלש\u0004 ערי המקלט \u0003שבארץ ישראל לא היו שלש שבעבר הירדן קולטות,\u0004 אף ששלוש אלה נבחרו כבר על ידי משה (ראה דברים ד, מא), \u0003שנאמר \"שש ערי מקלט תהיינה\"\u0004 (במדבר לה, יג) לומר: \u0003עד שיהיו ששתן קולטות כאחת\u0004 (ביחד), באותו הזמן, וכל עוד חלק מהן אינן קולטות — אף השאר אינן קולטות.","ועוד בדין ערי מקלט: \u0003ומכוונות להן דרכים מזו לזו,\u0004 כלומר שהיו מסדרים ומיישרים את הדרכים המובילות לערי המקלט, \u0003שנאמר \"תכין לך הדרך ושלשת\"\u0004 (דברים יט, ג).","\u0003ומוסרין להן\u0004 לבורחים לעיר המקלט \u0003שני תלמידי חכמים, שמא יהרגנו\u0004 גואל הדם \u0003בדרך. וידברו אליו\u0004 אל גואל הדם אותם תלמידי חכמים, וישכנעו אותו שלא יהרגנו מפני שהוא שוגג. \u0003ר' מאיר אומר:\u0004 אף \u0003הוא\u0004 הרוצח בשגגה \u0003מדבר על ידי עצמו,\u0004 שהוא יכול לדבר עבור עצמו, \u0003שנאמר \"וזה דבר הרצח\u0004 אשר ינוס שם וחי\" (במדבר, יט, ד), ללמד שהרוצח עצמו מדבר.","\u0003ר' יוסי בר יהודה אומר: בתחלה,\u0004 הדבר הראשון שעושים ההורגים אדם, \u0003אחד שוגג ואחד מזיד מקדימין\u0004 (מזדרזים) ובורחים \u0003לערי מקלט, ובית דין\u0004 שבעירו \u0003שולחין ומביאין אותו משם\u0004 לדונו. \u0003מי שנתחייב מיתה בבית דין\u0004 שנמצא שהיה רוצח במזיד — \u0003הרגוהו\u0004 בית הדין, \u0003ו\u0004זה \u0003שלא נתחייב מיתה\u0004 כגון שמצאו שאירע הדבר באונס — \u0003פטרוהו. מי שנתחייב גלות\u0004 — \u0003מחזירין אותו למקומו\u0004 (לעיר המקלט), \u0003שנאמר\u0004 \"ושפטו העדה בין המכה ובין גואל הדם... \u0003והשיבו אתו העדה אל עיר מקלטו\" וגו'\u0004 (במדבר לה, כה) משמע שקודם שנשפט כבר היה בעיר המקלט, ולאחר מכן מביאים אותו למשפט לפני העדה במקום המעשה, ואחר כך משיבים אותו לעיר המקלט.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלש ערים הבדיל משה בעבר הירדן\u0004 לערי מקלט, \u0003וכנגדן הבדיל יהושע בארץ כנען, ומכוונות היו\u0004 הערים שכאן וכאן זו כנגד זו, \u0003כמין שתי שורות\u0004 גפנים \u0003שבכרם,\u0004 ובאופן זה: \u0003חברון בהר יהודה כנגד בצר במדבר, שכם בהר אפרים כנגד רמות בגלעד, קדש בהר נפתלי כנגד גולן בבשן.\u0004 ונאמר \u0003\"ושלשת\u0004 את גבול ארצך\" (דברים יט, ג) כלומר, \u0003שיהו משולשין\u0004 במרחקים שווים, כלומר \u0003שיהא\u0004 המרחק \u0003מדרום\u0004 מהגבול הדרומי של הארץ, עד \u0003לחברון,\u0004 שהיא עיר המקלט הראשונה מדרום, \u0003כ\u0004מו המרחק \u0003מחברון לשכם, ומחברון לשכם כמשכם לקדש, ומשכם לקדש כמקדש ל\u0004גבול ה\u0003צפון.\u0004","ותוהים תחילה על מספר הערים: \u0003בעבר הירדן\u0004 שהיו בו שניים וחצי שבטים בלבד היו \u0003תלת\u0004 \u0005[שלוש]\u0006 ערים, \u0003בארץ ישראל\u0004 שישבו בה תשעה שבטים ויותר — גם כן רק \u0003תלת\u0004 \u0005[שלוש]?!\u0006 \u0003אמר אביי: בגלעד\u0004 שבעבר הירדן \u0003שכיחי\u0004 \u0005[מצויים]\u0006 \u0003רוצחים,\u0004 ולכן היו צריכים להוסיף בעבר הירדן מספר גדול יותר של ערי מקלט, ל"],["\u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"גלעד קרית פעלי און עקבה מדם\"\u0004 (הושע ו, ח). \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הביטוי \u0003\"עקבה מדם\"? אמר ר' אלעזר: שהיו עוקבין\u0004 (אורבים) על מנת \u0003להרוג נפשות.\u0004","ושואלים עוד: \u0003ומאי שנא מהאי גיסא ומהאי גיסא דמרחקי\u0004 \u0005[ומה שונה מצד זה ומצד זה שהיו\u0006 ערי המקלט \u0005רחוקות],\u0006 שהרי מגבול הארץ הצפוני או הדרומי עד עיר המקלט הראשונה היה המרחק גדול, רבע מאורך הארץ, \u0003ומאי שנא מציעאי דמקרבי\u0004 \u0005[ומה שונות האמצעיות שהן קרובות]?\u0006 שהרי באמצע הארץ, המרחק ממקום הרצח לעיר המקלט הקרובה הוא לכל היותר חצי ממרחק זה!","\u0003אמר אביי: בשכם נמי שכיחי\u0004 \u0005[גם כן מצויים]\u0006 \u0003רוצחים, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"וכחכי איש גדודים חבר כהנים, דרך ירצחו שכמה\" וגו'\u0004 (הושע ו, ט). ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חבר כהנים\"? אמר ר' אלעזר: שהיו מתחברין\u0004 יחד \u0003להרוג נפשות, ככהנים הללו שמתחברין\u0004 שהולכים חבורות חבורות \u0003לחלוק\u0004 ביניהם את \u0003התרומות בבית הגרנות.\u0004","ושואלים: \u0003ותו ליכא\u0004 \u0005[ועוד אין]\u0006 אלא רק שש הערים הללו? \u0003והא כתיב\u0004 \u0005[והרי נאמר]:\u0006 \"את שש ערי המקלט אשר תתנו לנוס שמה הרוצח \u0003ועליהם תתנו ארבעים ושתים עיר\"\u0004 (במדבר לה, י), משמע שלכל ערי הלויים יש דין ערי מקלט! \u0003אמר אביי: הללו,\u0004 שש הערים שנקבעו לכך — \u0003קולטות\u0004 את הרוצח בשגגה \u0003בין\u0004 שהגיע לשם \u0003לדעת\u0004 שידע שזו עיר מקלט, \u0003בין שלא לדעת\u0004 (ידע). ואילו \u0003הללו,\u0004 ארבעים ושתים האחרות, \u0003לדעת\u0004 — \u0003קולטות, שלא לדעת\u0004 — \u0003אינן קולטות.\u0004","ועוד שואלים: \u0003וחברון,\u0004 האם \u0003עיר מקלט הוא? והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"ויתנו לכלב את חברון כאשר דבר משה\"\u0004 (שופטים א, כ), משמע שחברון היתה שייכת לכלב שהיה משבט יהודה, ולא היתה עיר של לויים! \u0003אמר אביי: פרוודהא\u0004 \u0005[פרבריה,\u0006 הכפרים שסביבה\u0005]\u0006 ניתנו לכלב, ואולם העיר עצמה היתה עיר של כהנים, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במפורש בחלוקת הערים ללויים: \"ויתנו להם את קרית ארבע... היא חברון... \u0003ואת שדה העיר ואת חצריה נתנו לכלב בן יפנה\"\u0004 (יהושע כא, יא— יב).","ועוד שואלים: \u0003ו\u0004האם \u0003קדש עיר מקלט הואי\u0004 \u0005[היתה]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"וערי מבצר הצדים צר וחמת רקת וכנרת וגו' וקדש ואדרעי ועין חצור\"\u0004 (יהושע, יט, לה—לז), \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003ערים הללו\u0004 ערי המקלט, \u0003אין עושין אותן לא טירין\u0004 (ישובים) \u0003קטנים, ולא כרכים גדולים, אלא עיירות בינוניות.\u0004 ומן הכתוב נראה שקדש היתה עיר מבצר גדולה! \u0003אמר רב יוסף: תרתי\u0004 \u0005[שתי]\u0006 \u0003קדש הואי\u0004 \u0005[היו],\u0006 וקדש זו הנזכרת ביהושע בין ערי המבצר איננה עיר המקלט קדש. \u0003אמר רב אשי: כגון\u0004 העיר \u0003סליקום, ואקרא\u0004 \u0005[והמבצר]\u0006 של \u0003סליקום,\u0004 שהיו קרובים זה לזה, אבל כל אחד היה ישוב לעצמו. וכן היה מבצר בקדש, והעיר עצמה, שהיתה עיירה בינונית, היא שימשה כעיר מקלט.","\u0003גופא\u0004 \u0005[\u0006דנים \u0005לגופה]\u0006 של אותה הברייתא שהזכרנו, ומביאים אותה בשלמות: \u0003ערים הללו\u0004 של מקלט, \u0003אין עושין אותן לא טירין קטנים ולא כרכין גדולים, אלא עיירות בינוניות. ואין מושיבין\u0004 (מקימים) \u0003אותן אלא במקום מים, ואם אין שם מים\u0004 שאין מעיין סמוך לעיר — \u0003מביאין להם מים\u0004 על ידי אמת מים. \u0003ו\u0004כן \u0003אין מושיבין אותן אלא במקום שווקים, ואין מושיבין אותן אלא במקום אוכלוסין\u0004 שיש הרבה אנשים החיים באזור, שבאים לעיר. \u0003נתמעטו אוכלוסיהן\u0004 — \u0003מוסיפין עליהן. נתמעטו דיוריהן\u0004 (תושבים) הדרים בעיר עצמה — \u0003מביאין להם\u0004 דיירים חדשים, שיש בהם \u0003כהנים לוים וישראלים.\u0004","\u0003ואין מוכרין בהן\u0004 בערי המקלט \u0003לא כלי זיין, ולא כלי מצודה\u0004 (צייד) כדי שלא יזדמן נשק לידיו של גואל הדם שיוכל בו להרוג את הרוצח, אלו \u0003דברי ר' נחמיה. וחכמים מתירין. ושוין\u0004 (ומסכימים) ר' נחמיה וחכמים \u0003שאין פורסין בתוכן\u0004 של ערי המקלט \u0003מצודות\u0004 (רשתות), \u0003ואין מפשילין\u0004 (כורכים, עושים) \u0003לתוכן חבלים,\u0004 וטעמו של דבר \u0003כדי שלא תהא רגל גואל הדם מצויה שם,\u0004 שאם גואל הדם בא לעיר המקלט מסיבות שונות, כדי לרכוש מצודות או חבלים, בכל פעם הוא עלול לפגוש את הרוצח, ושמא יהרגנו.","\u0003אמר ר' יצחק: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 המלמד את הדברים הללו — שנאמר ברוצח בשגגה: \u0003\"ונס אל אחת מן הערים האל וחי\"\u0004 (דברים ד, מב), כלומר: \u0003עביד ליה מידי דתהוי ליה חיותא\u0004 \u0005[עשה לו דבר\u0006 כדי \u0005שתהיה לו חיות],\u0006 ולכן צריכים לדאוג שיוכל הנמלט לחיות בעיר הזו.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003תלמיד שגלה\u0004 — \u0003מגלין רבו עמו\u0004 לעיר המקלט, על מנת שילמדנו שם, \u0003שנאמר \"וחי\",\u0004 וכאמור, הכוונה היא: \u0003עביד ליה מידי דתהוי ליה חיותא\u0004 \u0005[עשה לו דבר שתהיה לו\u0006 בו \u0005חיות],\u0006 וכיון שחייו של התלמיד תלויים בלימודו — צריך רבו להיות עמו. \u0003אמר ר' זעירא: מכאן\u0004 אנו למדים \u0003שלא ישנה אדם לתלמיד שאינו הגון,\u0004 שהרי תלמיד כזה יכול לגרום לרבו שיגלה.","\u0003אמר ר' יוחנן: הרב שגלה\u0004 — \u0003מגלין ישיבתו עמו.\u0004 ושואלים: \u0003איני\u0004 \u0005[כן הוא]\u0006 שצריך הרב לגלות? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' יוחנן\u0004 עצמו: \u0003מנין לדברי תורה שהן קולטין,\u0004 שהם נחשבים כעיר מקלט, ושאסור לפגוע באדם העוסק בתורה? \u0003שנאמר\u0004 ברשימת ערי המקלט \u0003\"את בצר\u0004 \u0003במדבר\" וגו'\u0004 (דברים ד, מג), \u0003וכתיב בתריה\u0004 \u0005[ונאמר אחריו]\u0006 \u0003\"וזאת התורה\"\u0004 (דברים ד, מד) לומר שגם התורה היא כעיר מקלט.","ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שתורה נחשבת כעיר מקלט — \u0003בעידנא דעסיק\u0004 \u0005[בזמן ש\u0006הוא \u0005עוסק]\u0006 \u0003בה, הא\u0004 \u0005[זה]\u0006 שאין התורה נחשבת כעיר מקלט — \u0003בעידנא דלא עסיק\u0004 \u0005[בזמן שאינו עוסק]\u0006 \u0003בה.\u0004 מה שאין כן בערי המקלט, שעצם מושבו בעיר היא הגנה לו.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור],\u0006 \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 דברי ר' יוחנן שדברי תורה \u0003קולטין\u0004 — מצילים \u0003ממלאך המות,\u0004 ולא בענין רוצח בשגגה. \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רב חסדא הוה יתיב וגריס בבי\u0004 \u0005[היה יושב ולומד בבית]\u0006 \u0003רב, ולא הוה קא יכול שליחא דמלאכא דמותא למיקרב\u0004 \u0003לגביה\u0004 \u0005[ולא היה יכול שליחו של מלאך המוות להתקרב אליו],\u0006 משום \u0003דלא הוה שתיק פומיה מגירסא\u0004 \u0005[שלא היה שותק פיו מללמוד],\u0006 \u0003סליק ויתיב אארזא דבי\u0004 \u0005[עלה\u0006 השליח הזה \u0005וישב על הארז של בית]\u0006 \u0003רב, פקע ארזא ושתיק\u0004 \u0005[נשבר הארז,\u0006 \u0005והשתתק]\u0006 רב חסדא לרגע מפני הרעש הפתאומי, \u0003ויכיל ליה\u0004 \u0005[ויכול\u0006 היה \u0005לו]\u0006 להמיתו. והיא דוגמה לכך שדברי התורה מצילים ממיתה כאשר עוסק בהם.","\u0003אמר ר' תנחום בר חנילאי: מפני מה זכה ראובן לימנות בהצלה תחלה,\u0004 שעיר המקלט הראשונה ברשימת ערי המקלט (דברים ד, מג) היא העיר בצר שבנחלת ראובן — \u0003מפני שהוא פתח בהצלה תחלה\u0004 בהצלתו של יוסף מידי אחיו, \u0003שנאמר \"וישמע ראובן ויצלהו מידם\"\u0004 (בראשית לז, כא).","\u0003דרש ר' שמלאי: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"אז יבדיל משה שלש ערים בעבר הירדן מזרחה שמש\"\u0004 (דברים ד, מא)? \u0003אמר לו הקדוש ברוך הוא למשה: הזרח שמש לרוצחים,\u0004 תן להם תקוה להצלה. והוא שנאמר \"מזרחה שמש\". \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כך \u0003אמר לו\u0004 הקדוש ברוך הוא: \u0003הזרחת שמש לרוצחים\u0004 על ידי הבדלה זו.","ובענין שנזכר במשנתנו, \u0003דרש ר' סימאי: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"אהב כסף לא ישבע כסף ומי אהב בהמון לא תבואה\"\u0004 (קהלת ה, ט)? \u0003\"אהב כסף לא ישבע כסף\"\u0004 — \u0003זה משה רבינו,\u0004 ומדוע נקרא הוא כך? שכך היתה אהבתו למצוות, \u0003שהיה יודע שאין שלש ערים שבעבר הירדן קולטות\u0004 את הרוצחים בשגגה \u0003עד\u0004 (כל עוד) \u0003שלא נבחרו שלש\u0004 הערים ש\u0003בארץ כנען,\u0004 ומה שעשה בבחירת ערי המקלט לא היתה לו חשיבות למעשה, \u0003ו\u0004מכל מקום \u0003אמר: מצוה שבאה לידי אקיימנה.\u0004","וכך דורשים גם את המשך הפסוק ביחס לתורה: \u0003\"ומי אהב בהמון לא תבואה\"\u0004 — \u0003למי נאה\u0004 (ראוי) \u0003ללמד בהמון\u0004 (בקהל) — \u0003מי שכל תבואה שלו\u0004 (שדורש \"לא\" כמו \"לו\"), שמי שיודע את כל פרי ותנובת התורה, הוא הראוי ללמד אותה ברבים. \u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ר' אלעזר: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"מי ימלל גבורות ה' ישמיע כל תהלתו\"\u0004 (תהלים קו, ב)? \u0003למי נאה (ללמד) [למלל] גבורות ה'\u0004 — \u0003מי שיכול להשמיע כל תהלתו,\u0004 ומי שהוא יודע רק מקצת — אינו ראוי ללמד ברבים.","\u0003ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003ואיתימא\u0004 \u0005[ויש אומרים]\u0006 בשם \u0003רבה בר מרי,\u0004 ש\u0003אמר\u0004 פירוש אחר לפסוק: \u0003\"מי אהב בהמון לו תבואה\"\u0004 — \u0003כל האוהב למלמד בהמון,\u0004 את חכמי התורה המלמדים לרבים — \u0003לו תבואה —\u0004 יהיו לו פירות, בנים תלמידי חכמים. ומספרים: \u0003יהבו ביה רבנן עינייהו\u0004 \u0005[נתנו חכמים עיניהם],\u0006 כששמעו מאמר זה, \u0003ברבא בריה\u0004 \u0005[בנו של]\u0006 \u0003רבה\u0004 שהיה אוהב תלמידי חכמים מרביצי תורה, וזכה לבנים תלמידי חכמים. ומוסיפים להביא מה שדרשו חכמים בפסוק זה.","\u0003(סימן\u0004 לדברים האמורים בהמשך: \u0003אשי ללמוד, רבינא ללמד).\u0004","\u0003רב אשי אמר: כל האוהב ללמוד בהמון,\u0004 עם חברים רבים — \u0003לו תבואה,\u0004 הוא יצליח בלימודו. \u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר ר' יוסי בר' חנינא: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"חרב אל הבדים ונאלו\"\u0004 (ירמיה נ, לו) — \u0003חרב\u0004 ראויה לבוא \u0003על צוארי שונאיהם של תלמידי חכמים\u0004 (לשון נקיה, והכוונה לתלמידי חכמים) \u0003שיושבין ועוסקין בתורה בד בבד\u0004 (כל אחד בנפרד). והוא שנאמר \"חרב אל הבדים\" — לשון ריבוי של \"בד\". \u0003ולא עוד אלא שמטפשין\u0004 (נעשים טפשים) כשלומדים באופן זה, ומהיכן למדים דבר זה? \u0003כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"ונאלו\", וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 \u0003\"אשר נואלנו\"\u0004 (במדבר יב, יא), במשמעות — אשר נהגנו בטפשות. \u0003ולא עוד אלא שחוטאין\u0004 על ידי כך, \u0003שנאמר\u0004 בהמשך אותו כתוב \u0003\"ואשר חטאנו\". ואיבעית אימא מהכא\u0004 \u0005[ואם תרצה אמור מכאן]\u0006 ראיה מה פירוש \"נואלו\" — שנאמר \u0003\"נואלו שרי צען\"\u0004 (ישעיה יט, יג).","ואילו \u0003רבינא אמר\u0004 בפירושו של פסוק זה: \u0003כל האוהב ללמד בהמון\u0004 — \u0003לו תבואה.\u0004 שמתוך שהוא מלמד את הרבים תורתו משתבחת. \u0003והיינו\u0004 \u0005[וזהו]\u0006 ש\u0003אמר רבי: הרבה תורה למדתי מרבותי, ומחבירי יותר מהם, ומתלמידי יותר מכולן.\u0004","ועוד בשבח לימוד תורה \u0003אמר ר' יהושע בן לוי: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"עמדות היו רגלינו בשעריך ירושלם\"\u0004 (תהלים קכב, ב)? \u0003מי גרם לרגלינו שיעמדו במלחמה\u0004 ויצליחו בה — \u0003שערי ירושלם, שהיו עוסקים\u0004 בהם \u0003בתורה,\u0004 שמפרש \"בשעריך\" — בגלל שעריך, מקום המשפט והתורה.","\u0003ו\u0004עוד \u0003אמר ר' יהושע בן לוי: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"שיר המעלות לדוד שמחתי באמרים לי בית ה' נלך\"\u0004 (תהלים קכב, א)? \u0003אמר דוד לפני הקדוש ברוך הוא: רבונו של עולם, שמעתי בני אדם שהיו אומרים: מתי ימות זקן זה\u0004 (דוד), \u0003ויבא שלמה בנו\u0004 וימלוך \u0003ויבנה בית הבחירה ונעלה לרגל.\u0004 שהרי ידוע היה לכל שבימי דוד לא ייבנה המקדש, אלא רק בנו אחריו. \u0003ו\u0004אף ששמעתי דבר זה שלכאורה יש בו לצערני — \u0003שמחתי. אמר לו הקדוש ברוך הוא: \"כי טוב יום בחצריך מאלף\"\u0004 (תהלים פד, יא) — \u0003טוב לי יום אחד שאתה עוסק בתורה לפני, מאלף עולות שעתיד שלמה בנך להקריב לפני על גבי המזבח\u0004 (כפי שמפורש בספר מלכים א ג, ד).","נאמר במשנה \u0003ומכוונות להם\u0004 לערי המקלט \u0003דרכים. תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' אליעזר בן יעקב אומר: ל\u0004"],["\u0003\"מקלט\" היה כתוב על\u0004 שלט בכל \u0003פרשת דרכים\u0004 (צומת), לסימון הדרך הפונה לעיר המקלט, \u0003כדי שיכיר הרוצח\u0004 בשגגה את דרכו לעיר המקלט \u0003ויפנה לשם. אמר רב כהנא: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 המלמד זאת? \u0003\"תכין לך הדרך\"\u0004 (דברים יט, ג) לומר: \u0003עשה [לך] הכנה לדרך.\u0004","ומתוך שהוזכרה הלכה זו, מביאים: \u0003רב חמא בר חנינא\u0004 בדרשתו \u0003פתח לה פתחא להאי פרשתא מהכא\u0004 \u0005[פתיחה לפרשה זו\u0006 של דיני גלות \u0005מכאן]\u0006 מפסוק זה: \u0003\"טוב וישר ה' על כן יורה חטאים בדרך\"\u0004 (תהלים כה, ח), וכך אמר: \u0003אם לחטאים יורה\u0004 דרך, שהרי מעמידים שלטים בדרכים המורים להורגים היכן היא עיר המקלט — \u0003קל וחומר לצדיקים\u0004 שעוזר להם ה' ומורה להם דרך טובה.","\u0003ר' שמעון בן לקיש\u0004 בדרשתו \u0003פתח לה פתחא להאי פרשתא מהכא\u0004 \u0005[פתיחה לפרשה זו מכאן]:\u0006 נאמר במי שהרג בשגגה \u0003\"ואשר לא צדה\u0004 (התכוון) \u0003והאלהים אנה\u0004 (זימן) \u0003לידו\u0004 ושמתי לך מקום אשר ינוס שמה\" (שמות כא, יג). ויש לתמוה: מדוע יגרום ה' לאדם להכשילו במעשה כזה? תשובה לדבר מצויה בפסוק \u0003\"כאשר יאמר משל הקדמני מרשעים יצא רשע\"\u0004 (שמואל א כד, יג), שאין מעשה רע נעשה אלא על ידי מי שכבר יש בו חטא.","ולפי זה יש להבין את הפסוק \"והאלקים אנה לידו\", \u0003במה הכתוב מדבר\u0004 — \u0003בשני בני אדם שהרגו את הנפש, אחד הרג בשוגג ואחד הרג במזיד, לזה אין עדים\u0004 שהרג \u0003ולזה אין עדים\u0004 שהרג, ואין איש יודע מה שעשו, ולכן אינם נענשים זה בגלות וזה במיתה. \u0003הקדוש ברוך הוא מזמינן\u0004 מביאם לכך שיזדמנו שניהם \u0003לפונדק אחד, זה שהרג במזיד יושב תחת הסולם, וזה שהרג בשוגג יורד בסולם, ונפל עליו והרגו,\u0004 ובהזדמנות זו יש עדים בדבר, ונמצא \u0003זה שהרג במזיד\u0004 — \u0003נהרג\u0004 כראוי לו, \u0003וזה שהרג בשוגג\u0004 — \u0003גולה\u0004 כראוי לו.","ואגב העיסוק בדרך שה' מוליך בה את האדם, מביאים, \u0003אמר רבה בר רב הונא אמר רב הונא, ואמרי לה\u0004 \u0005[ויש האומרים אותה\u0006 אמרה\u0005]\u0006 ש\u0003אמר רב הונא אמר ר' אלעזר: מן התורה ומן הנביאים ומן הכתובים\u0004 אנו למדים ש\u0003בדרך שאדם רוצה לילך בה\u0004 — שם \u0003מוליכין אותו\u0004 ומסייעים לו.","\u0003מן התורה\u0004 אנו למדים דבר זה, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 שאמר ה' תחילה לבלעם: \u0003\"לא תלך עמהם\"\u0004 (במדבר כב, יד), עם שרי בלק, \u0003ו\u0004לאחר מכן כאשר הפציר, והוכיח בעצמו שהוא רוצה ללכת, \u0003כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"קום לך אתם\"\u0004 (במדבר כב, כ). \u0003מן הנביאים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אני ה' אלהיך מלמדך להועיל מדריכך בדרך (זו) תלך\"\u0004 (ישעיה מח, יז), כלומר, בדרך שהאדם בחר ללכת בה — שם ידריכוהו משמים. \u0003מן הכתובים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אם ללצים הוא יליץ ולענוים יתן חן\"\u0004 (משלי ג, לד), משמע שאם רוצה אדם ללכת בדרך ליצנות עוזרים לו משמים להיות לץ, ולרוצים להיות ענווים נותנים חן.","ושוב לענין ההלכה בדינו של הגולה, \u0003אמר רב הונא: רוצח שגלה לעיר מקלט, ומצאו גואל הדם\u0004 בדרכו לעיר המקלט, \u0003והרגו\u0004 — \u0003פטור\u0004 גואל הדם. ומעירים: \u0003קסבר\u0004 \u0005[סבור הוא]\u0006 רב הונא, שהכתוב \"פן ירדף גואל הדם אחרי הרוצח... והכהו נפש... \u0003ולו אין משפט מות\u0004 כי לא שונא הוא לו מתמול שלשום\" (דברים יט, ו) — \u0003בגואל הדם הוא דכתיב\u0004 \u0005[שנאמר],\u0006 שאין גואל הדם נענש אם הרג את הרוצח.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רב הונא, ממה ששנינו בברייתא: \u0003\"ולו אין משפט מות\"\u0004 — \u0003ברוצח הכתוב מדבר,\u0004 כלומר זה שרצח בשגגה אין עליו משפט מות, ולכן נצטוו ישראל לעשות ערי מקלט להצילו ממיתה. ודנה הברייתא ומוכיחה שאכן הדברים מוסבים על הרוצח: \u0003אתה אומר\u0004 שמדובר \u0003ברוצח, או אינו אלא בגואל הדם? כשהוא אומר\u0004 קודם לכן \u0003\"והוא לא שנא לו מתמול שלשום\"\u0004 (דברים יט, ד) ושם בוודאי מדובר על הרוצח — \u0003הוי אומר\u0004 שגם מי שמדובר עליו כאן בלשון זו \u0003ברוצח הכתוב מדבר.\u0004 ואם כן קשה על רב הונא מברייתא זו!","ומשיבים: רב הונא \u0003הוא דאמר כי האי תנא\u0004 \u0005[שאומר כ\u0006דעת \u0005תנא זה]\u0006 שיש לו שיטה אחרת משיטת ברייתא זו. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 אחרת: \u0003\"ולו אין משפט מות\"\u0004 — \u0003בגואל הדם הכתוב מדבר.\u0004 ויש לדון: \u0003אתה אומר בגואל הדם הכתוב מדבר, או אינו אלא ברוצח? כשהוא אומר \"כי לא שונא הוא לו מתמול שלשום\"\u0004 — \u0003הרי\u0004 שהכתוב על ה\u0003רוצח אמור, הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים \"ולו אין משפט מות\"\u0004 — \u0003בגואל הדם הכתוב מדבר.\u0004","ומנסים להביא ראיה ממשנתנו, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003מוסרין לו\u0004 להורג בשגגה הגולה לעיר מקלט \u0003שני תלמידי חכמים, שמא יהרגנו\u0004 גואל הדם \u0003בדרך, וידברו אליו.\u0004 ונברר: \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה \u0003דמתרו ביה\u0004 \u0005[שמתרים בו]\u0006 החכמים בגואל הדם, \u0003דאי קטיל\u0004 \u0005[שאם\u0006 הוא \u0005הורג]\u0006 את הרוצח בשגגה \u0003בר קטלא\u0004 \u0005[בן מוות]\u0006 \u0003הוא?\u0004 והרי זה שלא כדברי רב הונא הפוטר את גואל הדם שהרג את רוצח בשגגה.","ודוחים: \u0003לא,\u0004 אפשר להסביר \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003וידברו אליו דברים הראויים לו\u0004 לגואל הדם, \u0003אומרים לו: אל תנהג בו מנהג שופכי דמים, בשגגה בא מעשה לידו. ר' מאיר אומר: הוא מדבר על ידי עצמו, שנאמר \"וזה דבר הרצח\"\u0004 (דברים יט, ד) כלומר, הרוצח עצמו צריך להתנצל ולומר את הדברים. \u0003אמרו לו\u0004 חכמים לר' מאיר: \u0003הרבה שליחות עושה.\u0004 שיש דברים רבים שאדם עצמו קשה לו לעשותם, ואם הוא עושה אותם הם אינם מתקבלים, והם נעשים בדרך טובה יותר על ידי שליח. ודנים בלשון הברייתא.","\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003בשגגה בא מעשה לידו.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005],\u0006 \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003במזיד,\u0004 וכי \u0003בר\u0004 \u0005[בן]\u0006 \u0003גלות הוא?\u0004 ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 שפעמים שאף רוצח במזיד בורח לעיר מקלט, ומוסיפים:","\u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי בר' יהודה אומר: בתחלה,\u0004 כל הרוצחים \u0003אחד שוגג ואחד מזיד מקדימין\u0004 ובורחים \u0003לערי מקלט, ו\u0004לאחר מכן \u0003בית דין\u0004 שבמקומם \u0003שולחין ומביאין אותם משם.\u0004","ולאחר שביררו בית הדין את דינו, \u0003מי שנתחייב מיתה\u0004 — \u0003הרגוהו, שנאמר \"ושלחו זקני עירו ולקחו אתו משם ונתנו אתו ביד גאל הדם ומת\"\u0004 (שם יב). \u0003מי שלא נתחייב\u0004 כל עונש על מעשהו — \u0003פטרוהו, שנאמר: \"והצילו העדה את הרצח מיד גאל הדם\"\u0004 (במדבר לה, כה\u0003) מי שנתחייב גלות\u0004 — \u0003מחזירין אותו למקומו\u0004 לעיר המקלט, \u0003שנאמר \"והשיבו אתו העדה אל עיר מקלטו אשר נס שמה\"\u0004 (במדבר לה, כה).","\u0003רבי אומר:\u0004 אין התורה מצווה על ההורגים במזיד לברוח לערי מקלט, אלא התורה מתייחסת למצב הקיים, וההורגים במזיד \u0003מעצמן הן גולין, כסבורין הן\u0004 כי \u0003אחד שוגג ואחד מזיד\u0004 — \u0003קולטות\u0004 הערים הללו, \u0003והן אינן יודעין שבשוגג קולטות, במזיד אינן קולטות.\u0004","\u0003אמר ר' אלעזר: עיר\u0004 מקלט \u0003שרובה רוצחים\u0004 כלומר, שברחו אליה הרבה רוצחים בשגגה עד שנעשתה רובה רוצחים — שוב \u0003אינה קולטת, שנאמר\u0004 במי שהרג בשגגה וברח לעיר מקלט \u0003\"ודבר באזני זקני העיר ההיא את דבריו\"\u0004 (יהושע כ, ד), שיש לו דברים המיוחדים לו להגיד לזקני העיר, \u0003ולא שהושוו דבריהן לדבריו,\u0004 שאף הם אמרו דברים אלה בשעתם כאשר הם גלו לעיר המקלט בהיותם רוצחים בשגגה.","\u0003ו\u0004עוד \u0003אמר ר' אלעזר: עיר שאין בה זקנים\u0004 (חכמים) — \u0003אינה קולטת\u0004 רוצחים בשגגה, \u0003דבעינן\u0004 \u0005[שצריכים אנו]\u0006 שיתקיים הכתוב \"ודבר באזני \u0003זקני העיר\" וליכא\u0004 \u0005[ואין].\u0006 ובנקודה זו נחלקו חכמים, וכך \u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003עיר שאין בה זקנים, ר' אמי ור' אסי, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אומר: קולטת, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אומר: אינה קולטת.\u0004 ומסבירים: \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003אינה קולטת\u0004 — \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיהיו \u0003\"זקני העיר\", וליכא\u0004 \u0005[ואין\u0006 כאן\u0005].\u0006 \u0003למאן דאמר\u0004 \u0005[\u0006ו\u0005ל\u0006דעת \u0005מי שאומר]\u0006 \u0003קולטת\u0004 — תנאי זה הוא \u0003מצוה בעלמא\u0004 \u0005[בלבד],\u0006 לכתחילה, אבל למעשה — גם בלא זקנים יש לה דין עיר מקלט.","\u0003ו\u0004עוד נחלקו בענין זה בנושאים אחרים: \u0003עיר שאין בה זקנים, ר' אמי ור' אסי, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: נעשה בה בן סורר ומורה, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אין נעשה בה בן סורר ומורה.\u0004 ומסבירים את טעמיהם: \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003אין נעשה בה בן סורר ומורה\u0004 — \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיתקיים הכתוב \"ותפשו בו אביו ואמו והוציאו אותו אל \u0003זקני עירו\u0004 ואל שער מקומו\" (דברים כא, יט), \u0003וליכא\u0004 \u0005[ואין\u0006 כאן\u0005].\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003נעשה בן סורר ומורה\u0004 — \"זקני עירו\" הוא \u0003מצוה בעלמא\u0004 \u0005[בלבד],\u0006 לכתחילה.","\u0003ו\u0004עוד נחלקו ב\u0003עיר שאין בה זקנים, ר' אמי ור' אסי, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: מביאה עגלה ערופה\u0004 אם נמצא אדם הרוג ליד העיר הזו, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: אינה מביאה עגלה ערופה.\u0004 וגם כאן דומים טעמיהם: \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003אינה מביאה עגלה ערופה\u0004 — \u0003בעינן\u0004 \u0005[צריכים אנו]\u0006 שיתקיים \"והורידו \u0003זקני העיר ההיא\u0004 את העגלה\" (שם כא, ד), \u0003וליכא\u0004 \u0005[ואין\u0006 כאן\u0005].\u0006 \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003מביאה עגלה ערופה\u0004 — \"זקני העיר ההיא\" הוא \u0003מצוה בעלמא\u0004 \u0005[בלבד].\u0006","\u0003אמר ר' חמא בר חנינא: מפני מה נאמרה פרשת רוצחים\u0004"],["\u0003בלשון עזה, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"וידבר ה' אל יהושע לאמר דבר אל בני ישראל לאמר תנו לכם את ערי המקלט אשר דברתי אליכם\u0004 ביד משה\" (יהושע כ, א— ב)? מדוע נאמר \"וידבר ה'\", שהוא בלשון קשה, ולא נאמר \"ויאמר\", כמו בשאר המקומות שמוזכרים דברי ה' ליהושע? \u0003מפני ש\u0004ערי המקלט \u0003הן\u0004 מצוה \u0003של התורה,\u0004 ולכן יש להן תוקף מיוחד.","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 ש\u0003כל\u0004 לשון \u0003דיבור, לשון קשה\u0004 היא? ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003כדכתיב\u0004 \u0005[כמו שנאמר]\u0006 באחי יוסף \u0003\"דבר האיש אדני הארץ אתנו קשות\"\u0004 (בראשית מב, ל). ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 על הפסוק \"אז \u0003נדברו\u0004 יראי ה'\" (מלאכי ג, טז), \u0003אין \"נדברו\" אלא לשון נחת, וכן הוא אומר \"ידבר עמים תחתינו\"\u0004 (תהלים מז, ד) שמתפרש: ינהל בשקט ובנחת עמים תחתינו! ומשיבים: אין זו קושיה, \u0003\"דבר\" לחוד, \"ידבר\" לחוד,\u0004 שיש להבחין בין צורות שונות של אותו שורש עצמו.","(וסימן לדברים הבאים \u0003סימנ\"י רבנ\"ן מהמנ\"י וספר\"י).\u0004","ושבים לשאלה מדוע נאמרה פרשת רוצחים ליהושע בלשון קשה, ואומרים, \u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003ר' יהודה ורבנן, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אומר: מפני ששיהם\u0004 ששיהה אותם, את ערי המקלט, ולא קיים את המצוה מיד. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אומר: מפני שהן של תורה,\u0004 ולכן היה צורך לומר זאת בלשון עזה, לקיים את מצות התורה הזאת. ומביאים מחלוקת נוספת הקשורה לפרשת ערי המקלט שביהושע.","נאמר \u0003\"ויכתב יהושע את הדברים האלה בספר תורת אלהים\"\u0004 (יהושע כד, כו), \u0003פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 \u0003ר' יהודה ור' נחמיה\u0004 באלו דברים מדובר, \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אומר:\u0004 הכוונה היא ל\u0003שמנה פסוקים\u0004 אחרונים בתורה, שבהם מדובר על מות משה, והם הדברים שכתב והוסיף יהושע בספר תורת אלקים (ספר התורה) על הדברים שכתבם משה. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אומר:\u0004 זו פרשת \u0003ערי מקלט\u0004 הכתובה בספר יהושע (פרק כ).","ודנים: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006דעת \u0005מי שאומר],\u0006 שהכוונה היא ל\u0003שמונה פסוקים\u0004 שבתורה — \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \"ויכתוב... \u0003בספר תורת אלהים\",\u0004 שנכתבו הדברים בספר התורה עצמו. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהכוונה היא לפרשת \u0003ערי מקלט\u0004 שבספר יהושע \u0003מאי\u0004 \u0005[מה\u0006 משמע\u0005]\u0006 \"\u0003בספר תורת אלהים\u0004\"? והרי לא נכתבו דברים אלה בתורה! ומשיבים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך צריך להבין את הדברים: \u0003ויכתוב יהושע בספרו את הדברים האלה הכתובים בספר תורת אלהים.\u0004 אגב מחלוקות אלו מזכירים עוד מחלוקת בין ר' יהודה וחכם אחר, שלא נתפרש בה מה אמר כל אחד.","\u0003ספר\u0004 תורה \u0003שתפרו\u0004 את יריעות הקלף שלו \u0003בפשתן, פליגי בה\u0004 \u0005[נחלקו בכך]\u0006 בדינו של ספר זה \u0003ר' יהודה ור' מאיר, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אומר: כשר, וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אומר: פסול.\u0004","ומסבירים את דעותיהם: \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003פסול,\u0004 טעם הדבר הוא — \u0003דכתיב\u0004 \u0005[\u0006משום \u0005שנאמר]\u0006 \"והיה לך לאות על ידך ולזכרון בין עיניך... \u0003למען תהיה תורת ה' בפיך\"\u0004 (שמות יג, ט), \u0003ואיתקש\u0004 \u0005[והוקשה,\u0006 הושוותה\u0005]\u0006 \u0003כל התורה כולה\u0004 בפסוק זה \u0003לתפילין,\u0004 שנזכרים קודם בפסוק זה: \u0003מה תפילין הלכה למשה מסיני לתופרן בגידין\u0004 — \u0003אף כל\u0004 היריעות של ספר תורת ה' צריך \u0003לתפרן בגידין\u0004 הלקוחים מבהמה. \u0003ואידך\u0004 \u0005[והאחר]\u0006 סבור: \u0003כי איתקש\u0004 \u0005[כאשר הוקשה\u0006 הושוותה\u0005]\u0006 התורה לתפילין הרי זה דווקא לענין \u0003למותר בפיך,\u0004 שאין עושים יריעות ספר תורה אלא ממין בהמה שמותר באכילה לישראל, אבל \u0003ל\u0004פרטי \u0003הלכותיו לא איתקש\u0004 \u0005[הושוותה].\u0006","\u0003אמר רב: חזינן להו\u0004 \u0005[ראיתי אותן]\u0006 \u0003לתפילין דבי חביבי\u0004 \u0005[של בית דודי,\u0006 ר' חייא\u0005]\u0006 \u0003דתפירי בכיתנא\u0004 \u0005[ש\u0006הם \u0005תפורים בפשתן],\u0006 \u0003ולית הלכתא כוותיה\u0004 \u0005[ואין הלכה כמותו]\u0006 אלא תפירתן צריכה להיות דווקא בגידים.","נאמר בתורה כי הרוצח בשגגה יושב בעיר המקלט עד מות הכהן הגדול. ואמרו על כך: \u0003אחד\u0004 כהן גדול \u0003משוח בשמן המשחה\u0004 כדרך שהיו הכהנים הגדולים נמשחים לכהונה בזמן בית ראשון, \u0003ואחד\u0004 כהן גדול \u0003המרובה בבגדים\u0004 בלבד, כדרך שהיה בבית השני, שהלבישום שמונה בגדי כהונה גדולה, אבל לא נמשחו בשמן המשחה, \u0003ואחד\u0004 כהן גדול \u0003שעבר ממשיחותו\u0004 כגון שנמצא פסול בכהן גדול ומינו את זה תחתיו, ולאחר שחזר הכהן הראשון לכשרותו, העבירו את זה מן הכהונה הגדולה — כולם במותם \u0003מחזירין את הרוצח\u0004 מעיר מקלטו. \u0003ר' יהודה אומר: אף\u0004 כהן \u0003משוח מלחמה\u0004 שנמשח כדי לצאת בראש הצבא למלחמה, \u0003מחזיר\u0004 במותו \u0003את הרוצח.\u0004","\u0003לפיכך אימותיהן של כהנים\u0004 גדולים \u0003מספקות להן\u0004 לגולים לערי המקלט \u0003מחיה וכסות, כדי שלא יתפללו על בניהם שימותו,\u0004 שאם יהיו חייהם קשים שם — יתפללו שימותו הכהנים הגדולים, ויוכלו לצאת משם.","על האמור במשנה, שכל הכהנים הללו במותם מחזירים את הרוצח מעיר המקלט, שואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר רב כהנא:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"וישב בה עד מות הכהן הגדל\u0004 אשר משח אותו בשמן הקדש\" (במדבר לה, כה), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 גם \u0003\"כי בעיר מקלטו ישב עד מות הכהן הגדל\"\u0004 (במדבר לה, כח), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 עוד \u0003\"ואחרי מות הכהן הגדל\"\u0004 (במדבר לה, כח), הרי נזכר שלוש פעמים \"כהן גדול\" כנגד שלושה מיני כהנים גדולים שנמנו במשנה לדעת התנא הראשון: משוח בשמן המשחה, מרובה בגדים, וכהן שעבר ממשיחותו.","\u0003ור' יהודה\u0004 סבור: \u0003כתיב קרא אחרינא\u0004 \u0005[נאמר\u0006 עוד \u0005כתוב אחר]\u0006 \u0003\"לשוב לשבת בארץ עד מות הכהן\"\u0004 (במדבר לה, לב) הרי שנזכר כהן נוסף, והוא משוח המלחמה. \u0003ואידך\u0004 \u0005[ו\u0006התנא \u0005האחר]\u0006 סבור: \u0003מ\u0004כיון ש\u0003לא כתיב\u0004 \u0005[נאמר]\u0006 באותו פסוק \u0003\"הגדול\"\u0004 — אין זה רמז לכהן נוסף אלא \u0003חד מהנך\u0004 \u0005[אחד מאלה]\u0006 \u0003הוא\u0004 שהוזכרו קודם לכן, ואין כאן אלא חזרה על אותם דברים.","נאמר במשנה: \u0003לפיכך אימותיהן של כהנים\u0004 היו מספקות מחיה וכסות לגולים, כדי שלא יתפללו על בניהן שימותו. ותוהים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום ש\u0003לא מצלו\u0004 \u0005[יתפללו],\u0006 \u0003הא מצלו\u0004 — \u0003מייתי\u0004 \u0005[הרי אם יתפללו\u0006 שימותו — הם אכן \u0005ימותו]?\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"כצפור לנוד כדרור לעוף כן קללת חנם לא תבא\"\u0004 (משלי כו, ב), והרי קללת חינם היא זו, ומדוע יחששו לה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ההוא סבא\u0004 \u0005[זקן אחד]:\u0006 \u0003מפירקיה\u0004 \u0005[מדרשתו]\u0006 של \u0003רבא שמיע לי\u0004 \u0005[שמעתי]\u0006 שאין זו קללת חנם, כיון שהכהנים הגדולים יש להם מקצת אשמה במעשה הרציחה שעשו אלה, \u0003ש\u0004כן \u0003היה להן לבקש רחמים על דורן\u0004 שלא תארע תקלה של רצח, ואף לא בשגגה, \u0003ולא בקשו.\u0004 וכיון שיש בהם קצת אשמה יכולה התפילה שימותו להזיק להם.","\u0003ואיכא דמתני\u0004 \u0005[יש ששונים]\u0006 את המשנה בגירסה שונה במקצת: לפיכך אימותיהן של כהנים מספקות להם מחיה וכסות — \u0003כדי שיתפללו על בניהם שלא ימותו.\u0004 ונדייק: \u0003טעמא דמצלו\u0004 \u0005[הטעם,\u0006 דווקא, משום \u0005שמתפללים]\u0006 לא ימותו, \u0003הא לא מצלו\u0004 — \u0003מייתי\u0004 \u0005[הרי\u0006 אם \u0005לא יתפללו\u0006 — \u0005ימותו]?\u0006 \u0003מאי הוה ליה למעבד\u0004 \u0005[מה היה לו\u0006 לכהן הגדול \u0005לעשות]\u0006 כדי למנוע את הדבר? \u0003הכא אמרינן\u0004 \u0005[כאן,\u0006 בבבל \u0005אומרים אנו]\u0006 פתגם זה: \u0003טוביה חטא וזיגוד מנגיד\u0004 \u0005[לוקה\u0006]. שאדם בשם טוביה חטא חטא מסויים, ואדם בשם זיגוד בא לבדו להעיד עליו. וכיון שאין מקבלים עדות כזו, והוא כמוציא שם רע בלבד — הלקוהו משום הוצאת שם רע. ונמצא שהחוטא יצא בלא עונש, ודווקא זה שבא להעיד על כך לקה. ומכאן נעשה הדבר לפתגם מקובל לאדם שלוקה בעוון חבירו.","\u0003התם אמרי\u0004 \u0005[שם\u0006 בארץ ישראל היו \u0005אומרים]\u0006 פתגם אחר על אותו ענין: \u0003שכם נסיב\u0004 \u0005[נושא\u0006 אשה\u0005]\u0006 \u0003ומבגאי גזיר\u0004 \u0005[מל]\u0006 את עצמו. שלקחו לדוגמה מה שאירע בעיר שכם, כאשר שכם רצה לשאת את דינה וגרם לכל בני העיר שימולו. שנמצא ששכם הוא הנושא את האשה ונהנה, ואילו כל מי שנמצא שם צריך היה לסבול ולמול את עצמו.","\u0003אמר ליה ההוא סבא\u0004 \u0005[לו זקן אחד]:\u0006 \u0003מפירקיה\u0004 \u0005[מדרשתו]\u0006 של \u0003רבא שמיע לי\u0004 \u0005[שמעתי]\u0006 מדוע ראויים הכהנים הגדולים לעונש — \u0003שהיה להן לבקש רחמים על דורן\u0004 שלא תארע תקלה של רצח בשגגה, \u0003ולא בקשו,\u0004 ולכן היו צריכים תפילה של הגולים עצמם בעדם. ומביאים ראיה נוספת לרעיון זה, \u0003כי הא דההוא גברא דאכליה אריא ברחוק תלתא פרסי מיניה\u0004 \u0005[כמו\u0006 מעשה זה \u0005שאדם אחד שאכל אותו אריה במרחק שלש פרסות ממנו]\u0006 ממקומו של \u0003ר' יהושע בן לוי, ולא אישתעי\u0004 \u0005[שוחח]\u0006 \u0003אליהו\u0004 הנביא \u0003בהדיה תלתא יומי\u0004 \u0005[אתו שלושה ימים],\u0006 שהקפיד עליו על אדם שנהרג בסביבתו, משום שלא התפלל שלא יארע דבר כגון זה במקומו. מכיון שדיברנו בעניני קללות והתגשמותן, מביאים עוד.","\u0003אמר רב יהודה אמר רב: קללת חכם\u0004 — \u0003אפילו בחנם,\u0004 כאשר מתברר שלא היתה סיבה לקללה זו — מכל מקום \u0003היא באה\u0004 על המקולל. \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 זאת? \u0003מ\u0004מה שאירע ב\u0003אחיתופל, שבשעה שכרה דוד שיתין\u0004 את היסודות העמוקים הנמצאים מתחת למזבח שבבית המקדש, \u0003קפא תהומא בעא למישטפא לעלמא\u0004 \u0005[צף\u0006 ועלה \u0005התהום וביקש לשטוף את העולם].\u0006 \u0003אמר\u0004 דוד: \u0003מהו,\u0004 האם מותר \u0003לכתוב שם\u0004 קדוש \u0003אחספא\u0004 \u0005[על חרס]\u0006 \u0003ומישדא בתהומא דליקו אדוכתיה\u0004 \u0005[ולזרוק אותו בתהום\u0006 כדי \u0005שיעמוד\u0006 התהום \u0005במקומו]?\u0006 והשאלה היתה האם אין בכך משום בזיון השם שמשתמשים בו בדבר זה, ושהוא עלול להימחק בכך. \u0003ליכא דאמר ליה מידי\u0004 \u0005[לא היה מי שאמר\u0006 שהשיב \u0005לו דבר].\u0006 \u0003אמר\u0004 דוד: \u0003כל היודע דבר זה ואינו אומרו\u0004 — יהיה עונשו ש\u0003יחנק בגרונו.\u0004","\u0003נשא אחיתופל קל וחומר בעצמו, אמר: ומה\u0004 על מנת \u0003לעשות שלום בין איש לאשתו,\u0004 כשחושד האיש באשתו שהיא סוטה, ומביאה לשתות מי סוטה, \u0003אמרה התורה: שמי שנכתב בקדושה ימחה על המים,\u0004 שהרי מוחקים במים אלה מן המגילה שכתוב בה כמה פעמים שם ה', ומשקים איתם את האשה, כדי לעשות שלום בין בני הזוג. לצורך דבר כזה של תהום העלול לשטוף את כל העולם, שהוא שלום והצלה \u0003לכל העולם כולו לא כל שכן\u0004 שמותר להשתמש בשם, גם אם הוא עלול להימחק במים? \u0003אמר ליה\u0004 \u0005[לו]\u0006 אחיתופל לדוד: \u0003שרי\u0004 \u0005[מותר]\u0006 הדבר. ועל סמך זה \u0003כתב\u0004 דוד \u0003שם אחספא\u0004 \u0005[על חרס],\u0006 \u0003שדי אתהומא, נחת וקם אדוכתיה\u0004 \u0005[זרק על התהום,\u0006 ו\u0005ירד\u0006 התהום \u0005ועמד במקומו].\u0006","\u0003ואפילו הכי כתיב\u0004 \u0005[ואפילו כך נאמר]\u0006 בזמן מרד אבשלום \u0003\"ואחיתפל ראה כי לא נעשתה עצתו ויחבש את החמור ויקם וילך אל ביתו אל עירו ויצו אל ביתו ויחנק\"\u0004 (שמואל ב יז, כג). הרי שאף שלא היה מקום לקללה זו שקילל דוד לחול, שהרי השיב לו אחיתופל מה ששאל, מכל מקום כיון שיצא דבר קללה עליו מפי דוד — נתקיימה בו הקללה.","ועוד בענין זה \u0003אמר ר' אבהו: קללת חכם\u0004 — \u0003אפילו\u0004 נאמרה \u0003על תנאי היא באה\u0004 (מתקיימת). \u0003מנלן\u0004 \u0005[מנין לנו]?\u0006 \u0003מעלי\u0004 הכהן הגדול, \u0003דקאמר ליה\u0004 \u0005[שאמר לו]\u0006 \u0003[עלי] לשמואל\u0004 כשהיה לו חזון נבואה על עלי שבניו לא הלכו בדרכיו: \u0003\"כה יעשה לך אלהים וכה יוסיף אם תכחד ממני דבר\"\u0004 (שמואל א ג, יז). \u0003ואף על גב דכתיב\u0004 \u0005[ואף על פי שנאמר]\u0006 מיד אחר כך \u0003\"ויגד לו שמואל את כל הדברים ולא כחד ממנו\"\u0004 (שמואל א ג, יח) — \u0003[ואפילו הכי] כתיב\u0004 \u0005[כך נאמר]\u0006 מאוחר יותר לעת זקנת שמואל \u0003\"ולא הלכו בניו בדרכיו\"\u0004 (שמואל א ח, ג) כלומר, שכה עשה לו אלקים כמו שעשה לעלי, שבניו לא הלכו בדרכיו. הרי שאף שעלי קיללו על תנאי אם לא יגלה לו, ואילו שמואל גילה לו, ולא התקיים התנאי — מכל מקום פגעה הקללה בשמואל."],["ובענין דומה של דבר שקיים אף שמעיקרו נעשה על תנאי, \u0003אמר רב יהודה אמר רב: נידוי,\u0004 גם אם נעשה \u0003על תנאי\u0004 — \u0003צריך הפרה,\u0004 ולמרות שמתקיים התנאי. \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 כן? \u0003מיהודה, דכתיב\u0004 \u0005[שנאמר]\u0006 כאשר ביקש מיעקב אביו לקחת אתו את בנימין למצרים: \u0003\"אם לא הביאתיו אליך...\u0004 וחטאתי לך כל הימים\" (בראשית מג, ט), כלומר אהיה כל הזמן בנידוי, כחוטא. \u0003ואמר ר' שמואל בר נחמני אמר ר' יונתן: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 בברכת משה לשבטים: \u0003\"יחי ראובן ואל ימת\"\u0004 (דברים לג, ו) וסמוך לו \u0003\"וזאת ליהודה\"\u0004 (דברים לג, ז)? מדוע נקשרה ברכת יהודה לברכת ראובן?","\u0003כל אותן ארבעים שנה שהיו ישראל במדבר, עצמותיו של יהודה היו מגולגלין בארון\u0004 כשהן נפרדות זו מזו, מפני נידוי זה שנידה עצמו ולא הותר לו, \u0003עד שעמד משה ובקש עליו רחמים\u0004 מה' \u0003אמר לפניו: רבונו של עולם, מי גרם לראובן שיודה\u0004 על חטאו בבלהה — \u0003יהודה,\u0004 שכיון שהודה יהודה על חטאו בתמר — שמע ראובן והודה אף הוא, ולכן \u0003\"וזאת ליהודה... שמע ה' קול יהודה\"\u0004 (דברים לג, ז).","מסופר, \u0003עאל איבריה לשפא\u0004 \u0005[נכנסו איבריו למקומם]\u0006 ולא היו מגולגלים יותר, אך עדיין \u0003לא הוה קא מעיילי ליה למתיבתא דרקיע\u0004 \u0005[היו מכניסים אותו לישיבה של מעלה]\u0006 ולכן הוסיף משה וביקש עליו \u0003\"ואל עמו תביאנו\"\u0004 (דברים לג, ז), שיהא עם שאר הצדיקים. ועדיין \u0003לא הוה קא ידע למישקל ומיטרח בשמעתא בהדי רבנן\u0004 \u0005[היה יודע לשאת ולתת בהלכה יחד עם חכמים]\u0006 בישיבה של מעלה, על כן הוסיף וביקש משה \u0003\"ידיו רב לו\"\u0004 (דברים לג, ז). ועדיין \u0003לא הוה ידע לפרוקי קושיא\u0004 \u0005[היה יודע לתרץ קושיות]\u0006 שהקשו עליו, ועל כך התפלל משה \u0003\"ועזר מצריו תהיה\"\u0004 (דברים לג, ז).","שנינו במשנה מי נחשבים ככהנים גדולים שבמותם יוצא הרוצח מעיר המקלט. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 מה כוונת המשנה? האם דווקא \u0003במיתת כולן הוא חוזר,\u0004 ואינו חוזר במיתת אחד מהם, \u0003או דלמא\u0004 \u0005[שמא]\u0006 די \u0003במיתת אחד מהן\u0004 כדי שיחזור?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנה הבאה: \u0003נגמר דינו\u0004 של רוצח \u0003בלא\u0004 שיהא באותה שעה \u0003כהן גדול\u0004 — \u0003אינו יוצא משם לעולם; ואם איתא\u0004 \u0005[יש]\u0006 מקום לומר שיוצא אף במותו של אחד מאלה — \u0003ליהדר ביה בדהנך\u0004 \u0005[שיחזור ב\u0006גלל אחד \u0005מאלה]\u0006 האחרים, מרובה בגדים או כהן שעבר! ומשיבים: מדובר \u0003בדליכא\u0004 \u0005[כשאין]\u0006 שם אחרים, אלא רק כהן גדול אחד.","אם \u0003משנגמר דינו\u0004 של הרוצח לגלות \u0003מת כהן גדול\u0004 — \u0003הרי זה אינו גולה,\u0004 שמיתת הכהן הגדול פטרה אותו. \u0003אם עד שלא נגמר דינו מת כהן גדול, ומנו אחר תחתיו, ולאחר מכן נגמר דינו\u0004 — \u0003חוזר במיתתו של\u0004 כהן גדול \u0003שני.\u0004 ואולם אם \u0003נגמר דינו בלא כהן גדול\u0004 כלל, שלא היה כהן גדול בזמן גמר הדין, \u0003ו\u0004כן \u0003ההורג כהן גדול\u0004 בשגגה, \u0003ו\u0004כן \u0003כהן גדול שהרג\u0004 בשגגה — \u0003אינו יוצא משם לעולם.\u0004","\u0003ו\u0004הגולה \u0003אינו יוצא\u0004 מן העיר כלל, \u0003לא לעדות\u0004 בענין \u0003מצוה, ולא לעדות\u0004 בענין \u0003ממון, ולא לעדות\u0004 בענין דיני \u0003נפשות. ואפילו\u0004 הוא אדם ש\u0003ישראל צריכים לו, ואפילו\u0004 הוא \u0003שר צבא ישראל כיואב בן צרויה —\u0004 \u0003אינו יוצא משם לעולם, שנאמר \"אשר נס שמה\"\u0004 (במדבר לה, כה), לומר: \u0003שם תהא דירתו, שם תהא מיתתו, שם תהא קבורתו.\u0004","ועוד הלכה: \u0003כשם שהעיר קולטת\u0004 — \u0003כך תחומה קולט. רוצח שיצא חוץ לתחום\u0004 עיר המקלט \u0003ומצאו\u0004 שם \u0003גואל הדם, ר' יוסי הגלילי אומר: מצוה ביד גואל הדם\u0004 להורגו, \u0003ורשות ביד כל אדם\u0004 לעשות זאת. \u0003ר' עקיבא אומר: רשות ביד גואל הדם, וכל אדם חייבין עליו\u0004 אם הרגוהו.","שנינו במשנה שאם משנגמר דינו מת כהן גדול — הרי זה אינו גולה. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אמר אביי: קל וחומר\u0004 הוא, \u0003ומה מי שגלה כבר\u0004 — \u0003יצא עכשיו\u0004 במותו של כהן גדול זה, \u0003מי שלא גלה\u0004 עדיין — \u0003אינו דין שלא יגלה?\u0004 ודוחים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 נאמר אחרת: \u0003האי\u0004 \u0005[זה]\u0006 ש\u0003גלה\u0004 כבר — \u0003איכפר ליה\u0004 \u0005[נתכפר לו]\u0006 עוונו על ידי הגלות, ולכן הוא יוצא במות הכהן הגדול, \u0003האי\u0004 \u0005[זה]\u0006 ש\u0003לא גלה\u0004 עדיין — \u0003לא\u0004 נתכפר לו, ולכן לא יוצא במות הכהן! ודוחים: \u0003מידי\u0004 \u0005[כלום]\u0006 \u0003גלות קא מכפרא\u0004 \u0005[מכפרת]\u0006 כדי לפוטרו? \u0003מיתת כהן הוא דמכפרא\u0004 \u0005[שמכפרת],\u0006 והרי מת הכהן!","שנינו, ש\u0003אם עד שלא נגמר דינו\u0004 מת הכהן הגדול ונתמנה כהן גדול אחר, ואחר כך נגמר דינו — הרי הוא יוצא במותו של הכהן הגדול השני. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]?\u0006 \u0003אמר רב כהנא:\u0004 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"וישב בה עד מות הכהן הגדל אשר משח אתו בשמן הקדש\"\u0004 (במדבר לה, ה), \u0003וכי הוא\u0004 הרוצח \u0003מושחו\u0004 את הכהן? \u0003אלא\u0004 הכוונה היא: \u0003זה\u0004 כהן גדול \u0003שנמשח בימיו\u0004 של אותו רוצח, מזמן שנעשה זה רוצח בשגגה.","ושואלים: ומדוע תולים את הדברים במותו של כהן זה? והרי לעיל אמרנו שיש שייכות לכהן הגדול במוות שבשגגה, משום שהיה לו להתפלל שלא יארע דבר כזה. אולם כאן, כאשר כהן גדול זה לא היה עדיין כהן גדול בשעת ההריגה, \u0003מאי הוה ליה למעבד\u0004 \u0005[מה היה לו לעשות]?\u0006 ומשיבים: \u0003היה לו לבקש רחמים\u0004 (להתפלל) על אותו רוצח בשגגה \u0003שיגמור דינו\u0004 בבית הדין \u0003לזכות\u0004 ולא יידון לגלות, \u0003ולא ביקש.\u0004","\u0003אמר אביי: נקטינן\u0004 \u0005[מוחזקים אנו]\u0006 בהלכה זו: הרוצח בשגגה ש\u0003נגמר דינו\u0004 לגלות, \u0003ומת\u0004 לפני שגלה — \u0003מוליכין את עצמותיו לשם,\u0004 לעיר המקלט, ושם הוא נקבר, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"לשוב לשבת בארץ עד מות הכהן\"\u0004 (במדבר לה, לב), \u0003ואיזהו ישיבה שהיא בארץ\u0004 בתוך הארץ עצמה — \u0003הוי אומר זו קבורה. תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003מת\u0004 הרוצח בשגגה בעיר המקלט, \u0003קודם שמת כהן גדול,\u0004 הרי לאחר מות הכהן \u0003מוליכין עצמותיו על קברי אבותיו, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ישוב הרצח אל ארץ אחזתו\"\u0004 (במדבר לה, כח) \u0003איזהו ישיבה שהיא ב\u0004תוך \u0003ארץ אחוזתו\u0004 — \u0003הוי אומר זו קבורה.\u0004","ומעלים שאלה אחרת: אם \u0003נגמר דינו\u0004 של ההורג לגלות, \u0003ונעשה כהן\u0004 גדול שהיה בימיו \u0003בן גרושה או בן חלוצה,\u0004 שבאו עדים והעידו שכהן גדול זה הוא כהן פסול, \u0003פליגי בה\u0004 \u0005[נחלקו בכך],\u0006 בשאלה האם רוצח בשגגה יוצא על ידי כך מעיר המקלט, \u0003ר' אמי ור' יצחק נפחא. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אומר: מתה כהונה\u0004 כלומר, אנו דנים זאת כאילו מת הכהן הגדול, ולכן הגולים שבים למקומם. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אומר: בטלה כהונה\u0004 — הרי זה כאילו לא היה אז כהן גדול, ואינם יוצאים מעיר המקלט לעולם.","ושואלים: \u0003לימא בפלוגתא\u0004 \u0005[האם נאמר\u0006 כי \u0005במחלוקת\u0006 של\u0005]\u0006 \u0003ר' אליעזר ור' יהושע קא מיפלגי\u0004 \u0005[חלוקים הם]\u0006 ר' אמי ור' יצחק נפחא. \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003היה\u0004 כהן \u0003עומד\u0004 בבית המקדש \u0003ומקריב על גבי המזבח, ונודע שהוא בן גרושה או בן חלוצה,\u0004 והריהו איפוא כהן פסול לעבודה, \u0003ר' אליעזר אומר: כל קרבנות שהקריב\u0004 הריהם \u0003פסולין\u0004 — שהרי התברר שאינו כהן כשר, \u0003ור' יהושע מכשיר\u0004 את הקרבנות שכבר הקריב.","ומעתה האם נאמר כי \u0003מאן דאמר\u0004 \u0005[מי שאומר\u0006 כאן\u0005]\u0006 \u0003מתה\u0004 כהונה — הוא סבור \u0003כר' יהושע,\u0004 ולכן הוא אומר שהכהן הגדול שנודע שהוא פסול הריהו נפסל מכאן ולהבא, והרי זה כאילו מת, אבל כהונתו לא בטלה מעיקרה. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003בטלה\u0004 כהונה, סבור \u0003כר' אליעזר,\u0004 ומשום כך הוא סבור שהכהונה מופקעת מתחילתה, ונמצא שבזמן שנגמר דינו לא היה כלל כהן גדול?"],["\u0003אליבא\u0004 \u0005[על פי\u0006 שיטתו\u0005]\u0006 של \u0003ר' אליעזר כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים],\u0006 שלדעתו ודאי בטלה כהונה, \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003אליבא\u0004 \u0005[על פי\u0006 שיטתו\u0005]\u0006 של \u0003ר' יהושע,\u0004 ובאופן זה: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 \u0003מתה\u0004 כהונה הרי הוא סבור \u0003כר' יהושע\u0004 בפשטות, \u0003ו\u0004אולם גם \u0003מאן דאמר\u0004 \u0005[ומי שאומר]\u0006 \u0003בטלה\u0004 כהונה יכול לסבור כמותו, ולומר כי \u0003עד כאן לא\u0004 שמענו ש\u0003קאמר\u0004 \u0005[\u0006ש\u0005אומר]\u0006 \u0003ר' יהושע התם\u0004 \u0005[שם]\u0006 אלא בענין עבודתו של הכהן בבית המקדש, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בה \u0003\"ברך ה' חילו ופעל ידיו תרצה\"\u0004 (דברים לג, יא) ודרשו: \"חילו\" — \u0003אפילו חללין שבו,\u0004 שבדיעבד גם פועל ידיהם של חללים בהקרבת הקרבן עולה לרצון וכשר (\"ופועל ידיו תרצה\"), \u0003אבל הכא\u0004 \u0005[כאן]\u0006 לעצם מעמדו של הכהן \u0005—\u0006 \u0003אפילו ר' יהושע מודה\u0004 שבטלה כהונה.","שנינו במשנה כי מי ש\u0003נגמר דינו\u0004 לגלות אינו יוצא כלל מעיר המקלט, ואפילו כל ישראל צריכים לו, ואפילו היה שר צבא ישראל כיואב בן צרויה. ואגב כך מביאים דברים שנאמרו לגבי יואב בענין זה. \u0003אמר רב יהודה אמר רב: שתי טעיות טעה יואב באותה שעה\u0004 שברח מפני שלמה, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"וינס יואב אל אהל ה' ויחזק בקרנות המזבח\"\u0004 (מלכים א ב, כח),","\u0003טעה\u0004 — \u0003שאינו קולט\u0004 במזבח \u0003אלא גגו, והוא תפס בקרנותיו\u0004 של המזבח. \u0003טעה\u0004 טעות שניה — \u0003שאינו קולט אלא מזבח בית עולמים, והוא תפס מזבח של שילה. אביי אומר: בהא נמי מיטעא טעה\u0004 \u0005[בזה גם כן טעה]\u0006 — \u0003שאינו קולט אלא כהן ועבודה בידו, והוא זר היה.\u0004","בהמשך לדבר זה מביאים מה ש\u0003אמר ריש לקיש: שלש טעיות עתיד\u0004 המלאך \u0003שרו של רומי לטעות, דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"מי זה בא מאדם חמוץ בגדים מבצרה\"\u0004 (ישעיהו סג, א) שמדבר בדרך משל על בואו של הקב\"ה לאחר הריגת שרו של אדום בבצרה: \u0003טועה\u0004 שרה של רומי — \u0003שאינה קולטת אלא\u0004 עיר המקלט \u0003בצר, והוא גולה לבצרה\u0004 שאינה בצר. \u0003טועה\u0004 — \u0003שאינה קולטת אלא\u0004 רוצח ב\u0003שוגג, והוא מזיד היה. טועה\u0004 — \u0003שאינה קולטת אלא אדם, והוא מלאך הוא.\u0004","ועוד לענין הלכה שנאמרה במשנה. \u0003אמר ר' אבהו: ערי מקלט לא נתנו לקבורה, דכתיב\u0004 \u0005[שנאמר]\u0006 בערי הלויים \u0003\"ומגרשיהם יהיו לבהמתם ולרכשם ולכל חיתם\"\u0004 (במדבר לה, ג), והמלים \"לכל חייתם\" באו ללמדנו: \u0003לחיים נתנו ולא לקבורה,\u0004 והלויים הגרים בערי המקלט נקברים מחוץ למגרש העיר ולא בתוכו. \u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה שדרשו במשנתנו, את הכתוב \u0003\"שמה\"\u0004 (במדבר לה, כה), שהגולה לעיר המקלט \u0003שם תהא דירתו, שם תהא מיתתו, שם תהא קבורתו!\u0004 ומשיבים: \u0003רוצח שאני, דגלי ביה רחמנא\u0004 \u0005[רוצח שונה, שגילתה בו התורה]\u0006 והורתה במיוחד לקוברו שם, אבל בני העיר אינם נקברים בעיר המקלט.","שנינו במשנה: \u0003כשם שהעיר קולטת\u0004 כך תחומה קולט. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה לכך\u0005]\u0006 ממה ששנינו על הכתוב \u0003\"וישב בה\"\u0004 (במדבר לה, כה) ופירשו: \u0003\"בה\"\u0004 — \u0003ולא בתחומה! אמר אביי: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן\u0004 שתחום העיר דינו כעיר — \u0003לקלוט,\u0004 שלענין קליטה והצלה אף תחום העיר קולט, ואין גואל הדם רשאי להורגו שם. \u0003כאן\u0004 שאין תחום העיר כעיר — \u0003לדור,\u0004 שאינו רשאי לדור אלא רק בעיר עצמה.","ותוהים: לשם מה צריך לומר שהרוצח אינו יכול \u0003לדור\u0004 בתחום העיר? \u0003תיפוק ליה\u0004 \u0005[תצא לו]\u0006 הלכה זו מטעם אחר ששנינו — ש\u0003אין עושין\u0004 בערי הלויים \u0003שדה\u0004 של העיר \u0003מגרש\u0004 (מקום פנוי) \u0003ולא מגרש שדה, לא מגרש עיר, ולא עיר מגרש.\u0004 ואם כן, בתחום העיר העשוי למגרש אין רשאים כלל לעשות מקום דירה! \u0003אמר רב ששת: לא נצרכה אלא למחילות,\u0004 שאם הרוצח עושה מחילה בתחום העיר וגר בה, הרי אף שאין בכך איסור מצד קלקול שדה העיר — אסור לו לעשות כן מצד גזירת הכתוב שישב בתוך העיר דווקא.","שנינו במשנה מחלוקת בין ר' יוסי הגלילי ור' עקיבא בדבר \u0003רוצח שיצא חוץ לתחום\u0004 אם רשאי או מצווה גואל הדם להורגו, ומה דינם של אנשים שאינם גואלי הדם. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על הפסוק \"ומצא אותו גואל הדם מחוץ לגבול עיר מקלטו \u0003ורצח גאל הדם את הרצח\u0004 אין לו דם\" (במדבר לה, כז) — \u0003מצוה\u0004 היא \u0003ביד גואל הדם\u0004 להורגו, \u0003אין\u0004 שם \u0003גואל הדם\u0004 לקיים מצוה זו — \u0003רשות ביד כל אדם\u0004 אחר שאינו גואל הדם להורגו, אלו \u0003דברי ר' יוסי הגלילי. ר' עקיבא אומר: רשות ביד גואל הדם\u0004 להורגו, \u0003וכל אדם\u0004 אחר \u0003חייבין עליו\u0004 אם הרגו.","ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוסי הגלילי\u0004 — \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 בפסוק \u0003\"אם רצח\u0004 גואל הדם את הרוצח אין לו דם\"? הלוא נאמר \"ורצח את הרוצח\", לומר שמצוה היא. \u0003ור' עקיבא\u0004 טוען: \u0003מי כתיב\u0004 \u0005[האם נאמר]\u0006 \u0003\"ירצח\"\u0004 בלשון צווי? הרי נאמר רק \"ורצח\" שהוא כסיפור דברים.","ובענין זה מביאים מה ש\u0003אמר מר זוטרא בר טוביה אמר רב: רוצח שיצא חוץ לתחום\u0004 עיר המקלט, \u0003ומצאו\u0004 שם \u0003גואל הדם והרגו\u0004 — הרי זה \u0003נהרג עליו.\u0004 ותוהים: \u0003כמאן\u0004 \u0005[כמי]\u0006 אמר דבר זה? הרי זה \u0003לא כר' יוסי הגלילי\u0004 שאומר שמצוה להורגו, \u0003ולא כר' עקיבא\u0004 שאומר שרשות להורגו!","ומשיבים: \u0003הוא דאמר כי האי תנא\u0004 \u0005[שאומר כ\u0006דעת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 \u0003ר' אליעזר אומר:\u0004 נאמר \"ולא ימות הרוצח \u0003עד עמדו לפני העדה למשפט\"\u0004 (במדבר לה, יב), \u0003מה תלמוד לומר\u0004 בפסוק זה? \u0003לפי שנאמר\u0004 \"ומצאו אותו גואל הדם... \u0003ורצח גאל הדם את הרצח\"\u0004 ((במדבר לה, כז) \u0003יכול\u0004 ירצחנו \u0003מיד? תלמוד לומר \"עד עמדו לפני העדה למשפט\",\u0004 משמע, שאין גואל הדם רשאי להרוג את הרוצח אלא לאחר שיצא חייב בדין, ובמקרה שלא נידון עדיין, אמר מר זוטרא בשם רב שגואל הדם נהרג עליו.","ושואלים: \u0003ור' יוסי ור' עקיבא, האי\u0004 \u0005[\u0006פסוק \u0005זה]\u0006 \u0003\"עד עמדו לפני העדה למשפט\" מאי דרשי ביה\u0004 \u0005[מה דורשים\u0006 הם \u0005בו]?\u0006 ומשיבים: \u0003ההוא מיבעי ליה לכדתניא\u0004 \u0005[אותו\u0006 פסוק \u0005נצרך להם לכמו ששנויה\u0006 בברייתא\u0005],\u0006 \u0003ר' עקיבא אומר: מנין לסנהדרין ש\u0004הם עצמם \u0003ראו אחד שהרג את הנפש, שאין\u0004 הם עצמם \u0003ממיתין אותו\u0004 (דנים אותו למיתה), \u0003עד שיעמוד\u0004 ויישפט \u0003בבית דין אחר? תלמוד לומר \"עד עמדו לפני העדה למשפט\",\u0004 לומר: \u0003עד שיעמוד בבית דין אחר,\u0004 שכיון שהם עצמם ראו את מעשה הרצח שוב אינם יכולים עוד לדון בזכותו כראוי.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 נאמר \u0003\"אם יצא יצא הרצח...\u0004 ורצח גואל הדם את הרוצח אין לו דם\" ((במדבר לה, כו— כז), \u0003אין לי אלא\u0004 שיצא \u0003במזיד,\u0004 שרשאי גואל הדם להורגו, יצא \u0003בשוגג מנין? תלמוד לומר\u0004 בלשון כפולה \u0003\"אם יצא יצא\", מכל מקום.\u0004","ושואלים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003וההורגו\u0004 את הרוצח שיצא בשגגה, \u0003במזיד —\u0004 \u0003נהרג,\u0004 הרגו \u0003בשוגג\u0004 — \u0003גולה!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003הא כמאן דאמר: אמרינן\u0004 \u0005[זה כ\u0006שיטת \u0005מי שאומר: אומרים אנו]\u0006 \u0003דברה תורה כלשון בני אדם,\u0004 ולכן לשון כפולה, כגון \"יצוא יצא\", אינה מלמדת דבר, \u0003הא כמאן דאמר: לא אמרינן\u0004 \u0005[זה כ\u0006דעת \u0005מי שאומר: אין אנו אומרים]\u0006 \u0003דברה תורה כלשון בני אדם,\u0004 והכפילות באה לרבות גם על היוצא בשוגג, שדמו מותר.","\u0003אמר אביי: מסתברא כמאן דאמר\u0004 \u0005[מסתבר\u0006 לפרש כאן \u0005כ\u0006דעת \u0005מי שאומר]\u0006 \u0003דברה תורה כלשון בני אדם,\u0004 ואין מדובר גם על מי שיצא בשוגג, ומדוע — \u0003שלא יהא סופו\u0004 של ההורג בשגגה \u0003חמור מתחלתו. מה תחלתו,\u0004 כלומר במשפט ששופטים אותו על הרצח, אם הרג \u0003במזיד\u0004 — \u0003נהרג, בשוגג\u0004 — \u0003גולה. אף סופו,\u0004 כשבאים לדון בהריגתו שלו, \u0003במזיד\u0004 — \u0003נהרג, בשוגג\u0004 — \u0003גולה.\u0004","\u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 \u0003אב שהרג\u0004 את בנו — \u0003בנו\u0004 האחר \u0003נעשה לו גואל הדם\u0004 והורגו. \u0003ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]\u0006 \u0003אין בנו נעשה לו גואל הדם.\u0004 ומציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי \u0003הא\u0004 \u0005[זו]\u0006 שאומרת שבנו נעשה גואל הדם להורגו היא שיטת \u0003ר' יוסי הגלילי,\u0004 שאומר שמצוה היא להרוג את הרוצח, ולכן המצוה מוטלת גם על הבן. \u0003והא\u0004 \u0005[וזו]\u0006 האוסרת להרוג את האב כשיטת \u0003ר' עקיבא,\u0004 הסבור שרשות היא?","ודוחים: \u0003ותסברא\u0004 \u0005[וכי יכול אתה לסבור כן],\u0006 \u0003בין למאן דאמר\u0004 \u0005[למי שאומר]\u0006 \u0003מצוה בין למאן דאמר\u0004 \u0005[למי שאומר]\u0006 \u0003רשות, מי שרי\u0004 \u0005[האם מותר]\u0006 לבן לעשות זאת? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר רב הונא, וכן תנא דבי\u0004 \u0005[ושנה\u0006 החכם \u0005בבית מדרשו]\u0006 של \u0003ר' ישמעאל: לכל\u0004 עבירות שבתורה, גם אם חטא האב וצריך להכותו או לקללו, \u0003אין הבן נעשה שליח לאביו להכותו ולקללתו, חוץ\u0004 מן המקרה שהיה האב \u0003מסית, שהרי אמרה תורה\u0004 במסית \u0003\"לא תחמל ולא תכסה עליו\"\u0004 (דברים יג, ט)!","\u0003אלא\u0004 יש לומר באופן אחר, \u0003לא קשיא\u0004 \u0005[אינו קשה],\u0006 \u0003הא\u0004 \u0005[זה\u0006 נאמר\u0005]\u0006 \u0003בבנו,\u0004 שאסור לו להיות גואל הדם להרוג את האב, \u0003והא\u0004 \u0005[וזה]\u0006 \u0003בבן בנו,\u0004 שכיון שאין מוטלת עליו מצות כיבוד אב — יכול הוא להיות גואל הדם, ויהרוג את סבו.","נאמר במשנה הקודמת כי כשם שהעיר קולטת את ההורג בשגגה, כך גם תחומה קולט. ומוסיפים: \u0003אילן שהוא עומד בתוך התחום\u0004 של עיר המקלט, \u0003ונופו\u0004 (ענפיו) \u0003נוטה חוץ לתחום\u0004 העיר, \u0003או עומד חוץ לתחום ונופו נוטה בתוך התחום\u0004 — \u0003הכל הולך אחר הנוף,\u0004 ולפי זה דנים אם הוא בתוך או מחוץ לתחום.","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005],\u0006 ממה ששנינו לדיני אכילת מעשר שני בתוך ירושלים: \u0003אילן שהוא עומד בתוך הפנים,\u0004 בתוך ירושלים \u0003ונוטה לחוץ\u0004 לחומת העיר, \u0003או עומד בחוץ ונוטה לפנים,\u0004 הכלל הוא: מה ש\u0003מכנגד החומה ולפנים\u0004 — נחשב \u0003כלפנים,\u0004 מה ש\u0003מכנגד החומה ולחוץ\u0004 — \u0003כלחוץ.\u0004 משמע איפוא שאין הולכים באילן אחר הנוף או אחר עיקרו, אלא כל חלק ממנו לפי מיקומו ביחס לחומת העיר!","ודוחים: \u0003מעשר\u0004 על \u0003ערי מקלט קא רמית\u0004 \u0005[אתה משליך,\u0006 מראה סתירה\u0005]?\u0006 אין הדברים דומים, \u0003מעשר בחומה תלה רחמנא\u0004 \u0005[תלתה התורה],\u0006 והחומה בלבד היא הקובעת את תחום העיר, \u0003ערי מקלט בדירה תלה רחמנא\u0004 \u0005[תלתה התורה]\u0006 את דינם, ולכן הולכים אחר מה שהוא יכול לדור בו, \u0003בנופו מתדר ליה\u0004 \u0005[הוא יכול לדור],\u0006 \u0003בעיקרו\u0004 בגזעו של עץ \u0003לא מתדר ליה\u0004 \u0005[אינו יכול לדור],\u0006 ולכן הולכים אחר הנוף.","\u0003ורמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מדין \u0003מעשר\u0004 על דין \u0003מעשר, דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003בירושלים הלך אחר הנוף\u0004 שהיכן שהנוף נמצא — שם נחשב מקומו של העץ, וכן \u0003בערי מקלט\u0004 — \u0003הלך אחר הנוף.\u0004 והרי שנינו קודם שלענין מעשר הולכים אחר החומה! \u0003אמר רב כהנא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 כי \u0003הא\u0004 \u0005[זו]\u0006 כשיטת \u0003ר' יהודה, והא\u0004 \u0005[וזו]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים].\u0006 ומה היא מחלוקתם? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 לענין אכילת מעשר שני בירושלים, ל"],["\u0003ר' יהודה אומר: במערה\u0004 — \u0003הולך אחר פתחה,\u0004 שאם פתחה בתוך העיר — הרי כל המערה נחשבת כבתוך העיר, ומותר לאכול בה מעשר. \u0003באילן\u0004 — \u0003הולך אחר נופו.\u0004 והיא שיטת הברייתא האומרת שבירושלים וגם בערי מקלט הולכים אחר הנוף.","ודוחים: ומנין שכך יסבור ר' יהודה לענין ערי מקלט? \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003שמעת ליה\u0004 \u0005[אותו]\u0006 את \u0003ר' יהודה\u0004 במפורש \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003מעשר\u0004 שהוא הולך אחר הנוף \u0003לחומרא,\u0004 שאם \u0003עיקרו\u0004 של העץ \u0003בחוץ ונופו בפנים\u0004 בתוך ירושלים, \u0003כי היכי\u0004 \u0005[כמו]\u0006 ש\u0003בנופו לא מצי פריק\u0004 \u0005[אינו יכול לפדות]\u0006 את פירות המעשר, אלא חייב לאוכלם בירושלים — \u0003בעיקרו\u0004 (בגזעו) \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003לא מצי פריק\u0004 \u0005[אינו יכול לפדות],\u0006 לפי שגזעו נמשך אחר נופו. אבל אם היה \u0003עיקרו מבפנים ונופו מבחוץ\u0004 היה מחמיר גם בצד אחר, \u0003כי היכי\u0004 \u0005[כמו]\u0006 ש\u0003בנופו לא מצי אכיל\u0004 \u0005[אינו יכול לאכול]\u0006 את הפירות מחוץ לירושלים \u0003בלא פדייה\u0004 — \u0003בעיקרו נמי\u0004 \u0005[גם כן]\u0006 \u0003לא מצי אכיל\u0004 \u0005[אינו יכול לאכול]\u0006 \u0003בלא פדייה,\u0004 ואם כן הולך הוא אחר הנוף רק להחמיר.","\u0003אלא גבי\u0004 \u0005[אצל]\u0006 \u0003ערי מקלט, בשלמא\u0004 \u0005[נניח]\u0006 אם \u0003עיקרו בחוץ ונופו בפנים,\u0004 אפשר לומר: \u0003כי היכי\u0004 \u0005[כמו]\u0006 ש\u0003בנופו לא מצי קטיל ליה\u0004 \u0005[אינו יכול,\u0006 רשאי, \u0005להרוג אותו],\u0006 כך \u0003בעיקרו נמי\u0004 \u0005[גם כן]\u0006 \u0003לא מצי קטיל ליה\u0004 \u0005[אינו יכול להרוג אותו].\u0006 \u0003אלא\u0004 אם היה \u0003עיקרו בפנים ונופו בחוץ,\u0004 האם תאמר \u0003כי היכי\u0004 \u0005[כמו]\u0006 ש\u0003בנופו\u0004 הוא \u0003מצי קטיל ליה\u0004 \u0005[יכול להרוג אותו],\u0006 \u0003בעיקרו נמי מצי קטיל ליה\u0004 \u0005[גם כן יכול להרוג אותו]?!\u0006 ואיך אפשר לומר זאת? \u0003הא גואי קאי\u0004 \u0005[הרי הוא עומד בפנים]\u0006 בתוך עיר מקלט, ובוודאי אינו יכול להורגו שם, ואם כן כיצד ניתן לומר שהולכים אחר הנוף!","\u0003אמר רבא,\u0004 אפשר להסביר כך: אם היה גזעו של העץ בפנים ונופו נוטה לחוץ, והרוצח בשגגה עומד \u0003בעיקרו\u0004 — \u0003דכולי עלמא לא פליגי דלא מצי קטיל\u0004 \u0005[הכל אינם חלוקים שאינו יכול להרוג\u0006 אותו\u0005],\u0006 ולא על כך אמר ר' יהודה שהעיקר הולך אחר הנוף. ומן הצד האחר, אם \u0003קאי\u0004 \u0005[עומד]\u0006 הרוצח \u0003בנופו\u0004 של העץ, \u0003ויכול\u0004 גואל הדם \u0003להורגו בחצים ובצרורות\u0004 — \u0003דכולי עלמא לא פליגי דמצי קטיל ליה\u0004 \u0005[הכל אינם חלוקים שיכול להרוג אותו],\u0006 וגם לדעת חכמים, שהרי נופו מחוץ לעיר.","\u0003כי פליגי\u0004 \u0005[כאשר חלוקים]\u0006 ר' יהודה וחכמים — הרי זה \u0003ב\u0004שאלה לענין \u0003מהוי\u0004 \u0005[שייעשה]\u0006 \u0003עיקרו דרגא\u0004 \u0005[מדרגה]\u0006 \u0003לנופו\u0004 לעלות להורגו שם. \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' יהודה, \u0005סבור]:\u0006 \u0003הוי\u0004 \u0005[נעשה]\u0006 \u0003עיקרו דרגא\u0004 \u0005[מדרגה]\u0006 \u0003לנופו\u0004 ויכול להגיע לגזעו של העץ בפנים, ומשם לעלות לנופו שבחוץ ולהרוג את הרוצח, והוא מה שאמר שהולכים אחר הנוף. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003לא הוי\u0004 \u0005[נעשה]\u0006 \u0003עיקרו דרגא\u0004 \u0005[מדרגה]\u0006 \u0003לנופו.\u0004","\u0003רב אשי אמר: מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אחר הנוף\"\u0004 בדברי ר' יהודה — אין הכוונה רק אחר הנוף ולא אחר הגזע, אלא שבנוסף למקום הגזע הולכים \u0003אף אחר הנוף,\u0004 במקום שיש בדבר להחמיר, ולכן עץ שעיקרו בפנים ונופו בחוץ, ייחשב לענין עיר המקלט כאילו היה נופו בפנים.","רוצח שגלה לעיר המקלט ו\u0003הרג\u0004 אדם בשגגה \u0003באותה העיר\u0004 — \u0003גולה\u0004 בה עצמה \u0003משכונה לשכונה, ובן לוי\u0004 שמושבו בעיר מקלט והרג — \u0003גולה מעיר\u0004 זו \u0003לעיר\u0004 מקלט אחרת.","ובדין האמור במשנה, בבן לוי הגולה, מביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר \"ואשר לא צדה... \u0003ושמתי לך מקום\u0004 אשר ינוס שמה\" (שמות כא, יג), \u0003\"ושמתי לך\"\u0004 — כוונתו \u0003בחייך,\u0004 שאף בחייו של משה רבינו כבר היה מקום שנועד לרוצחים בשגגה מעין עיר מקלט. \u0003\"מקום\"\u0004 — כוונתו \u0003ממקומך,\u0004 שמקומו של משה, מחנה הלויים, היה מקום המקלט במדבר, \u0003\"אשר ינוס שמה\". מלמד שהיו ישראל מגלין\u0004 את הרוצח בשגגה גם \u0003במדבר,\u0004 קודם שנכנסו לארץ. \u0003להיכן\u0004 היו \u0003מגלין\u0004 אותו כשהיו במדבר — \u0003למחנה לויה,\u0004 ששימש כעיר מקלט.","\u0003מכאן אמרו: בן לוי שהרג\u0004 — \u0003גולה מפלך לפלך\u0004 (ממחוז אחד לשני) לעיר לויים אחרת, \u0003ו\u0004אולם \u0003אם גלה לפלכו\u0004 לעירו שלו — \u0003פלכו קולטו. אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: מאי קרא\u0004 \u0005[מה המקרא]\u0006 המלמד דבר זה, שרוצח המצוי בעיר מקלט מוצא מקלט באותה עיר עצמה — שנאמר \u0003\"כי בעיר מקלטו ישב\"\u0004 (במדבר לה, כח) כוונתו: \u0003עיר שקלטתו כבר\u0004 הריהי נעשית לו עיר מקלט גם להבא.","\u0003כיוצא בו, רוצח שגלה לעיר מקלטו ורצו אנשי העיר לכבדו\u0004 מפני שהיה אדם גדול, \u0003יאמר להם \"רוצח אני\", אמרו לו\u0004 בני העיר: \u0003\"אף על פי כן\"\u0004 כלומר, יודעים אנו, ובכל זאת רוצים אנו לכבדך — \u0003יקבל מהן\u0004 את הכבוד, \u0003שנאמר \"וזה דבר הרוצח\"\u0004 (דברים יט, יב) שצריך לדבר ולהגיד להם שרוצח הוא, ואולם די בכך."],["\u0003מעלים\u0004 (משלמים) \u0003היו\u0004 הרוצחים בשגגה, הגרים בעיר המקלט, \u0003שכר ללוים\u0004 הגרים באותה עיר על שהיו שוכרים מהם דירות לגור בהן, שהרי ערי מקלט ערי הלויים היו, אלו \u0003דברי ר' יהודה. ר' מאיר אומר: לא היו מעלים להן שכר,\u0004 והיו גרים שם בחינם, משום שגזירת הכתוב היא. \u0003ו\u0004עוד נחלקו: רוצח שחוזר למקומו במות הכהן הגדול \u0003חוזר ל\u0004אותה \u0003שררה\u0004 (תפקיד ציבורי) \u0003שהיה בה\u0004 לפני שגלה, אלו \u0003דברי ר' מאיר. ר' יהודה אומר: לא היה חוזר לשררה שהיה בה.\u0004","\u0003אמר רב כהנא: מחלוקת\u0004 זו בין ר' יהודה ור' מאיר, אם משלמים ללויים בעלי הבתים בעיר המקלט, היא דווקא \u0003בשש\u0004 ערי המקלט המנויות בתורה במפורש, \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' יהודה, \u0005סבור]\u0006 שמה שנאמר \"ערי מקלט תהיינה \u0003לכם\"\u0004 (במדבר לה, יא) לרוצחים שבכם, כוונתו \u0003לקליטה\u0004 בלבד, שערים אלו אמורות להוות מקלט לרוצח, אבל אין זה נותן לרוצחים זכויות נוספות בעיר עצמה, ולכן צריכים לשלם ללויים. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' מאיר, \u0005סבור]:\u0006 \u0003\"לכם\"\u0004 — כוונתו \u0003לכל צרכיכם,\u0004 ולכן אין צריכים לשלם ללויים. \u0003אבל בארבעים ושתים\u0004 ערי הלויים הנוספות, שאף הן היו ערי מקלט — \u0003דברי הכל היו מעלין להם שכר.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא:\u0004 אי אפשר לומר כן, כי \u0003הא\u0004 \u0005[הרי]\u0006 \u0003ודאי \"לכם\"\u0004 — \u0003לכל צרכיכם משמע,\u0004 ובוודאי שבשש ערי המקלט אין צריכים לשלם ללויים. \u0003אלא אמר רבא:\u0004 כך צריך לומר, \u0003מחלוקת\u0004 היא דווקא \u0003בארבעים ושתים\u0004 ערי הלויים הנוספות, \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' יהודה, \u0005סבור]\u0006 שמה שנאמר \u0003\"ועליהם תתנו\u0004 ארבעים ושתים עיר\" (מדבר לה, ו) כוונתו \u0003כי הנך\u0004 \u0005[כמו\u0006 ערים \u0005אלו]\u0006 רק \u0003ל\u0004ענין \u0003קליטה,\u0004 כמו שנאמר תחילה \"את שש ערי המקלט אשר תתנו לנוס שמה הרוצח\", שגם אלה קולטות. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' מאיר, \u0005סבור]:\u0006 \u0003\"ועליהם תתנו\"\u0004 — \u0003כי הנך\u0004 \u0005[כמו אלה]\u0006 לכל ענין, \u0003מה הנך\u0004 \u0005[אלה]\u0006 שש ערי המקלט המפורשות ניתנו \u0003לכל צרכיכם, אף הני נמי\u0004 \u0005[אלה גם כן]\u0006 — \u0003לכל צרכיכם, אבל בשש\u0004 ערי המקלט המפורשות — \u0003דברי הכל לא היו מעלים להן שכר.\u0004","","שנינו במשנה מחלוקת לגבי השאלה האם הרוצח שחזר מגלותו \u0003חוזר\u0004 גם \u0003לשררה שהיה בה.\u0004 ובענין זה מביאים מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 לגבי עבד עברי שמשתחרר ביובל, שנאמר בו \u0003\"ושב אל משפחתו ואל אחזת אבותיו ישוב\"\u0004 (ויקרא כה, מא) שיש לדורשו: \u0003למשפחתו הוא שב, ואינו שב למה שהחזיקו אבותיו\u0004 לענין גדולה וכבוד, אלו \u0003דברי ר' יהודה. ר' מאיר אומר: אף הוא שב למה שהחזיקו אבותיו,\u0004 שנאמר \u0003\"אל אחזת אבותיו\",\u0004 וכוונתו — \u0003כאבותיו.\u0004 \u0003וכן ב\u0004רוצח ה\u0003גולה\u0004 לעיר מקלט הדין כן, שהרי \u0003כשהוא אומר \"ישוב\",\u0004 ומלה זו מיותרת היא, שהרי נאמר בתחילת הדברים \"ושב\", אלא באה \u0003לרבות את הרוצח.\u0004","","ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"וכן בגולה\"?\u0004 ומסבירים: \u0003כדתניא\u0004 \u0005[כמו ששנויה\u0006 ברייתא\u0005]\u0006 שנאמר: \u0003\"ישוב הרצח אל ארץ אחזתו\"\u0004 (במדבר לה, כח) — \u0003לארץ אחוזתו הוא שב, ואינו שב למה שהחזיקו אבותיו\u0004 בעניני גדולה, אלו \u0003דברי ר' יהודה. ר' מאיר אומר: אף הוא\u0004 הרוצח \u0003שב למה שהחזיקו אבותיו,\u0004 ומנין — \u0003גמר\u0004 \u0005[למד]\u0006 מגזירה שווה \u0003שיבה שיבה\u0004 (\"ישוב\" \"ישוב\") \u0003מהתם\u0004 \u0005[משם],\u0006 מעבד עברי שנאמר בו \"לאחוזת אבותיו ישוב\", ולדעת ר' מאיר הכוונה לחזקת אבותיו, שאף ברוצח שנאמר בו \"ישוב\" הדין כן.","","לאחר שהביאה המשנה את רשימות הנהרגים (במסכת סנהדרין) ואת אלו הגולים, מביאה המשנה \u0003ואלו הן הלוקין\u0004 מן התורה, משום שעברו על מצוות לא תעשה: \u0003הבא על אחותו, ו\u0004כן הבא \u0003על אחות אביו, ועל אחות אמו, ועל אחות אשתו, ועל אשת אחיו, ועל אשת אחי אביו, ועל הנדה. אלמנה\u0004 שנישאה \u0003לכהן גדול, גרושה וחלוצה לכהן הדיוט, ממזרת ו\u0004כן \u0003נתינה\u0004 (מבני הגבעונים) שנישאה \u0003לישראל, בת ישראל\u0004 שנישאה \u0003לנתין ו\u0004כן בת ישראל שנישאה \u0003לממזר\u0004 — כל אלה לוקים. וקצת פרטים בדבר, אם היתה אשה שהיא גם \u0003אלמנה ו\u0004גם \u0003גרושה,\u0004 שנתאלמנה וחזרה ונישאה ונתגרשה — \u0003חייבין עליה משום שני שמות\u0004 (שני כתובים, שני איסורים) שכהן גדול שנושא אותה לוקה גם משום אלמנה וגם משום גרושה. אם היתה אשה אחת גם \u0003גרושה\u0004 מאדם אחד \u0003ו\u0004גם \u0003חלוצה\u0004 מאדם אחר — הכהן שבא עליה \u0003אינו חייב אלא משום אחת בלבד.\u0004","","ועוד מן הלוקים: \u0003הטמא שאכל את הקדש, ו\u0004כן \u0003הבא אל המקדש טמא, ו\u0004ה\u0003אוכל חלב, ו\u0004כן האוכל \u0003דם, ונותר\u0004 מן הקרבנות, \u0003ופגול\u0004 (קרבן שנפסל משום שחשבו להקריבו שלא בזמנו), \u0003ו\u0004האוכל קרבן \u0003טמא.\u0004","\u0003והשוחט\u0004 או \u0003מעלה\u0004 קרבן על המזבח \u0003בחוץ\u0004 מחוץ למקדש, \u0003והאוכל חמץ בפסח, והאוכל ו\u0004כן \u0003העושה מלאכה ביום הכפורים, והמפטם את השמן\u0004 שעושה שמן מבושם כעין שמן המשחה שמשחו בו את כלי המקדש, שלא לצורך קודש, \u0003והמפטם את הקטורת\u0004 כדרך הקטורת שבמקדש, להדיוט, \u0003והסך בשמן המשחה, והאוכל נבילות וטריפות שקצים ורמשים.\u0004","ועוד לוקה אם \u0003אכל טבל\u0004 (תבואה שלא הפרישו ממנה תרומות ומעשרות כלל) \u0003ומעשר ראשון שלא נטלה תרומתו\u0004 שלא הפרישו ממנו מעשר מן המעשר, \u0003ומעשר שני והקדש שלא נפדו.\u0004","ובפרטי איסורי האכילה, \u0003כמה יאכל מן הטבל ויהא חייב? ר' שמעון אומר:\u0004 אפילו אם אוכל \u0003כל שהוא\u0004 חייב מלקות. \u0003וחכמים אומרים:\u0004 עד שיאכל \u0003כזית,\u0004 שהוא השיעור הקטן ביותר הנקרא אכילה. \u0003אמר להן ר' שמעון: אי\u0004 (אין) \u0003אתם מודים לי באוכל נמלה,\u0004 אף על פי שגודלה \u0003כל שהוא שהוא חייב? אמרו לו:\u0004 על נמלה לוקה \u0003מפני שהיא כברייתה\u0004 כלומר, הריהי יצור שלם, כפי שנבראה, והוא מה שאסרה התורה. \u0003אמר להן: אף חטה אחת כברייתה\u0004 היא יחידה שלמה, ולוקה עליה.","על רשימת הלוקים במשנה מעירים: \u0003חייבי כריתות קא תני\u0004 \u0005[שנה],\u0006 שהרי הרשימה של רוב הלוקים הראשונים, כוללת דברים שיש בהם לא רק איסור לא תעשה, אלא גם נאמר בתורה שחייבים עליהם כרת, ובכל זאת לוקים על איסורים אלה. ואילו \u0003חייבי מיתות בית דין\u0004 — \u0003לא קתני\u0004 \u0005[שנה]\u0006 ביניהם. משמע שעל איסורים אלה אין לוקים, ואם כן, \u0003מתניתין מני\u0004 \u0005[משנתנו כ\u0006שיטת \u0005מי היא]?\u0006 שיטת \u0003ר' עקיבא היא. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 שנחלקו תנאים בדבר זה: \u0003אחד חייבי כריתות, ואחד חייבי מיתות בית דין ל\u0004"],["\u0003ישנו בכלל מלקות ארבעים,\u0004 שכיון שעברו על לא תעשה שבתורה — לוקים, אלו \u0003דברי ר' ישמעאל.\u0004","\u0003ר' עקיבא אומר: חייבי כריתות ישנו בכלל מלקות ארבעים,\u0004 ומדוע — \u0003שאם עשו תשובה\u0004 על חטאם זה \u0003בית דין של מעלה מוחלין להן\u0004 על עונש הכרת, ולכן אין לפוטרם ממלקות. \u0003חייבי מיתות בית דין\u0004 — \u0003אינו בכלל מלקות ארבעים, ש\u0004כן גם \u0003אם עשו תשובה\u0004 — \u0003אין בית דין של מטה מוחלין להן,\u0004 אלא דנים אותם למיתה, ואין אדם נענש פעמיים על אותה עבירה.","\u0003ר' יצחק אומר\u0004 שיטה אחרת: אף חייבי כריתות כחייבי מיתות בית דין, אינם לוקים. וטעם הדבר — \u0003חייבי כריתות בכלל\u0004 אחד \u0003היו,\u0004 ככתוב \"כי כל אשר יעשה מכל התועבות האלה ונכרתו הנפשות העושות מקרב עמם\" (ויקרא יח, כט), ובכללם גם הבא על אחותו, \u0003ולמה יצאת\u0004 למה נתפרש במיוחד דין \u0003כרת באחותו,\u0004 שנאמר שוב \"ואיש אשר יקח את אחותו... ונכרתו לעיני בני עמם\" (ויקרא כ, יז) — כדי להדגיש: \u0003לדונו\u0004 את הבא על אחותו \u0003בכרת\u0004 דווקא \u0003ולא במלקות,\u0004 ומכאן למדים גם לכל חייבי הכריתות שאין לוקים.","ומסבירים את השיטות. \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' ישמעאל\u0004 שמחייב מלקות גם בחייבי מיתות בית דין? \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"אם לא תשמר לעשות את כל דברי התורה הזאת\"\u0004 (דברים כח, נח) \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 מיד אחר כך בעונשו של העובר על כתוב זה \u0003\"והפלא ה' את מכתך\"\u0004 (דברים כח, נט), והרי דרשו בענין זה: \u0003הפלאה זו איני יודע מה היא, כשהוא אומר\u0004 בחייבי מלקות \u0003\"והפילו השפט והכהו לפניו\"\u0004 (דברים כה, ב) — \u0003הוי אומר הפלאה זו מלקות היא, וכתיב\u0004 \u0005[ונאמר]\u0006 שהפלאה זו באה כעונש \u0003\"אם לא תשמר לעשות את כל\u0004 דברי התורה הזאת\", משמע שמי שאיננו מקיים כל אחת מן המצוות — מלקים אותו, ואף חייבי מיתות בית דין בכלל זה.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 מפרש ר' ישמעאל, \u0003חייבי עשה נמי\u0004 \u0005[גם כן]\u0006 ילקו, שהרי נאמר בכתוב זה \"כל דברי התורה הזאת\"! ומשיבים: \u0003\"אם לא תשמר\" כתיב\u0004 \u0005[נאמר],\u0006 \u0003וכ\u0004שיטת \u0003ר' אבין אמר ר' אילעי,\u0004 ש\u0003אמר ר' אבין אמר ר' אילעי: כל מקום שנאמר\u0004 בתורה לשון \u0003\"השמר\"\u0004 או \u0003\"פן\" ו\u0004כן \u0003\"אל\"\u0004 — \u0003אינו אלא\u0004 איסור \u0003לא תעשה.\u0004 וכיון שנאמר בכתוב זה \"אם לא תשמור\" — הכוונה היא דווקא לעובר על מצוות לא תעשה שלוקה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 על \u0003לאו שאין בו מעשה נמי\u0004 \u0005[גם כן]\u0006 ילקה, והרי אין לוקים עליו! ודוחים: \"אם לא תשמור \u0003לעשות\" כתיב\u0004 \u0005[נאמר],\u0006 וזה לא עשה מעשה.","ושואלים: \u0003לאו שניתק לעשה\u0004 שנלווית אליו מצות עשה (כגון שלא לקחת האם על הבנים, אלא לשלח את האם) \u0003נמי\u0004 \u0005[גם כן]\u0006 ילקה עליו, שהרי יש בו מעשה, והרי אין לוקים עליו! ודוחים: אין מלקים על לאו שכזה, משום שאין מלקות אלא \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003לאו\u0004 של \u0003חסימה\u0004 שאסור לחסום שור בדישו (דברים כה, ד). שלאו זה הובא בתורה בסמוך לדין המלקות, כחלק מאותה פרשיה עצמה, ומסמיכות זו אנו למדים שאין לוקה על מצוות לא תעשה אלא בדומה לזו, והרי היא אינה ניתקת לעשה.","ומעירים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכך]\u0006 לתירוץ זה, את \u0003כולהו\u0004 \u0005[כל]\u0006 השאלות הקודמות \u0003נמי\u0004 \u0005[גם כן]\u0006 יש לתרץ באותו אופן, שאין לוקים עליהן משום שלוקים רק על לאו שהוא \u0003דומיא\u0004 \u0005[דומה]\u0006 ל\u0003לאו\u0004 של \u0003חסימה,\u0004 שהוא לא תעשה דווקא, ויש בו מעשה.","ומבררים: \u0003ור' עקיבא מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שלדעתו חייבי מיתות בית דין אינם לוקים? נאמר \"והכהו \u0003כדי רשעתו\"\u0004 (דברים כה, ב) לומר: \u0003משום רשעה אחת אתה מחייבו\u0004 בעונש, \u0003ואי אתה מחייבו משום שתי רשעיות,\u0004 שאין אדם נענש בשני עונשים על חטא אחד, ודי לו שנענש במיתה.","\u0003ור' ישמעאל\u0004 סבור בענין זה: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים לענין \u0003מיתה וממון, או מלקות וממון,\u0004 שאין מענישים אותו בשניהם כאחת, \u0003אבל מיתה ומלקות\u0004 אינם כשני עונשים, אלא \u0003מיתה אריכתא\u0004 \u0005[ארוכה]\u0006 \u0003היא,\u0004 שקודם מלקים אותו ואחר כך הורגים אותו.","ושואלים: \u0003ולר' עקיבא, אי הכי\u0004 \u0005[אם כך]\u0006 \u0003חייבי כריתות נמי\u0004 \u0005[גם כן],\u0006 כיון שהם חייבים כרת לא יתחייבו בעונש נוסף של מלקות! \u0003מאי אמרת\u0004 \u0005[מה אתה אומר]\u0006 בתשובה לכך, \u0003שאם עשו תשובה\u0004 הרי הם נפטרים מן המיתה? ואולם \u0003השתא מיהת לא עבדי\u0004 \u0005[עכשיו בכל אופן\u0006 עדיין \u0005לא עשו]!\u0006","\u0003אמר ר' אבהו: בפירוש ריבתה תורה חייבי כריתות למלקות, דגמר\u0004 \u0005[שלמד]\u0006 בגזירה שווה \u0003\"לעיני\"\u0004 (\"ונכרתו לעיני בני עמם\" ויקרא כ, יז) \u0003מ\"לעיניך\"\u0004 (\"ארבעים יכנו... ונקלה אחיך לעיניך\" דברים כה, ג). \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003ר' אבא בר ממל: אי הכי\u0004 \u0005[אם כך]\u0006 \u0003חייבי מיתות בית דין נמי נגמר\u0004 \u0005[גם כן נלמדם]\u0006 מגזירה שווה, ממה שכתוב \u0003\"מעיני\"\u0004 (\"אם מעיני העדה נעשתה לשגגה\" במדבר טו, כד) האמור בעבודה זרה, שחייבים עליה מיתת בית דין, \u0003מ\"לעיניך\"\u0004 האמור במלקות, וילקו אף חייבי מיתות בית דין!","ודוחים: \u0003דנין\u0004 לומדים בגזירה שווה \u0003\"לעיני\" מ\"לעיניך\"\u0004 בגלל הדמיון בלשון, \u0003ואין דנין \"מעיני\" מ\"לעיניך\".\u0004 ושואלים: והאם הבדל זה מונע מלדרוש גזירה שווה?","\u0003ומאי נפקא מיניה\u0004 \u0005[מה יוצא מזה]\u0006 מה משנה הבדל קטן זה? \u0003והא תנא דבי\u0004 \u0005[והרי שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל:\u0004 נאמר \u0003\"ושב הכהן\"\u0004 (ויקרא יד, יט) ונאמר \u0003\"ובא הכהן\"\u0004 (במדבר טו, מד), \u0003זו היא שיבה וזו היא ביאה,\u0004 ולמדים גזירה שווה מזה על זה, אף שהמילים כלל אינן זהות!","\u0003ועוד\u0004 אפשר לומר: \u0003לגמר\u0004 \u0005[שנלמד]\u0006 גזירה שווה \u0003\"מעיני\"\u0004 האמור במיתת בית דין \u0003מ\"לעיני\"\u0004 האמור בכריתות, שבין מילים אלו יש דמיון, \u0003דהא גמור\u0004 \u0005[שהרי\u0006 כבר \u0005למד]\u0006 דין מלקות בחייבי כריתות שנאמר בהם \u0003\"לעיני\" מ\"לעיניך\"!\u0004","ומעירים: \u0003קבלה מיניה\u0004 \u0005[קבל ממנו]\u0006 \u0003ר' שמואל בר רב יצחק\u0004 שזה הוא טעם הדבר: מה שלמדים מהכתוב \u0003\"כדי רשעתו\"\u0004 — \u0003משום רשעה אחת אתה\u0004 (בית הדין) \u0003מחייבו, ואי אתה מחייבו משום שתי רשעיות\u0004 — דווקא \u0003ברשעה\u0004 בעונש \u0003המסורה לבית דין הכתוב מדבר,\u0004 אבל עונש שבידי שמים איננו בכלל זה.","\u0003רבא אמר:\u0004 את המחלוקת שבין ר' ישמעאל ור' עקיבא יש להגדיר ולהעמיד באופן זה: אם \u0003אתרו ביה\u0004 \u0005[התרו בו]\u0006 בשעת עבירה שהוא נענש \u0003לקטלא\u0004 \u0005[למיתה]\u0006 — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל,\u0006 ואף ר' ישמעאל, \u0005אינם חלוקים]\u0006 ש\u0003אין לוקה ומת. כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה כגון \u0003דאתרו ביה\u0004 \u0005[שהתרו בו]\u0006 \u0003למלקות\u0004 בלבד, \u0003ר' ישמעאל סבר\u0004 \u0005[סבור]:\u0006 \u0003לאו שניתן לאזהרת מיתת בית דין —\u0004 \u0003לוקין עליו,\u0004 אם התרו בו רק למלקות. \u0003ור' עקיבא סבר:\u0004 שכל \u0003לאו שניתן לאזהרת מיתת בית דין\u0004 — \u0003אין לוקין עליו,\u0004 שאין בו חיוב מלקות כלל, ורק לענין מיתת בית דין נאמר.","ושואלים: \u0003ו\u0004לדעת \u0003ר' עקיבא, אי הכי\u0004 \u0005[אם כך]\u0006 \u0003חייבי כריתות נמי\u0004 \u0005[גם כן]\u0006 נאמר כי \u0003לאו שניתן לאזהרת כרת הוא,\u0004 ולא למלקות! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב מרדכי לרב אשי: הכי\u0004 \u0005[כך]\u0006 \u0003אמר אבימי מהגרוניא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: חייבי כריתות\u0004 כלל \u0003לא צריכי\u0004 \u0005[צריכים]\u0006 \u0003התראה\u0004 בכתוב, כדי להיענש, \u0003שהרי\u0004 המבטל מצוות \u0003פסח ומילה ענש\u0004 עליהם הכתוב בכרת \u0003אף על פי שלא הזהיר,\u0004 ומשום כך נותרת האזהרה שבחייבי כריתות לענין מלקות.","ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003אזהרה\u0004 שנאמרה בחייבי כריתות נאמרה רק \u0003ל\u0004ענין \u0003קרבן,\u0004 שאם עובר בשגגה על הלאו חייב להביא קרבן חטאת, אבל לא ילקה על כך. וראיה לדבר, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003פסח ומילה דלית בהו\u0004 \u0005[שאין בהם]\u0006 \u0003אזהרה לא מייתי\u0004 \u0005[מביאים]\u0006 \u0003קרבן\u0004 אם ביטלו אותם!","ודוחים: \u0003התם לאו היינו טעמא\u0004 \u0005[שם,\u0006 בביטול פסח ומילה, \u0005לא זהו הטעם]\u0006 שאין מביאים קרבן, \u0003אלא משום דאיתקש\u0004 \u0005[שהוקשה,\u0006 הושוותה\u0005]\u0006 \u0003כל התורה כולה\u0004 לענין קרבן חטאת שמביאים על שגגה \u0003לעבודה זרה: מה עבודה זרה\u0004 שהיא דבר שאומרים לו לאדם \u0003שב ואל תעשה\u0004 — מביא עליה קרבן חטאת אם עבר ועשה מעשה בשוגג, \u0003אף כל\u0004 עבירה שיש בה \u0003שב ואל תעשה,\u0004 אם עבר ועשה מעשה בשוגג — חייב עליו חטאת, \u0003לאפוקי הני\u0004 \u0005[להוציא\u0006 את \u0005אלה],\u0006 פסח ומילה, שיש בהן ציווי של \u0003קום עשה,\u0004 והעבירה שהוא עובר היא בהימנעות בלבד.","\u0003רבינא אמר: לעולם\u0004 טעמו של ר' עקיבא לחייב מלקות בחייבי כריתות, הוא \u0003ל\u0004"]]};
